window.__D("text/pelach-harimon/c002",{"p":[[4801940325,"ושרש זה הוא מבחי' עצם שם מ\"ה החדש המאיר בחכ' דווקא שהוא כ\"ח מ\"ה<sup data-n=\"1596\">57</sup> והוא כלי למ\"ה העצמי כו'. וע\"ד העבודה הוא בחי' אה' עצמי' הפועלת בחי' קבעומ\"ש להיות בטל רצונך העצמי שבנה\"א שרצונו ליכלל מצד תוקף העונג ונק' יונתי (שהוא כד מסתכל ז\"א בפנים נק' המל' יונתי ע' ברשימ' הנ\"ל<sup data-n=\"1597\">58</sup> ), אבל כאשר מקבל עליו עומ\"ש שזהו בחי' נעשה קודם לנשמע שזהו ענף מאה' העצמי' המתלבש בחלק המעשה נק' תמתי כו'. וזהו בחי' שוב שאחר הרצוא דרשפי אש דאה' בתענוגים הנ\"ל שזהו המביא להתלבש בימות החול אחרי השבת ונמצא שמוח דחכ' שליט על פנימי' הלב (מדות דיחידה ששרשם מעתיק ואריך) המשפיעים בו והוא מחמת בחי' א\"ק עצמו המתלבש בחכ' דוקא וזהו והחכ' תחי' בעלי' לעשות בחי' שוב במדות דיחידה הנק' בעלי' כו' וד\"ל. וזהו כל המתיישב ביינו מדעת קונו יש בו, פעולת התיישבות המדות דיחידה הנק' יין שזהו מדעת קונו שהוא בחי' א\"ק הנק' בשם קונה שמים וארץ<sup data-n=\"1598\">59</sup> כו' וד\"ל.\n<b>וזהו\"ע</b> כי טובים דודיך מיין<sup data-n=\"1599\">60</sup>, דודים הוא אה' עצמי' הנ\"ל והוא בחי' שמן הטוב המבואר בב\"ז פ' שמיני<sup data-n=\"1600\">61</sup> שהוא חסד דע\"י המלובש בגולגלתא<sup data-n=\"1601\">62</sup> שבזה מלובש בחי' עצמות שם מ\"ה החדש וידוע דאבא אחיד ותליא בחסד זה<sup data-n=\"1602\">63</sup> כו' וכד מסתכל ז\"א במצחא אז נמשך בו מדעת קונו שזהו בחי' ש\"ע נהורין<sup data-n=\"1603\">64</sup> מלשון וישע הפנה<sup data-n=\"1604\">65</sup> להיות משפיע למטה דווקא גילוי א\"ס בעצמו, וזהו אראנו בישע אלקים<sup data-n=\"1605\">66</sup> ש\"ע נהורין המלובשים בי' דחכמה ונק' ישע כו' וד\"ל. וזהו בחי' המילה מל י\"ה<sup data-n=\"1606\">67</sup> שהוא התגלות דחו\"ב המושלים על המדות הפנימי' דיחידה וכן פריעה פר\"ע י\"ה<sup data-n=\"1607\">68</sup> וכן מציצה מצץ י\"ה<sup data-n=\"1608\">*69</sup> ג' מדריגות דמוחין דקטנות ומוחין דיניקה ומוחין דגדלות, ובחי' מילה מוחין דקטנות למשול ברוחו לקבעומ\"ש בתומ\"צ ופריעה פר\"ע י\"ה אותיות עורף<sup data-n=\"1609\">69</sup> שגם בעת הילוכו כל היום בעסק דמו\"מ יהי' בחי' עומ\"ש הנ\"ל, ומציצה הוא",[["1596","57","<b>בחכ'. . כ\"ח מ\"ה</b>: זהר רע\"מ צו כח, א. לד, א."],["1597","58","<b>ברשימ' הנ\"ל</b>: שבהערה 34."],["1598","59","<b>קונה שמים וארץ</b>: לך יד, יט. כב."],["1599","60","<b>כי טובים דודיך מיין</b>: שה\"ש א, ב."],["1600","61","<b>בב\"ז פ' שמיני</b>: סד, ג."],["1601","62","<b>חסד דע\"י המלובש בגולגלתא</b>: ראה ע\"ח שער א\"א שי\"ג, פ\"ו ופ\"ז."],["1602","63","<b>דאבא אחיד ותליא בחסד זה</b>: ראה ע\"ח שער או\"א שי\"ד, פ\"א (בשם הזהר — ראה זהר במדבר קיח, ב)."],["1603","64","<b>ש\"ע נהורין</b>: ראה זהר אד\"ר נשא קכח, ב. ע\"ח שער א\"א שי\"ג, פי\"ד. אוה\"ת מטות ע' א'רעב. המשך תער\"ב ח\"ב ע' א'רה."],["1604","65","<b>וישע הפנה</b>: בראשית ד, ד וברש\"י שם. ראה גם אגה\"ק ס\"ג. מאמרי אדה\"א בראשית ס\"ע רפא. אוה\"ת חנוכה כרך ב ע' רצג. וראה גם לקמן מאמר ד\"ה רפאיני הא' על יד הערה 89. ד\"ה רפאיני תר\"ח על יד הערה 94."],["1605","66","<b>אראנו בישע אלקים</b>: תהלים נ, כג."],["1606","67","<b>המילה מל י\"ה</b>: ראה ת\"ז תכ\"ב סח, א. תו\"א לך יב, א. ביאוה\"ז בראשית ד, ב. סידור שער המילה קמג, ג. תו\"ח מקץ צד, א הערה 2. סהמ\"צ להצ\"צ ח, ב."],["1607","68","<b>פריעה פרע י\"ה</b>: ראה ע\"ח שער האונאה של\"ג, פ\"ג. טעמי המצות [להאריז\"ל] לך סוד מצות מילה ופריעה. ביאוה\"ז בראשית ד, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' פג."],["1608","*69","<b>מציצה. . מצץ י\"ה</b>: ראה גם לקמן מאמר ד\"ה ענין מצות מילה תו\"ר על יד הערה 18."],["1609","69","<b>ופריעה. . אותיות עורף</b>: כשמחלפים אות י באות ו באותיות אהו\"י."]]],[4801940373,"בחי' מצץ י\"ה בגי' ר\"ך אורות הנתוספין על ק\"נ<sup data-n=\"1610\">70</sup> להיות בגי' ש\"ע בחי' ימינך פשוטה לקבל שבים<sup data-n=\"1611\">71</sup> מקור הסליחה מצד כי עם קשה עורף<sup data-n=\"1612\">72</sup> ולכן מציצה הוא בחי' רפואה סליחת עונות להשלים כל הפגמים והחסרונות ובנפש הוא הכח לשוב בתשובה מן ההיפוך, וכ\"ז נמשך בעת המילה שזהו בחי' ג' מיני מוחין מאו\"א קטנות ויניקה וגדלות בבחי' קבלתם מא\"ק דווקא ולכן לא יוכל לימשוך ע\"י אתעדל\"ת במעהמ\"צ רק בעובדא זאת דהסרת הרע דווקא שזהו הבדלה דג' מיני קליפות שנעשה ע\"י מילה ופריעה ואטיפו דדמא<sup data-n=\"1613\">73</sup> כו' או מציצה כמבו' באוה\"ח הק'<sup data-n=\"1614\">74</sup> פ' תזריע<sup data-n=\"1615\">75</sup> כו', (ועד\"ז בל\"ת אחוזתם<sup data-n=\"1616\">76</sup> בי\"ה להיות בבחי' הבדלת הרע כידוע בענין לאו קודם להן<sup data-n=\"1617\">77</sup> כו').\n<b>ועתה</b> י\"ל ענין למנצח תמן מל תמן נצח דהנה ההפרש בין א\"ק לכל הפרצופי'<sup data-n=\"1618\">78</sup> שכולם מתלבשים זב\"ז מבחי' ז\"ת שבהם מחסד ולמטה משא\"כ א\"ק אינו מתלבש רק מבחי' נה\"י שבו והטעם הוא כי כל הפרצופי' הם בערך זל\"ז עד שפרצוף העליון הוא בגדר משפיע לתחתון והתחתון הוא בגדר מקבל ממנו ולכן עצמות המשפיע מתעורר להיות נמשך במקבל לכן יש להמקבל השגה בו כידוע דאחר מ' שנין קאים אדעתי' דרבי'<sup data-n=\"1619\">79</sup> והשגה זאת נק' תפיסא והתלבשות כו' (אבל ג\"ר של פרצוף העליון שהוא בחי' ביטולו במקורו הגבוה ממנו לא יוכל להתגלות במקבל כו'), אבל בבחי' א\"ק שהוא בחי' הרצה\"פ שלמעלה מגדר עונג לגמרי וכידוע דאין טעם לרצון<sup data-n=\"1620\">80</sup> אפילו טעם ועונג כו' שזהו ההתחברות מבחי' העצמי' להיות משפיע ומקבל שאינו ע\"י העונג כי למעלה בעצמותו לא יתכן עונג ושלימות כי הוא שלימותא דכולא<sup data-n=\"1621\">81</sup> רק ההתחברות הוא בדרך רצון פשוט למעלה מן הטעם לגמרי (וע' בס' פרי הארץ<sup data-n=\"1622\">82</sup> כו'), ולהיות בחי' א\"ק ההמשכה מבחי' העצמי' לזאת לא יתלבש רק מבחי' נה\"י שבו בחי'",[["1610","70","<b>ר\"ך אורות הנתוספין על ק\"נ</b>: ראה ע\"ח שער א\"א שי\"ג, פי\"ד. זהר הרקיע בראשית ע' כז [צ\"ל: כח]. לקו\"ת במדבר יא, ד. מסעי צג, סע\"ג."],["1611","71","<b>ימינך פשוטה לקבל שבים</b>: ע\"פ תפלת נעילה."],["1612","72","<b>כי עם קשה עורף</b>: תשא לד, ט. ראה שמו\"ר פמ\"ב, ט. תו\"ח תצוה ח\"ב שעט, ד. וש\"נ."],["1613","73","<b>מילה ופריעה ואטיפו דדמא</b>: ראה ע\"ח שער ק\"נ שמ\"ט, פ\"ו."],["1614","74","<b>באוה\"ח הק'</b>: ראה לקו\"ש ח\"ב ע' 508 סל\"ג."],["1615","75","<b>באוה\"ח הק' פ' תזריע</b>: יב, ג ד\"ה ימול בשר ערלתו."],["1616","76","<b>אחוזתם</b>: כנצ\"ל: אחיזתם."],["1617","77","<b>לאו קודם להן</b>: ראה לקמן מאמר ד\"ה מנין שקושרין לשון של זהורית על יד הערה 156 בשם הבעש\"ט. לקו\"ת פקודי ו, ד. שה\"א ד, ב. מאמרי אדה\"א נ\"ך ע' רלו. וש\"נ."],["1618","78","<b>ההפרש בין א\"ק לכל הפרצופי'</b>: ראה דרושים שבהערה 1. ובסהמ\"צ להצ\"צ כאן ר\"ע יא מציין: וכמ\"ש בדוכתא טובא בע\"ח ומהם בשער תלת רישין [ שער אריך שי\"ג, פ\"ב] ובשער עתיק. ולהעיר מלקו\"ת מסעי צה, סע\"ג ואילך. תו\"ח בא ח\"א צ, א."],["1619","79","<b>דאחר מ'. . אדעתי' דרבי'</b>: ראה ע\"ז ה, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. תו\"ח בשלח ח\"א ריז, ג הערה 418. המשך וככה תרל\"ז ספל\"ה. לקמן מאמר ד\"ה שבת שבתון על יד הערה 30. ד\"ה אם בחוקותי הג' על יד הערה 34."],["1620","80","<b>דאין טעם לרצון</b>: ראה של\"ה ד, ב. מאמרי אדה\"א דברים ח\"א ע' כא. וש\"נ. תו\"ח בא ח\"א פט, ד. וש\"נ."],["1621","81","<b>שלימותא דכולא</b>: ראה עבודת הקודש ח\"א רפ\"ח. דרך אמונה להנ\"ל מהדורת קה\"ת ע' יג ובהנסמן שם. לקו\"ת עקב טז סע\"א. הלשון שלימותא דכולא — ראה ת\"ז בהקדמה (יז, ב)."],["1622","82","<b>בס' פרי הארץ</b>: להרמ\"מ מוויטעפסק פ' לך בסופה ד, א."]]],[4801940418,"חיצוני' דחיצוני' ולא עצמותו כלל שהוא בחי' תוקף האמונה הנמצא בכללות נש\"י למעלה מן הטעם ודעת לגמרי ושוה ומשוה קטן וגדול<sup data-n=\"1623\">83</sup> כי גם למעלה מאיר בחי' נה\"י באצי' ועשי' בהשוואה ממש<sup data-n=\"1624\">84</sup>. והנה ידוע שהחיבור מעליון לתחתון ממשפיע למקבל מז\"ת שבו עצמות המשפיע הוא מצד האהבה המעוררו לזה וזהו בחי' ה\"ח בכל מקום שיש בהם ב' בחי' חסדים סתומים וחסדים<sup data-n=\"1625\">85</sup> מגולים להיות ידוע שמה שהמשפיע מגלה אהבתו הוא רק הארה אבל עצמי' עומק האה' נשאר בהעלם בלבבו וגם גילוי האהבה למקבל אינו רק בעת יחודו עמו אבל בעת שמסתלק ממנו לא נשאר רק רושם האה' מהארה זאת וזהו שאין רק ה\"ח עד הוד עצמו' המשפיע אבל בחי' יסוד כח השופע המתלבש במקבל ונשאר תמיד עמו לא נשאר רק רושם מזה (וזהו המבואר בכהאריז\"ל שרק כללות ה\"ח הוא ביסוד וכללות דכללותם במל' ולא עצמות החסדים כו' וד\"ל), אבל בבחי' א\"ק להיותו למעלה מגדר משפיע ומקבל ואינו מאיר ממנו רק בחי' חיצוני' היא הנותנת שבבחי' חיצוני' זאת מתלבש כל הפנימי' ולא רק הארה, והשפעה זאת היא נמשכת במקבל ג\"כ בבחי' עצמות עד שעי\"ז המקבל אינו נפרד מן המשפיע אפי' בעת שמתרחק מעמו הוא בבחי' דביקות והתקשרות עצמי' כמו בעת יחודו עמו כי בבחי' זאת אין המקום תופס מקום כלל, וזהו\"ע כריתות ברית דשני אוה\"נ<sup data-n=\"1626\">86</sup> להמשיך בחי' עצמי' שלא יפרד אהבתם במשך הזמן וריחוק מקום, וזהו ענין המילה הנק' בשם ברית להיות חבוקה ודבוקה<sup data-n=\"1627\">87</sup> אע\"ג דאנא אזיל הכא והכא דיוקנא אשתאר בך<sup data-n=\"1628\">88</sup> במשפיע וכן במקבל משכונא דילי גבייכו<sup data-n=\"1629\">89</sup> כו' וד\"ל.\n<b>ונמצא</b> שיש כאן ז' חסדים, ה\"ח בעת קירוב המקבל עם המשפיע וב' חסדים בעת ריחוק המקבל שמלובש בו ג\"כ אה' עצמי' המשפיע בלי הסתר כלל ונמצא שכל הז' חסדים מגולים וכ\"א כלול מי' בגי' ע', וזהו תמן מל תמן נצח להיות שההתלבשות הוא מבחי' נצח בחי' חיצוני' דחיצוני' היא הנותנת שמלובש בזה כל הפנימי' ועצמי' שזהו ענין ז' חסדים מגולים בגי' דמל<sup data-n=\"1630\">90</sup> כו' וד\"ל. וזהו ענין על מילה שניתנה בשמינית להיות ידוע שבחי' שם מ\"ה החדש נק' מלך השמיני<sup data-n=\"1631\">91</sup> והטעם לזה להיות כי ידוע דשית אלפי שנין<sup data-n=\"1632\">92</sup> דהוי עלמא המה נכללים בוימ\"ב<sup data-n=\"1633\">93</sup> שבאים בדרך",[["1623","83","<b>ושוה ומשוה קטן וגדול</b>: ע\"פ פיוט (לימים נוראים) ”האוחז ביד מדת משפט\"."],["1624","84","<b>נה\"י באצי' ועשי' בהשוואה ממש</b>: ראה גם סידור כאן קמא, ג. לקו\"ת כאן כא, ג. אוה\"ת כאן ע' תקיד."],["1625","85","<b>וחסדים</b>: אוצ\"ל: וה' חסדים."],["1626","86","<b>אוה\"נ</b>: אוהבים נאמנים."],["1627","87","<b>חבוקה ודבוקה</b>: לשון הושענא אום אני חומה (ליום ג')."],["1628","88","<b>אע\"ג. . דיוקנא אשתאר בך</b>: ראה זהר ויחי רמד, סע\"ב ואילך. סבא משפטים קיד, א."],["1629","89","<b>משכונא דילי גבייכו</b>: ראה זהר פקודי רמא, א. בחוקותי קיד, א. מאמרי אדה\"א נ\"ך ס\"ע פח ואילך. וש\"נ. הנחות תקע\"ז ע' צט וע' רמט."],["1630","90","<b>ע'. . בגי' דמל</b>: ראה ע\"ח שער האונאה של\"ג, פ\"ג. טעמי ושער המצות פ' לך. וראה גם סידור כאן קמא, א (ז' חסדים). לקו\"ת כאן כא, ב (הז' עליונות). אוה\"ת ברכה א'תתקי."],["1631","91","<b>שם מ\"ה החדש נק' מלך השמיני</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ב. פ\"ג. תו\"א ויחי קג, ב. מאמרי אדה\"א דברים ח\"ד ע' א'תפב."],["1632","92","<b>דשית אלפי שנין</b>: ראה ר\"ה לא, א. מאמרי אדה\"א בראשית ע' נג. וש\"נ."],["1633","93","<b>דשית אלפי שנין. . בוימ\"ב</b>: ראה מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."]]],[4801940459,"המשכה מלמעלמ\"ט בבחי' התלבשות בהעלם בכדי לברר בירורים וזהו בחי' ו\"ד דחכ' הנ\"ל שהוא בחי' שם מה המברר ב\"ן בג' מדריגות דטנת\"א אותיות שבשם ב\"ן מברכים<sup data-n=\"1634\">94</sup> ע\"י טנת\"א שבו כל הבחי' בדוגמתא. והנה יום השבת שנק' שביעי הוא בחי' העלאה היפוך המשכה שזהו בחי' עליות שם ב\"ן להתכלל בשם מ\"ה שעי\"ז נגלה בחי' שם מה ושם ב\"ן בטל ונכלל בו ואז מתגלה שם מ\"ה העצמי בחי' י' דחכ' ג\"כ בג' מדריגות דטנת\"א שזהו ג' מיני אה' המתגלים בשבת בג' תפלות וסעודות אה\"ע ואה\"ר ואה' בתענוגים ובחי' זאת נק' יום השביעי כי יום הוא בחי' גילוי ושית יומין המה בחי' גילויי' לפעול ירידה והמשכה ויום השביעי הוא בחי' גילוי הפועל העלאה, אבל בחי' זאת דאתעדל\"ע שנמשך שלא ע\"י אתעדל\"ת כלל שנמשכת תמיד רק במקום טהור מרע הוא עצמות שם מ\"ה החדש ונק' יום השמיני להיותו למעלה גם מכל העליות שאחרי הירידות כי אינו בגדר מקום שיהי' שייך בו עלי' וירידה וזהו על מילה שניתנה בשמיני דווקא והיא מתלבשת בחיצוני' שנק' נצח ולכן א' ע\"ז דווקא מל נצח ולכן מילה למעלה משבת ודוחה שבת<sup data-n=\"1635\">95</sup> עד שמלאכות מותרים בה מצד שנתגלה בחי' הקב\"ה שהכל שלו וכמ\"ש מוריד גשמים אפי' בשבת<sup data-n=\"1636\">96</sup> כו' כן במילה מותרים כל המלאכות אפי' בשבת כו' וד\"ל.",[["1634","94","<b>מברכים</b>: כנצ\"ל: מבררים."],["1635","95","<b>מילה. . ודוחה שבת</b>: שבת קל, א (במשנה). קלב, א."],["1636","96","<b>מוריד גשמים אפי' בשבת</b>: ראה ב\"ר פי\"א, ה. לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב ובהערה 17."]]],[4801940099,"<b>אור ליום פ' הנ\"ל שנת כת\"ר</b>\n<b>סוד</b> הוי'<sup data-n=\"1637\">1</sup> ליריאיו<sup data-n=\"1638\">2</sup> זה מצות מילה, שהיתה גנוזה עשרים דור [היינו מאדם ועד נח ועד בכלל עשר דורות ומשם ועד אברהם<sup data-n=\"1639\">3</sup> ועד בכלל עשר דורות כו'] וניתנה לאברהם שהי' ירא ה' כו' [... כי הגם שמדתו מדת האהבה<sup data-n=\"1640\">4</sup> מ\"מ כלולה בה מדת היראה, והגם שאחר העקידה זכה למדת יראה מצד התכללותו בבחי' יצחק ע\"י",[["1637","1","<b>סוד הוי' ליריאיו</b>: הנחת ר\"ה מדרוש כ\"ק אדמו\"ר הצ\"צ.\nלמאמר זה ראה פלח הרמון לך מא, ב ואילך. אוה\"ת בהעלותך ע' שפז ואילך. וע' שצג ואילך.\nמאמר זה הובא לקמן במאמר ד\"ה שלאח\"ז גדולה מילה תר\"כ.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["1638","2","<b>סוד הוי' ליריאיו</b>: תהלים כה, יב. ראה תנחומא לך יט. אגדת בראשית פט\"ז. וראה ב\"ר פמ\"ט, ד. ילק\"ש תהלים עה\"פ (רמז תשב)."],["1639","3","<b>מאדם ועד נח. . אברהם</b>: אבות פ\"ה, מ\"ב."],["1640","4","<b>לאברהם. . מדת האהבה</b>: ראה זהר לך פה, א. ועוד. ואתחנן רסב, ב. סידור שער התפילין יב, א ואילך. אמ\"ב שם קלו, ד ואילך. וראה גם לקמן ביאור למאמר ד\"ה והתהלכתי בתוככם תר\"ב ובהערה 26."]]],[4801940164,"העקידה כמ\"ש כי עתה ידעתי<sup data-n=\"1641\">5</sup> כי ירא אלקים אתה כו' היינו יראה פנימי' אבל בחי' יראה תתאה מצד האהבה הי' לו בתחלה כי האוהב ירא שלא יפגום אהבתו<sup data-n=\"1642\">6</sup> כו' וד\"ל].\n<b>והנה</b> מתחלה יש להבין מהו סוד הוי', הנה כתי' כי אל דעות הוי'<sup data-n=\"1643\">7</sup> שיש שני דעות ד\"ע וד\"ת, ד\"ת הוא מאין ליש שהנברא הוא בחי' מציאות דבר מה והאור האלקי נק' בשם אין ע\"ש שהוא שופע בהעלם וזהו דעה של הנבראים, אך בחי' ד\"ע הוא כמ\"ש קמי' שהוא בחי' היש האמיתי מקור הנבראים וכולא קמי' כלא חשיב<sup data-n=\"1644\">8</sup> אך כ\"ז הוא מאצילות לבריאה וב' דעות אלו הוא בחי' הוי' ואלקים כו'. אך בהוי' גופא יש שני בחי' סתים וגלי' [... היינו ע\"ס דאצי' הם בחי' גלי' דהוי' והוא בחי' הוי' שאחר הפסיק טעמי'<sup data-n=\"1645\">9</sup>, אבל יש בחי' הוי' שקודם הפסיק טעמי', והוא בחי' ע\"ס הגנוזות<sup data-n=\"1646\">10</sup> במאציל. אך בזה יש כמה מדריגות כי המאציל נק' כתר ויש כתר הפרטי באצילות שג\"כ נק' מאציל לגבי אצילות כו', אך יש בחי' כתר הכללי דא\"ק. והנה הע\"ס דאצילות נק' דעת תחתון מאין ליש היינו שהם מקור לנבראים לכן נק' בחי' יש מקור הנבראים, אך בחי' אוא\"ס שבכתר שמלובש בהם בהעלם נק' אין, וזהו מאין ליש, אבל עצמות הכתר הוא יש האמיתי ובו כלולים כל הי' ספירות דאצילות לכן הם בחי' אין כלא וכן עד\"ז כתר הפרטי נק' ד\"ת לגבי כתר כללי דא\"ק, וכן עד\"ז כתר דא\"ק הוא לאחר הצמצום הוא בחי' ד\"ת לגבי אוא\"ס שברצה\"פ שלפני הצמצום שעלה ברצונו להיטיב ואנא אמלוך, וכן בחי' רצה\"פ להיטיב ואנא אמלוך כיון שהם מקור להשפעה הגם שהם בבחי' א\"ס נק' ד\"ת לגבי שעשועי המלך בעצמותו<sup data-n=\"1647\">11</sup> שהוא גילוי אור עצמותו שאינו מקור להשפעה כלל ונק' יש האמיתי, ובכאן יתפרש יש אמיתי אמיתת היש ולא בחי' מקור ובו כלול בחי' מקור להשפעה והיינו רעדכ\"ר<sup data-n=\"1648\">12</sup> וכההוא דהוי קבדח טובא<sup data-n=\"1649\">13</sup> ואי הוי שאיל מיני'<sup data-n=\"1650\">14</sup> כו' ובחי' זאת נק' אין דכלא חשיב",[["1641","5","<b>כי עתה ידעתי</b>: וירא כב, יב. ראה גם אגה\"ק סי\"ג. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקנד. פרשיות התורה ח\"א ע' קל. לקו\"ת ואתחנן ח, ב. בראשית לח, ב. פלח הרמון לך כאן מא, ב."],["1642","6","<b>האוהב ירא שלא יפגום אהבתו</b>: ראה תו\"ח שם."],["1643","7","<b>כי אל דעות הוי'</b>: שמו\"א ב, ג. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. לעיל ע' קיב ובהערה 86."],["1644","8","<b>וכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה פ\"א (ז, רע\"א). מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1645","9","<b>הוי'. . הפסיק טעמי'</b>: תשא לד, ו. זהר אד\"ר נשא קלח, רע\"א. ראה הנסמן במאמרי אדה\"א נ\"ך ע' תקעז. תו\"ח בשלח ח\"א קנז, ב הערה 361."],["1646","10","<b>ע\"ס הגנוזות</b>: ראה פרדס שער סדר האצי' ש\"ה, פ\"ד. שער הצחצחות שי\"א. וראה שם פ\"ג. הנסמן במאמרי אדה\"א דברים ח\"א ע' שמו־ שעה\"י — לקו\"ב — קפט, ג-ד הערה 2."],["1647","11","<b>שעשועי המלך בעצמותו</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. קונטרסים ע' שמה ובהנסמן בהנ\"ל. וראה גם לקמן ד\"ה את שבתותי תרי\"ב ובהערה 130."],["1648","12","<b>רעדכ\"ר</b>: ראה זהר ספדצ\"נ תרומה קעו, ב. תו\"ח בראשית לו, ג הערה 23. תצוה ח\"ב שעו, ג."],["1649","13","<b>דהוי קבדח טובא </b>: הלשון — ראה ברכות ל, ב. ז\"ח מדהנ\"ע בראשית י, ג. בהערה הבאה."],["1650","14","<b>דהוי קבדח טובא ואי הוי שאיל מיני'</b>: לשון הרגיל בכתבי ר\"ה — ראה שבת עז, ב. לעיל ע' עו הערה 14."]]],[4801940223,"כו' משא\"כ כאשר עלה ברצונו להיטיב שנעשה מקור להשפעה והעונג נעלם בו נק' מאין ליש כו' וד\"ל. ..]. וזהו סוד הוי' שהוא הסתום שבו כו'.\n<b>והנה</b> ע\"י מצות מילה נמשך בחי' סתים דהוי' שהוא למע' מן החכ' ונגלה בנפש וזהו סוד הוי' [כידוע דגדולה מילה<sup data-n=\"1651\">15</sup> שנכרתו עליה י\"ג בריתות שהם י\"ג ת\"ד<sup data-n=\"1652\">16</sup> שהם למע' מן החכ', ונמשך ע\"י מצות מילה כו'], וזהו הטעם ג\"כ שהיתה גנוזה עשרים דור כי עשרי\"ם בגימ' כתר<sup data-n=\"1653\">17</sup> כו', ועוד כי הכתר נק' עשרים להיותו כולל ע\"ס דאו\"י וע\"ס<sup data-n=\"1654\">19</sup> דאו\"ח<sup data-n=\"1655\">18</sup> וזהו כ' דכתר שכולל עשרים בחי' הנ\"ל. וזהו שהיתה גנוזה עשרים דור כי כמו למע' כאשר צריך להתגלות סוד הוי' שהוא פנימי' דשם הוי' וסתים שבו נגלה ע\"י הכתר שהוא ממוצע<sup data-n=\"1656\">20</sup> בין המאציל לנאצלים ועל ידו נגלה בחכמה שהוא גלי' דהוי', כן למטה נמשך סוד הזה ונגנז עשרים דור [... שהם ג\"כ כנגד עשרים בחי' שבכתר מאדם ועד נח כנגד ע\"ס דאו\"י ומנח ועד אברהם<sup data-n=\"1657\">21</sup> כנגד ע\"ס דאו\"ח כמ\"ש במ\"א וד\"ל<sup data-n=\"1658\">22</sup>. ..]. וזהו ג\"כ ענין סוכה שהיא גבוה למעלה מעשרים אמה פסולה<sup data-n=\"1659\">23</sup>, כי חג הסוכות הוא שמונה ימים והוא בחי' אחת עם המילה כנ\"ל במאמר תנו רבנן<sup data-n=\"1660\">24</sup> כו' והוא בחי' המשכה מלמעלה מן החכ' שזהו ע\"י הכתר הממוצע שהוא בחי' עשרים כנ\"ל משא\"כ בחי' שלמעלה מעשרים שהוא מה שלא נתלבש בכתר הממוצע לא שלטא בי' עינא<sup data-n=\"1661\">25</sup> בחי' ראי' דחכ' כו' וד\"ל.\n<b>והנה</b> מ\"ש סוד הוי' ליריאיו תרי משמע היינו כי מתחלה נמשך בחי' סוד זה שהוא בחי' הוי' דד\"ע כנ\"ל בבחי' חכ\"ע שהוא בחי' יראה עילאה ואח\"כ נמשך מחכ\"ע לחכ\"ת שבמל' שהוא בחי' יראה תתאה. אך דרך ההמשכה מחכ\"ע לחכ\"ת ע\"ז",[["1651","15","<b>דגדולה מילה</b>: נדרים לא, ב (במשנה). וראה לקו\"ש לך כרך כה ע' 54 ואילך ובהערה 5."],["1652","16","<b>י\"ג בריתות שהם י\"ג ת\"ד</b>: ראה גם סידור שער המילה קמט, ד ואילך. לקו\"ת עקב טו, ב [ושם מציין ללקו\"ת — טעמי המצות להאריז\"ל — פ' קדושים אזהרת שעטנז. וראה שער המצות שם. שער מאמרי רשב\"י לאדר\"ז (רפד, א). ע\"ח שער הולדת או\"א וזו\"ן שט\"ז, פ\"ה]. לקמן מאמר ד\"ה גדולה מילה תר\"כ ובהערה 16."],["1653","17","<b>עשרי\"ם בגימ' כתר</b>: ראה ת\"ז מנטובה בהקדמה ח, רע\"א: עשרים כתר. מאו\"א מערכת כתר אות לו וביאיר נתיב שם. מאמר ד\"ה באתי לגני תש\"ל (קונט' יו\"ד שבט תש\"נ — סה\"מ מלוקט ד ע' קלט) פ\"ה הערה 44: ”ראה תורת העולה להרמ\"א ח\"א פ\"ד (ו, ג). לקו\"ת שה\"ש לה, ג. קהלת יעקב בערכו\" [מערכת עשרים]. ספר הערכים חב\"ד מערכת אותיות התורה אות כ ע' ע הערה 25."],["1654","19","<b>ע\"ס דאו\"י וע\"ס דאו\"ח</b>: ראה שה\"א לה, א הערה 2."],["1655","18","<b>הכתר נק' עשרים. . ע\"ס דאו\"י וע\"ס דאו\"ח</b>: ראה סידור שחרית מו, ג. פיה\"מ פקס\"א קט, סע\"ג. מאמרי אדה\"ז תק\"ע ע' קלא. קה\"י וספר הערכים (ע' עב הערה 38) שבהערה שלפנ\"ז. לקמן מאמר ד\"ה והתהלכתי תרכ\"ב על יד הערה 101."],["1656","20","<b>הכתר שהוא ממוצע</b>: ראה ע\"ח (ש' דרושי אבי\"א) שמ\"ב, פ\"א. תו\"ח שמות ח\"א יא, ג הערה 509."],["1657","21","<b>מאדם ועד נח. . אברהם</b>: ראה גם פלח הרמון כאן מא, סע\"ב ואילך."],["1658","22","<b>וד\"ל</b>: ב: באריכות כו' וד\"ל."],["1659","23","<b>סוכה. . מעשרים אמה פסולה</b>: סוכה ב, א (במשנה)."],["1660","24","<b>כנ\"ל במאמר תנו רבנן</b>: [הוא הדרוש שנאמר לפנ\"ז — ראה לקמן ברשימת הכת\"י כאן) אוה\"ת חנוכה כרך ב ע' 608. פלח הרמון חנוכה צט, ד."],["1661","25","<b>לא שלטא בי' עינא</b>: סוכה ב, א."]]],[4801940276,"מורה אותיות סוד כי ההמשכה הוא ע\"י תפארת ויסוד, והנה תפארת הוא בחי' ו' רברבי<sup data-n=\"1662\">26</sup> ע\"ש שבו מאיר מוחין דגדלות מפנימי' הכתר לכן כל בחי' שבו כלול מי' ונעשה מספר ששים שזהו אות הס'<sup data-n=\"1663\">27</sup> שבתיבת סוד כו' [... כי מוחין דגדלות מורה על התגלות כל הפרטים מהעלם אל הגילוי, וקטנות מורה על העלם כל הפרטים כאשר לא באו לידי גילוי כענין בוצין בוצין מקטפי' ידיע'<sup data-n=\"1664\">28</sup> שניכר שיהי' חכם ואעפי\"כ לא יוכל להתחכם מחמת שכל פרטי החכ' שבו נעלמים במקורם כו' וד\"ל. ..] ונק' ארז אשר בלבנון<sup data-n=\"1665\">29</sup> [... כי לבנון הוא בחי' מוחין הנמשכים בו מבחי' פנימיות הכתר כנ\"ל וד\"ל] והוי\"ו הוא בחי' יסוד ו' זעירא<sup data-n=\"1666\">30</sup> מצד שלא נגלה בו כל הפרטים הפנימים הכלולים בו [... כנ\"ל שזהו בחי' קטנות כו'. ..] ולכן הוא בבחי' ו' בלבד וזהו אזוב אשר בקיר<sup data-n=\"1667\">31</sup>, ועל ידו נמשך ונקלט סוד הזה במל' שע\"ז מורה אות הד'<sup data-n=\"1668\">32</sup> דסוד שהוא בחי' דוד מרכבה למדת המלוכה<sup data-n=\"1669\">33</sup> כו' וד\"ל. ולכן לוקחין עץ ארז ואזוב לטהר את המצורע<sup data-n=\"1670\">34</sup> כו' [... כי נגע הוא סגירו דנהורא עילאה<sup data-n=\"1671\">35</sup> כמ\"ש בזהר והיינו הסתלקות אור חכ\"ע מבחי' המל' שזהו ע\"י פגם לה\"ר<sup data-n=\"1672\">36</sup> שפגם בדיבור וממילא נסתלק מן הנשמה כח הראי' דחכ'<sup data-n=\"1673\">37</sup> שהוא רואה את הנולד<sup data-n=\"1674\">38</sup> מאין ליש ע\"י כח מ\"ה<sup data-n=\"1675\">39</sup> שבנפשו כי בחושך לא יוכל לראות [... כידוע דאור הראי' אינו מאיר בעצם רק כאשר מקבל מתחלה ניצוץ השמש<sup data-n=\"1676\">40</sup> בתוכו<sup data-n=\"1677\">41</sup> ] וכיון שנסתלק אור חכ\"ע משרשו במדת המלוכה ממילא לא יוכל לראות כו'<sup data-n=\"1678\">42</sup> וזהו תורת המצורע תורתו של מוציא שם רע<sup data-n=\"1679\">43</sup> כו', אך ביום טהרתו והיינו כאשר חזר בתשובה אז לוקחין עץ ארז ואזוב שהוא כנגד ת\"ת",[["1662","26","<b>תפארת. . ו' רברבי</b>: ראה זהר אחרי עד, ב. ע\"ח שער הולדת או\"א וזו\"ן שט\"ז, ספ\"ו. מאו\"א מערכת ו. הערה הבאה."],["1663","27","<b>ו' רברבי. . הס'</b>: ראה גם אוה\"ת בהעלותך ס\"ע שפז ואילך. ע' שצד ואילך. ראה ע' תשעו."],["1664","28","<b>בוצין בוצין מקטפי' ידיע'</b>: ברכות מח, א. ראה גם סידור ערב שבת קסד, ד. מאמרי אדה\"א קונטרסים ע' רז."],["1665","29","<b>ארז אשר בלבנון</b>: ע\"פ מל\"א ה, יג."],["1666","30","<b>יסוד ו' זעירא</b>: ראה זהר אחרי שם. ע\"ח שם. מאו\"א מערכת ו ס\"א וביאיר נתיב שם."],["1667","31","<b>אזוב אשר בקיר</b>: ע\"פ מל\"א שם."],["1668","32","<b>במל'. . הד'</b>: ראה זהר רע\"מ פינחס רנז, א. ת\"ז סתמ\"ב. תמ\"ז."],["1669","33","<b>דוד מרכבה למדת המלוכה</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["1670","34","<b>עץ ארז ואזוב לטהר את המצורע</b>: מצורע יד, ד. ראה גם אוה\"ת בהעלותך ע' שפח."],["1671","35","<b>נגע הוא סגירו דנהורא עילאה</b>: ראה זהר תזריע מט, ב. ביאוה\"ז שם עב, א. עג, ב. תו\"ח שמות ח\"א מב, ג הערה 253."],["1672","36","<b>נגע. . פגם לה\"ר</b>: ראה ערכין טז, א. רמב\"ם סוף הל' טומאת צרעת. פיה\"מ נגעים פי\"ב, מ\"ה. מו\"נ ח\"ג פמ\"ז. רש\"י תזריע יג, מו. מצורע יד, ד. ועוד."],["1673","37","<b>דחכ'</b>: ניתוסף ע\"פ ב."],["1674","38","<b>דחכ'. . את הנולד</b>: ראה תמיד לב, א. תניא פמ\"ג. מאמרי אדה\"א דברים ח\"א ע' רכא. וש\"נ. שע\"ת עא, ג ובהערה 23. תו\"ח תצוה ח\"ב שכט סע\"ד ואילך."],["1675","39","<b>דחכ'. . כח מ\"ה</b>: זהר רע\"מ צו כח, א. לד, א."],["1676","40","<b>דאור הראי'. . מקבל. . השמש</b>: ראה שבילי אמונה — לר' מאיר אבן אלדבי — הנתיב הרביעי ד\"ה וחוש הראות (ע' 58). לקו\"ב לשעה\"י קסח, ב ואילך. תו\"ש ע' 76."],["1677","41","<b>בתוכו</b>: ב ניתוסף: כמבואר בספרי מחקרים."],["1678","42","<b>כו'</b>: ב: כו' וד\"ל."],["1679","43","<b>תורת המצורע. . רע</b>: מצורע יד, ב. ראה ערכין טו, ב."]]],[4801940326,"ויסוד ועל ידיהם מחזירים אור חכ\"ע במל'<sup data-n=\"1680\">44</sup> ואז יוכל לראות בכח מ\"ה שבנפש את הנולד מאין ליש כו' וד\"ל. ..].\n<b>וזהו</b> בזאת יבא אהרן אל הקדש<sup data-n=\"1681\">45</sup> ואמר במדרש זכות מצות מילה<sup data-n=\"1682\">46</sup> נכנסת עמו שנאמר<sup data-n=\"1683\">47</sup> זאת בריתי<sup data-n=\"1684\">48</sup>, כי ענין הקודש האמור כאן הוא בחי' קה\"ק שהוא למע' מן החכ' כמאמר והבדילה הפרכת<sup data-n=\"1685\">49</sup> בין הקדש ובין קה\"ק שזהו בחי' פרסא<sup data-n=\"1686\">50</sup> המפסיק בין כתר לחכ' ולכן אומר שע\"י מה יוכל לבא אל הקדש שהוא בחי' הכתר היינו ע\"י מצות מילה ששרשה בכתר כנ\"ל וד\"ל. ובזה יובן ג\"כ<sup data-n=\"1687\">51</sup> מאמר השני בזכות מצות מילה זכה לע' נפש וגם לע' זקנים<sup data-n=\"1688\">52</sup> וע' ימים<sup data-n=\"1689\">53</sup> טובים<sup data-n=\"1690\">54</sup> כו'. כי הנה ענין מילה הוא המשכת סוד הוי' ע\"י י\"ג מדה\"ר כנ\"ל, ומבואר במ\"א שבחי' יעקב הוא בחי' מדה\"ר באצילות<sup data-n=\"1691\">55</sup> וא\"כ בזמן האבות נמשך סוד הוי' הנ\"ל באצילות<sup data-n=\"1692\">56</sup>, אך בחי' השבטים הם בבריאה לכן הם בחי' רח\"ר על עולמות הנבראים ולכן ע\"י נמשך סוד הוי' בעולם הבריאה כו' [... ובזה אפ\"ל למה תתענו ה' מדרכיך<sup data-n=\"1693\">57</sup> תקשיח לבנו מיראתיך כו' שלכאורה הוא תמוה האיך אפ\"ל שהקב\"ה מקשיח לבנו מיראתו ית' אדרבה הקב\"ה עוזרו<sup data-n=\"1694\">58</sup> כו' וכדכתי' עד יערה עלינו כו'<sup data-n=\"1695\">59</sup> שתמיד הוא מעורר אותנו באתעדל\"ע הגם שאין אתעדל\"ת וכמ\"ש הפייטן בשורך דלות מעשים<sup data-n=\"1696\">60</sup> קרב צדק מאיליך [ע'<sup data-n=\"1697\">61</sup> בפרד\"ס<sup data-n=\"1698\">62</sup> ], אלא הכוונה על אהוי\"ר שבאצילות שנק' דרכיך ויראתיך והם מתעלמים ע\"י הפרסא, שזהו כח ה' שהפרסא הפסיק<sup data-n=\"1699\">63</sup> הנ\"ל וזהו למה תתענו",[["1680","44","<b>במל'</b>: ב: משרשו במדת המלוכה."],["1681","45","<b>בזאת יבא אהרן אל הקדש</b>: אחרי טז, ג."],["1682","46","<b>זכות מצות מילה</b>: ראה שמו\"ר פל\"ח, ח. ראה גם סה\"מ תרכ\"ז ע' קצו. וש\"נ."],["1683","47","<b>שנאמר</b>: בג ניתוסף: בה."],["1684","48","<b>זאת בריתי</b>: לך יז, י."],["1685","49","<b>והבדילה הפרכת</b>: תרומה כו, לג [ושם: הפרוכת לכם. ב: לכם הפרוכת]. ראה גם לקמן על יד הערה 75. תו\"ח בשלח ח\"א קצ, ג ובהערה 302."],["1686","50","<b>הפרכת. . פרסא</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' שכה. וש\"נ. המשך זאת חנוכת המזבח תר\"ם פ\"י. וש\"נ."],["1687","51","<b>ג\"כ</b>: ג ניתוסף: ענין."],["1688","52","<b>בזכות מצות מילה. . לע' זקנים</b>: ראה הנסמן בהערה 2."],["1689","53","<b>וע' ימים טובים</b>: באוה\"ת לך כרך ד ע' תשטז: מצות מילה. . לע' זקנים, כי ע' זקנים איתא במדרש [ראה בהערה הבאה] שהוא כנגד ע' יו\"ט שיש בשנה."],["1690","54","<b>וע' ימים טובים</b>: ראה במדב\"ר פי\"ד, יב. ילקו\"ש בהעלותך יא, טז (רמז תשלו). בה\"ג סוף הל' סופרים. אוה\"ת בהעלותך ע' שצא ואילך. וראה גם פלח הרמון לך כאן מא, סע\"ג ואילך. וירא נה, א."],["1691","55","<b>יעקב. . מדה\"ר באצילות</b>: ראה זהר לך פז, ב. תניא פמ\"ה. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקעט ובהנסמן במ\"מ לשם."],["1692","56","<b>באצילות</b>: ב ניתוסף: ע\"י מעשיהם ושרש נשמתם."],["1693","57","<b>למה תתענו ה' מדרכיך</b>: ישעי' סג, יז. ראה גם לקמן מאמר ד\"ה והניף הכהן אותם הב' על יד הערה 44."],["1694","58","<b>הקב\"ה עוזרו</b>: קדושין ל, ב. סוכה נב, ב. ראה תניא רפי\"ג."],["1695","59","<b>עד יערה עלינו כו' </b>[ב: רוח ממרום]: ישעי' לב, טו. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ו וע' ח."],["1696","60","<b>בשורך דלות מעשים</b>: פיוט אל תעש עמנו כלה בסדר עבודה ליו\"כ [ושם: דלות מעשים בשורך]."],["1697","61","<b>ע' בפרד\"ס</b>: שער מהות והנהגה ש\"ח, ספ\"כ."],["1698","62","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט ובהערה 293."],["1699","63","<b>שהפרסא הפסיק</b>: ב: שהפסיק הפרסא. ג: כתב: שהפרסא הפסיק ומחקו ותיקן ממעל לשורה: שהפסיק הפרסא."]]],[4801940374,"מדרכיך שהוא אה' דאברהם<sup data-n=\"1700\">64</sup> הנק' דרך כמ\"ש למען יצוה כו' ושמרו דרך הוי'<sup data-n=\"1701\">65</sup>, תקשיח מיראתך יראה פנימי' שבאצי' שהוא בחי' יצחק וע\"י הפרסא העלים אותם והרחיק אותנו נשמות<sup data-n=\"1702\">*66</sup> דבריאה מהם, וע\"ז אמר שוב למען עבדיך שבטי נחלתיך כי ע\"י השבטים שהם בחי' רח\"ר<sup data-n=\"1703\">66</sup> על עולמות הנבראים כנ\"ל שוב<sup data-n=\"1704\">*67</sup> להאיר סוד הוי'<sup data-n=\"1705\">67</sup> גם עלינו נשמות הנבראים כו' וד\"ל. ..]. אך בחי' ע' נפש הם יוצאי ירך יעקב הם בחי' המשכות רח\"ר על נפשות שהם ממדריגות תחתונות דעשי' לכן הם ממשיכים סוד הוי' הנ\"ל אפי' על נפש דעשי' כו' [... ולכן נק' יוצאי ירך כי הירך הוא בחי' נה\"י<sup data-n=\"1706\">68</sup> הממשיך מוחין במל'<sup data-n=\"1707\">69</sup> ואימא תתאה מקננא באופן<sup data-n=\"1708\">70</sup> שהוא עולם העשי' כו' וד\"ל. ..]. וזהו שבזכות מצות מילה זכה להמשכת סוד הוי' גם בעשי' שזהו בחי' ע' נפש [... כי סוד בגימ' ע'<sup data-n=\"1709\">71</sup> כו'. ..].\n<b>אך</b> ע\"י ע' נפש אינו נמשך סוד הוי'<sup data-n=\"1710\">72</sup> למטה כמו למע' רק הארה מבחי' אצילות כו' אך אח\"כ ע\"י ע' זקנים נמשך סוד הוי' הנ\"ל בעשי' כמו באצילות כו' [... והטעם לזה כי זקן נק' שקנה חכ'<sup data-n=\"1711\">73</sup> ממקורו והיינו שמאיר בשכלו מקור החכ' הנק' משכיל כמו שהוא מצד זיכוך הקרומי' המקיפים את המוח לזאת נגלה אצלו האמת כמ\"ש בלי יגיעה ופלפול כלל. וזהו ענין האשכלות<sup data-n=\"1712\">74</sup> כו' ולמעלה היינו גילוי החכ\"ס בחכ\"ע כמ\"ש ואין הפרסא מסתרת כלל. אך צריך עוד תנאי לזה, כי הנה ידוע בענין והבדילה הפרכת שיש פרסא מפסיק בין חכ' שבכתר לכתר שבכתר<sup data-n=\"1713\">75</sup> כידוע דעצם הרצון אין טעם לרצון<sup data-n=\"1714\">76</sup> אפי' טעם הכמוס, לזה צריך בחי' משה שהוא ענין<sup data-n=\"1715\">77</sup> שבעים איש ולו נאמר אספה לי<sup data-n=\"1716\">78</sup> היינו שיקבץ אותם בתכלית האחדות כו' ויגביהם לעצמות הרצון<sup data-n=\"1717\">79</sup> כי שרשו הוא משם כמו שנאמר בו כי מן המים משיתיהו<sup data-n=\"1718\">80</sup> מים עליונים שמעל לרקיע הנ\"ל שע\"ג החכ' שבכתר לכן בכחו לאסוף אותם, ועי\"ז נגלה עצמו' ההעלם כמ\"ש למע' ואז ממילא נגלה למטה ג\"כ עצמות ההעלם שבאצילות",[["1700","64","<b>מדרכך. . דאברהם</b>: ראה גם תו\"א ויצא כד, א. תו\"ח ויצא קעז, א."],["1701","65","<b>למען יצוה. . דרך הוי'</b>: וירא יח, יט [ושם למען אשר יצוה]."],["1702","*66","<b>נשמות</b>: ב: נש\"י. ג: כתב: נשמות ומחקו ותיקן ממעל: נש\"י."],["1703","66","<b>רח\"ר</b>: ב ניתוסף: דבריאה."],["1704","*67","<b>שוב</b>: בג: ישוב."],["1705","67","<b>הוי'</b>: ג: ניתוסף: הנ\"ל. וראה בסמוך בפנים."],["1706","68","<b>הירך הוא בחי' נה\"י</b>: ראה אוה\"ת וישלח ע' 486. ויקרא ע' ו. ואתחנן ע' קיד."],["1707","69","<b>נה\"י הממשיך מוחין במל'</b>: ראה ע\"ח שער תקון הנוקבא של\"ד, פ\"ב כלל ו. שער כסה\"כ שמ\"ו, פ\"ה. פע\"ח שער ק\"ש שעהמ\"ט שט\"ז, פ\"ג."],["1708","70","<b>ואימא תתאה מקננא באופן</b>: ראה ת\"ז ת\"ו (כג, א)."],["1709","71","<b>סוד בגימ' ע'</b>: מדרשים שבהערה 2."],["1710","72","<b>סוד הוי'</b>: ב: בחי' סוד הוי' הנ\"ל."],["1711","73","<b>זקן נק' שקנה חכ'</b>: תו\"כ קדושים יט, לב. קדושין לב, ב. ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' תשמ. תו\"ח משפטים ח\"ב ש, ב ואילך."],["1712","74","<b>האשכלות</b>: סוטה מז, סע\"א. סע\"ב."],["1713","75","<b>פרסא. . לכתר שבכתר</b>: ראה לעיל הערה 49."],["1714","76","<b>אין טעם לרצון</b>: ראה של\"ה ד, ב. מאמרי אדה\"א דברים ח\"א ע' כא. וש\"נ. תו\"ח בא ח\"א פט, ד. וש\"נ."],["1715","77","<b>ענין</b>: ב: ע\"ג."],["1716","78","<b>אספה לי</b>: בהעלותך יא, טז."],["1717","79","<b>הרצון</b>: שם ניתוסף: [וזהו אספה לי וד\"ל]."],["1718","80","<b>כי מן המים משיתיהו</b>: שמות ב, י. ראה מאמרי אדה\"א שמות ח\"ב ע' שצד ואילך. וש\"נ. תו\"ח שמות ח\"א מג, א. וש\"נ."]]],[4801940419,"עד עשי' גשמי'<sup data-n=\"1719\">81</sup> כו' וד\"ל. ..]. אך כ\"ז הי' בזמן הבית אך בזמן הגלות אין לנו סנהדרין כו'<sup data-n=\"1720\">82</sup> [... ולזה הי' בזמן הבית יחוד פב\"פ בתמידות. ..] אך בשבתות וימים טובים שהם ע' כי נ\"ב שבתות בכל שנה ע\"י העיבור וי\"ח ימים טובים הם מדאורייתא כי ימי הפסח שבעה וימי הסוכות שמנה ושבועות ור\"ה ויוהכ\"פ שלשה ימים הם י\"ח בס\"ה ע' לכן על ידם נמשך ג\"כ סוד הוי' למטה כמו למע' אף בזמן הגלות [... ולכן הוא יחוד פב\"פ אפי'<sup data-n=\"1721\">83</sup> בזמן הגלות כידוע בענין המאמר סליק אגרין<sup data-n=\"1722\">84</sup> כו' וד\"ל. ..].",[["1719","81","<b>גשמי'</b>: בג ניתוסף: כמ\"ש."],["1720","82","<b>כו'</b>: ב: בחי' ע' נפש וע' זקנים."],["1721","83","<b>יחוד פב\"פ אפי'</b>: ב: סוד החכ' אף."],["1722","84","<b>סליק אגרין</b>: זהר בחוקותי קיד, ב. ראה ביאוה\"ז שם קמג, ד. ולהצ\"צ כרך א ע' תמד."]]],[4801940100,"<b>[שנת כת\"ר]</b>\n<b>גדולה</b> מילה<sup data-n=\"1723\">1</sup> שנכרתו עלי' שלש עשרה בריתות<sup data-n=\"1724\">2</sup> כו', הנה מי יעלה לנו השמימה ר\"ת מילה וס\"ת הוי'<sup data-n=\"1725\">3</sup>, והוי' הוא מקור התומ\"צ<sup data-n=\"1726\">4</sup> וא\"כ בחי' מילה הוא גבוה מתומ\"צ<sup data-n=\"1727\">5</sup>, והיינו כי על התורה נאמר לא בשמים היא<sup data-n=\"1728\">6</sup> כי ירדה מן השמים לארץ<sup data-n=\"1729\">7</sup>, משא\"כ מצות מילה היא בשמים וידוע שיש שמיא וארעא תתאין שהם בחי' זו\"נ<sup data-n=\"1730\">9</sup> ויש שמיא וארעא עילאין<sup data-n=\"1731\">8</sup> שהם בחי' חו\"ב<sup data-n=\"1732\">10</sup>, לכך השמימה הוא גבוה מבחי' חו\"ב שזהו",[["1723","1","<b>גדולה מילה</b>: הנחת ר\"ה (רק חלק) מדרוש כ\"ק אדמו\"ר הצ\"צ.\nהמאמר מיוסד על מאמר ד\"ה בעצם היום הזה שנדפס בפלח הרמון לך מב, א ואילך ובהנסמן בהערות וציונים לשם. ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' י ואילך. ע' יב ואילך. סה\"מ תרכ\"ו ע' כו ואילך. ולהתחלת המאמר ראה גם מאמר ד\"ה מי יעלה לנו השמימה נדפס בס' נתיב רש\"י כז, ב יודפס בע\"ה בפלח הרמון לפ' נצבים.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["1724","2","<b>גדולה מילה. . בריתות</b>: נדרים לא, ב (במשנה). וראה לקו\"ש לך כרך כה ע' 54 ואילך ובהערה 5."],["1725","3","<b>מי יעלה. . ר\"ת מילה וס\"ת הוי'</b>: נצבים ל, יב. ראה בעה\"ט שם. ת\"ז בהקדמה ב, ב. תכ\"ב סה, ב. סו, א. ת\"ע קלא, רע\"א."],["1726","4","<b>והוי' הוא מקור התומ\"צ</b>: כל התומ\"צ נק' מצות הוי' (פלה\"ר כאן מב, רע\"ב). ראה גם ת\"ז בהקדמה ב, א. רת\"ב יח, סע\"א."],["1727","5","<b>מילה הוא גבוה מתומ\"צ</b>: כי ר\"ת גבוה מס\"ת (פלה\"ר כאן מב, סע\"א)."],["1728","6","<b>לא בשמים היא</b>: נצבים ל, יב."],["1729","7","<b>ירדה מן השמים לארץ</b>: ראה ב\"מ נט, ב. תו\"א בראשית א, א. תו\"ח לך צג, ג ובהערה 15. מאמר ד\"ה אנכי ה\"א ערב שבועות תשמ\"ט פ\"ה הערה 53 (סה\"מ מלוקט ג ע' קפ)."],["1730","9","<b>שמיא וארעא. . זו\"נ</b>: ראה דרושים שבהערה 1. שה\"א לז, ב ובהערה 26. סה\"מ תרכ\"ו ע' כז. לקמן ביאור מאמר ד\"ה וזכרתי הר\"ת על יד הערה 11."],["1731","8","<b>שמיא וארעא תתאין. . עילאין</b>: באוה\"ת כאן ס\"ע תשכה מציין לזהר ויקהל דרנ\"ו ע\"א. וכנצ\"ל: רט, א."],["1732","10","<b>שמיא וארעא. . חו\"ב</b>: ראה דרושים שבהערה 1. סה\"מ תרכ\"ו ע' כז. סה\"מ תרל\"ח ע' שפד."]]],[4801940165,"בחי' שמים דכתר<sup data-n=\"1733\">11</sup> (... אפ\"ל שזהו שמי השמים כו'. ..), ושם הוא שרש מצות מילה בבחי' הכתר שלמעלה מן החכמה, ועם זה יובן מאמר הנ\"ל גדולה מילה שנכרתו עלי' שלש עשרה בריתות כי על כללות התו' לא נכרתו עלי' רק ג' בריתות<sup data-n=\"1734\">12</sup> כי ברית הוא המחבר וכללות האצי' נכללו בג' קוין חח\"ן בג\"ה דת\"י<sup data-n=\"1735\">13</sup> וצריך להמשיך אותם ולייחדם בבי\"ע ולכן א\"צ רק ג' בריתות (... והגם שיש ע\"ס מ\"מ בבי\"ע אינם מתגלים כ\"כ בפרטיות רק בהעלם רק ג' כלליי' שהם ג' קוין, כי עכשיו הגם שע\"י המצות נמשך אור האצי' בבי\"ע אינו נמשך רק בהעלם בבחי' קטנות ובבחי' קטנות לא נגלה כל הפרטים כנ\"ל במאמר סוד ה'<sup data-n=\"1736\">14</sup> בענין ההפרש בין יו\"ד רבתי ליו\"ד זעירא<sup data-n=\"1737\">15</sup> כנ\"ל. ..), משא\"כ ע\"י מילה מאיר אור עצמות המאציל בנאצלים (כי על ידה מאיר אור הכתר הנק' מאציל כנ\"ל בענין השמימה כו'), ואותו האור עצמו נמשך בבי\"ע לכן צריך לי\"ג בריתות שהם כנגד י\"ג מדה\"ר<sup data-n=\"1738\">16</sup> כי ענין יגמה\"ר מבואר בפרדס שער עשר ולא תשע<sup data-n=\"1739\">17</sup> בשני אופנים, הא' שהם כנגד י\"ס וג' גנוזות ראשי ראשים (וזהו דעת רב האי ז\"ל), והב' שהם כנגד ע\"ס דאצי' וג' עולמות בי\"ע (וזהו דעת רב חמא ז\"ל), ושניהם אמת, וא\"כ כיון שמצות מילה היא מחברת אור עצמות המאציל ובו גנוזות הי\"ס כידוע (... רק מצד העלמם אינם רק בבחי' ג' קדמון מצוחצח צח<sup data-n=\"1740\">18</sup> כו' ר\"ת קמ\"ץ<sup data-n=\"1741\">19</sup> שהוא<sup data-n=\"1742\">20</sup> בכת\"ר. ..)<sup data-n=\"1743\">21</sup>, וע\"י מילה נמשכים באצי' (כנ\"ל במאמר סוד ה'<sup data-n=\"1744\">22</sup> ) לכן הם י\"ג בחי' ג' גנוזות וי\"ס כו', וכן הוא מחברת אור זה שיאיר בבי\"ע והם ג\"כ י\"ג י\"ס דאצי' וג' עולמות בי\"ע כנ\"ל בשני האופנים כו' וד\"ל.\n<b>והנה</b> זהו ענין מילה שניתנה בשמיני<sup data-n=\"1745\">23</sup> שהוא המשכת הכתר שלמעלה מהחכמה כו' (... ונק' שמיני מצד שהתגלות זאת דכתר נמשך ע\"י הבינה הנק' שמינית<sup data-n=\"1746\">24</sup>",[["1733","11","<b>השמימה. . דכתר</b>: ראה גם סה\"מ תרכ\"ו והדרושים שבהערה 1."],["1734","12","<b>התו'. . ג' בריתות</b>: ברכות מח, סע\"ב."],["1735","13","<b>חח\"ן בג\"ה דת\"י</b>: ראה זהר רע\"מ בהעלותך קנג, ב. פרדס שער סדר עמידתן ש\"ו, פ\"א. בד קודש פ\"ב (נדפס גם באגרות קודש כ\"ק אדמו\"ר האמצעי ח\"א ע' רצ ואילך). מאמרי אדה\"א בראשית ע' שיז. וש\"נ."],["1736","14","<b>כנ\"ל במאמר סוד ה'</b>: שנדפס לפנ\"ז (ושם הוא ד\"ה: והנה מ\"ש)."],["1737","15","<b>ההפרש בין יו\"ד רבתי ליו\"ד זעירא</b>: שם וכן בב: ו' רבתי ו' זעירא."],["1738","16","<b>לי\"ג בריתות. . י\"ג מדה\"ר</b>: ראה גם דרושים שבהערה 1. סה\"מ תרל\"ג ח\"ב ס\"ע תג ובהערה שם. לעיל מאמר ד\"ה סוד ה' תר\"כ ובהערה 16."],["1739","17","<b>בפרדס שער עשר ולא תשע</b>: פ\"ז."],["1740","18","<b>קדמון מצוחצח צח</b>: ראה ת\"ז ת\"ע קלה, ב. ספר הערכים חב\"ד ח\"ג מערכת אור קדמון, מצוחצח צח ע' תפב."],["1741","19","<b>קדמון מצוחצח צח. . ר\"ת קמץ</b>: ראה פרדס שער הצחצחות שי\"א, פ\"ז. מאו\"א מערכת קמץ סי\"ח. מאמרי אדה\"ז כתובים ח\"א ע' עג. אוה\"ת בחוקותי כרך ג' ע' תתקלו. במדבר ח\"ד ע' א'תצב ואילך. ע' א'תצו ואילך (ובהוצאת תשנ\"ז בהעלותך ע' 43-49). לקמן מאמר ד\"ה אם בחוקותי הג' על יד הערה 54."],["1742","20","<b>קמ\"ץ שהוא בכתר</b>: ראה ע\"ח שער השמות שער מ\"ד, פ\"א. מאו\"א שם. תו\"ח ויקהל ח\"ב שפז, ד. וש\"נ. מאמר ד\"ה אם בחוקותי הנ\"ל על יד הערה 51."],["1743","21","<b>בכתר)</b>: סיום הסוגר ניתוסף ע\"פ ב."],["1744","22","<b>כנ\"ל במאמר סוד ה'</b>: נדפס לפנ\"ז (ד\"ה והנה ע\"י ואילך)."],["1745","23","<b>מילה שניתנה בשמיני</b>: מנחות מג, ב."],["1746","24","<b>הבינה הנק' שמינית</b>: ראה גם זהר רע\"מ פינחס רמה, ב. מאמרי אדה\"א דברים ח\"ד ע' א'שדמ. וש\"נ. בהערה שלאח\"ז."]]],[4801940224,"כו' חוץ להיקף כנ\"ל במאמר ת\"ר<sup data-n=\"1747\">25</sup> כו'. ..), אך יש עוד במצות מילה שהוא בבחי' יסוד (... כי ע\"י מילה מגלים העטרה שהוא בחי' יסוד ומל' הדבוקה בו הנק' עטרת היסוד<sup data-n=\"1748\">26</sup> כו'. ..), ולכן מאשר יושיט לו המלך את שרביט הזהב הוא ג\"כ ר\"ת מילה<sup data-n=\"1749\">27</sup>, היסוד נק' שרביט הזהב<sup data-n=\"1750\">28</sup> כי עיקר היסוד הוא בבחי' גבו' (... וכידוע דהמשכת פנימי' השפע במל' להוליד נשמות מוכרח להיות ע\"י גבורות תגבורת השפע כו' וכמאמר הזהר צדיק נטיל לשמאלא<sup data-n=\"1751\">29</sup> כו' עמודא דאמצעיתא לימינא כו'. ..), ושני הבחי' הם במצות מילה (... כי המשכות יגמה\"ר מהמאציל לאצי' הוא ע\"י יסוד עליון שבמאציל והמשכתם מאצי' לבי\"ע הוא ע\"י יסוד דאצי' כו' וד\"ל. ..), כי עצם המילה הוא גילוי היסוד הנק' שרביט הזהב, ומה שנמשכים על ידה הוא בחי' י\"ג מדה\"ר שמן המאציל לנאצלים ומאצי' לבי\"ע וזה\"ע י\"ג בריתות שנכרתו עלי' כו' וד\"ל. והנה ידוע שיש ב' בחי' מילה הא' מה שנאמר ומלתם את ערלת לבבכם<sup data-n=\"1752\">30</sup> כו' והוא מלמטה למעלה כו', וברוחני' היינו ענין התשובה כו', והב' הוא מה שנאמר ומל ה' את לבבך<sup data-n=\"1753\">31</sup> שזהו מלמעלה למטה וזה\"ע גאולה העתידה, וע\"י אתעדל\"ת במילה שמלמטלמ\"ע שהוא בחי' התשובה יתגלה אתעדל\"ע<sup data-n=\"1754\">32</sup> בחי' גאולה העתידה, וזהו אם ישראל עושין תשובה נגאלין<sup data-n=\"1755\">33</sup> כו' ולכן מילה ניתנה בשמיני שהוא בחי' אתעדל\"ת לבחי' גאולה העתידה שהכינור שתתגלה לגאולה העתידה הוא של שמונה נימין<sup data-n=\"1756\">34</sup> כו' וד\"ל. והנה במילה שהיתה לאברהם הי' ב' הבחי' וכמאמר בעצם היום הזה נימול<sup data-n=\"1757\">35</sup> ממילא ומאליו וכמאמר וכרות עמו הברית<sup data-n=\"1758\">36</sup> כידוע וד\"ל.\n<b>וביאור</b><sup data-n=\"1759\">37</sup> הדברים להבין ענין שמיא וארעא עילאין ושמיא וארעא תתאין וענין השמימה, הנה מבשרי אחזה שיש באדם נר\"נ ח\"י<sup data-n=\"1760\">38</sup>, נר\"נ הם מלובשים בכלים דמוחא לבא וכבדא<sup data-n=\"1761\">39</sup> וחי' יחי' הם בחי' מקיפים, כי ענין ההתלבשות הוא אור",[["1747","25","<b>כנ\"ל במאמר ת\"ר</b>: אוה\"ת חנוכה ח\"ב ע' 608. פלח הרמון חנוכה צט, ג."],["1748","26","<b>העטרה. . יסוד ומל'. . עטרת היסוד</b>: ראה גם ע\"ח שער הכללים פ\"ה. אוה\"ת בהעלותך ע' שפב. שמע\"צ כרך ה ע' ב'קנו. (יהל אור) תהלים ע' שלה."],["1749","27","<b>מאשר יושיט לו המלך. . ר\"ת מילה</b>: אסתר ד, יא. ראה של\"ה תושב\"כ שובבי\"ם ת\"ת שכט, א. מנורת המאור לר\"י אלנקאוה ח\"ג ע' 474. מנורת המאור (ר\"י אבוהב) נר ג ח\"א ספ\"ג (ע' 178)."],["1750","28","<b>היסוד נק' שרביט הזהב</b>: מאו\"א מערכת שרביט סס\"ט. ראה אוה\"ת מג\"א (מהדורת תש\"נ) ע' לט ואילך."],["1751","29","<b>צדיק נטיל לשמאלא</b>: ת\"ז תי\"ג כח ב. ראה פרדס שער עשר ולא תשע ש\"א, פ\"ב. שער מהות והנהגה ש\"ח, ספכ\"ד. שער המכריעין ש\"ט, ספ\"ד."],["1752","30","<b>ומלתם את ערלת לבבכם</b>: עקב י, טז."],["1753","31","<b>ומל ה' את לבבך</b>: נצבים ל, ו [בדילוג]."],["1754","32","<b>אתעדל\"ת. . אתעדל\"ע</b>: ראה זהר לך פח, א. תו\"ח שמות ח\"א מא, א ובהערה 189."],["1755","33","<b>אם ישראל עושין תשובה נגאלין</b>: סנהדרין צז, ב."],["1756","34","<b>שהכינור. . של שמונה נימין</b>: ראה ערכין יג, ב. לקו\"ת תזריע כא, ד. סה\"מ תרל\"ח ס\"ע צט ואילך."],["1757","35","<b>בעצם היום הזה נמול</b>: לך יז, כו. ראה ב\"ר פמ\"ז, ט. תנחומא לך יז. זהר לך צו, ב."],["1758","36","<b>וכרות עמו הברית</b>: נחמי' ט, ח. ראה ב\"ר פמ\"ט, ב."],["1759","37","<b>וביאור</b>: השוה פלח הרמון כאן מב, ב."],["1760","38","<b>נר\"נ ח\"י</b>: ראה ב\"ר פי\"ד, ט. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תכח."],["1761","39","<b>נר\"נ. . דמוחא לבא וכבדא</b>: ראה אבן עזרא משפטים כג, כה. יסוד מורא — להנ\"ל — ש\"ז. ע\"ח שער אח\"פ ש\"ד, פ\"א. לקמן מאמר ד\"ה את שבתותי תרי\"ב ובהערה 90."]]],[4801940277,"פנימי כמו חיות הנפש הנמזג במוח מתאחד עם כלי המוח עד שנעשה ממזיגה זאת מקור לשכל (... והגם שרחוק ערך הגשמי מהרוחני מ\"מ הקב\"ה מפליא לעשות ומקשר רוחני בגשמי עד שנעשה עצם אחד להוליד שכל, משא\"כ מחיות הנפש בלבדו לא יתהווה שכל וכן מכלי המוח בלבדו לא יתהווה שכל כו'. ..), וזהו בחי' נשמה, וכן חיות הנמזג בלב נעשה ממזיגה זאת מקור למדות שבלב וזהו בחי' רוח, ומחיות הנפש הנמזג בכבד נעשה מקור לכח התנועה ונק' בחי' נפש, וג' בחי' אלו הם בד\"כ בג' אברי' כלליי' דמוחא ליבא וכבדא ובפרט הם מתפשטים בכל האברים בג' מיני גידים<sup data-n=\"1762\">40</sup> הנק' נערווין הם מקושרים בעצמות ובהם מתפשט החיות מהמוח ולכן על ידם מרגיש המוח את כל האברים ונק' גידי הרגשה וגידים הדופקים המלאים רוח בהם מתפשט החיות מהלב לכל האברים וגידי הדם המתפשטים בבשר בהם מתפשט החיות מהכבד לכל האברים, וזה\"ע ג' בחי' שבכל אבר בשר וגידים ועצמות<sup data-n=\"1763\">41</sup>. והנה ג' מיני חיות אלו שהוא בחי' נר\"נ נק' פנימי', אך יש ב' מקיפים והוא בחי' חי' יחידה, כי הנה עצם החכמה הוא בחי' אין ונכלל במקורה בהעלם, ומה שנגלה ממנה במוח כנקודה שהוא בחי' ברק המבריק<sup data-n=\"1764\">42</sup> הוא רק בחי' אחרונה מעצם החכמה (... ולמעלה הוא בחי' יסוד אבא כמשי\"ת. ..), ולכן עצם החכ' נק' מקיף דחי' כו' ובחי' יחידה הוא בחי' כח הרצון שלמעלה אפי' ממקור החכ' (... כידוע דאין טעם לרצון<sup data-n=\"1765\">43</sup> אפי' טעם הכמוס ונק' מקיף למקיף כו'. ..).\n<b>והנמשל</b> מזה<sup data-n=\"1766\">44</sup> יובן למעלה בבחי' אדה\"ע שנאמר ועל הכסא כמראה אדם<sup data-n=\"1767\">45</sup> כו' שיש שני בחי', בחי' ממכ\"ע ובחי' סוכ\"ע<sup data-n=\"1768\">46</sup> שהו\"ע מקיפים ופנימי', וחיות הפנימי נמשך מבחי' המל' שהו\"ע ל' כלים דמל' דאצי'<sup data-n=\"1769\">47</sup> המלובשים בבי\"ע ונק' ממכ\"ע כדוגמת חיות הנפש המתמזג בג' כלים דמוחא ליבא וכבדא, וכ\"ה אור וחיות האלקי הממלא נתפס בתוך הנבראים עד שהם מרגישים אור האלקי המחי' ומהווה אותם מאין ליש ומחמת זה המה בטלים לאור האלקי המחי' אותם (... וביטול זה גופא הוא חיותם כידוע בשם הרה\"מ נ\"ע<sup data-n=\"1770\">48</sup> בענין יראת ה' לחיים<sup data-n=\"1771\">49</sup> שלכן",[["1762","40","<b>בג' מיני גידים</b>: ראה ע\"ח שער פנו\"ח ש\"מ, דרוש יב. שער החשמ\"ל שמ\"א, פ\"א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקכט. מאמרי אדה\"א דברים ח\"ג ע' תתקיז ואילך. הנחות תקע\"ז ע' כט ובהנסמן בהנ\"ל. תו\"ח בא ח\"א קד, א ואילך."],["1763","41","<b>אבר בשר וגידים ועצמות</b>: רמב\"ם הל' טומאת מת פ\"ב, ה\"ג."],["1764","42","<b>ברק המבריק</b>: ראה גם בענין ברק במבריק לקמן מאמר ד\"ה והניף הכהן הב' הערה 54."],["1765","43","<b>דאין טעם לרצון</b>: ראה של\"ה ד, ב. מאמרי אדה\"א דברים ח\"א ע' כא. וש\"נ. תו\"ח בא ח\"א פט, ד. וש\"נ."],["1766","44","<b>והנמשל מזה</b>: לפיסקא זו השווה פלח הרמון לך כאן מב, ג ואילך."],["1767","45","<b>ועל הכסא כמראה אדם</b>: יחזקאל א, כו [בדילוג]."],["1768","46","<b>ממכ\"ע ובחי' סוכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["1769","47","<b>ל' כלים דמל' דאצי'</b>: ראה ע\"ח שער השמות שער מ\"ד, פ\"א-ב. לקמן מאמר ד\"ה את שבתותי תרי\"ב ובהערה 26."],["1770","48","<b>בשם הרה\"מ נ\"ע</b>: מובא בשמו גם בסידור שער הק\"ש פב, סע\"ג. לעיל מאמר ד\"ה אשה כי תזריע תרכ\"ג על יד הערה 94. לקמן ד\"ה והתהלכתי תרכ\"ב על יד הערה 22. פלח הרמון תולדות פג, ד. שמות ע' רפג. שה\"ש ע' נד."],["1771","49","<b>יראת ה' לחיים</b>: משלי יט, כג. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תקלט. וש\"נ. תו\"ח בא ח\"א ק, א. וש\"נ."]]],[4801940327,"המלאכים חיים וקיימים יותר מחמת שהם בבחי' ביטול יותר כו' וד\"ל. ..). והנה חיות זה בא בחילוקי מדריגות רבות בכל עולם לפ\"ע כמו בעולם הבריאה החיות האלקי מאיר ביותר לכן הביטול נמצא בהם ביותר ובלתי מורגש כלל וזה\"ע השרפים דבריאה<sup data-n=\"1772\">50</sup> שנאמר בהם שרפים עומדים<sup data-n=\"1773\">51</sup> ועמידה הוא מלשון שתיקה<sup data-n=\"1774\">52</sup> שמורה על בחי' ביטול ביותר כו', משא\"כ חיות הקודש דיצי'<sup data-n=\"1775\">53</sup> נאמר בהם ברעש גדול מתנשאים<sup data-n=\"1776\">54</sup> שההתפעלות מורגש ביותר מצד שאין בהם בחי' הביטול כ\"כ כו' (... מצד שאור האלקי מוסתר ביותר לגביהם להיותם מקבלים ע\"י ב' פרסאות שבין אצי' לבריאה<sup data-n=\"1777\">55</sup> ובין בריאה ליצי'<sup data-n=\"1778\">56</sup>, משא\"כ השרפים דבריאה מקבלים דרך פרסא אחת מאצי' לבריאה בלבד כו'. ..), ובעולם העשי' בא אור וחיות האלקי בהסתר יותר עד שמרחוק ה' נראה להם<sup data-n=\"1779\">57</sup> בדרך הודאה בלבד כו', והנה אע\"פ שנאמר למעלה שאור וחיות הנתפס בג' עולמות דבי\"ע הוא בדוגמת חיות המתמזג בג' כלים דמוחא לבא וכבדא מ\"מ לגבי אדה\"ע דאצי' הוא בחי' אחרונה שבו שהוא בחי' נפש בלבד, והענין הוא כמו שבנפש האדם החיות הנמזג בכבד נק' בחי' נפש שממנו נמשך כח התנועה וענין התנועה הוא ממקום למקום להמשיך חיות הנפש מהעלמו באברים שיתגלה לחוץ במקום נבדל כמו זריקת אבן או כתיבה ביד כו', כן למעלה בחי' המל' נק' נפש<sup data-n=\"1780\">58</sup> בבחי' אדה\"ע כי כח המל' הוא המגלה אור וחיות האלקי שבעולם האצי' מהעלמו לחוץ בבחי' בריאה מאין ליש כו'.\n<b>אך</b><sup data-n=\"1781\">59</sup> כ\"ז הוא בחי' ממכ\"ע, אך בחי' המדות דאצי' מאירים בבחי' העלם בכל ג' עולמות דבי\"ע ובהשוואה, כי לגבי עצם אור האלקי שבבחי' המדות דאצי' שוה בחי' עולם הבריאה עם עולם העשי' כי שניהם אין ערוך לאור האלקי דבחי' המדות דאצי' לכן לית מח' תפיסא בי'<sup data-n=\"1782\">60</sup> אפי' דעולם (... כי תפיסא הוא בחי' הרגשה בגילוי. ..) הבריאה, ולית אתר פנוי מיני'<sup data-n=\"1783\">61</sup> גם בעולם העשי' כמו בעולם הבריאה כי שניהם שוין לפניו בהשוואה אמיתית (... ולא שייך לומר אשר ריחוק הערך דעשי' הוא יותר מרוחק<sup data-n=\"1784\">62</sup> הערך דבריאה לגבי אור האלקי שבמדות דאצי' שא\"כ יש קצת ערך כו'",[["1772","50","<b>השרפים דבריאה</b>: ראה לקו\"ת להאריז\"ל ישעי' פ\"ו. ביאוה\"ז בשלח לט, ד. מאמרי אדה\"א דברים ח\"א ע' רסג. וש\"נ. שע\"ת סב, א הערה 10."],["1773","51","<b>שרפים עומדים</b>: ישעי' ו, ב."],["1774","52","<b>ועמידה הוא מלשון שתיקה</b>: ראה סוטה לט, א. לקו\"ת נשא כ, ג. כב, ג. וראה גם לקמן מאמר ד\"ה רפאיני תר\"ח על יד הערה 77."],["1775","53","<b>חיות הקודש דיצי'</b>: ראה ע\"ח שער פנו\"ח ש\"מ, דרוש יג. תו\"ח תצוה ח\"ב שמ, ג. וש\"נ."],["1776","54","<b>חיות. . ברעש גדול מתנשאים</b>: ברכת יוצר. ראה אוה\"ת תרומה ע' א'תקיז."],["1777","55","<b>פרסאות שבין אצי' לבריאה</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא. ראה גם לקמן מאמר ד\"ה וזכרתי הר\"ת על יד הערה 29 ואילך."],["1778","56","<b>פרסאות שבין. . בריאה ליצי'</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פי\"ג. פי\"ד. תו\"א לך יב, סע\"ג."],["1779","57","<b>שמרחוק ה' נראה להם</b>: ע\"פ ירמי' לא, ב."],["1780","58","<b>המל' נק' נפש</b>: ראה פע\"ח התחילתו."],["1781","59","<b>אך</b>: לפיסקא זו השווה פלח הרמון לך כאן מב, ג."],["1782","60","<b>לית מח' תפיסא בי'</b>: ראה ת\"ז בהקדמה יז, א."],["1783","61","<b>ולית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. לקו\"ת בהר מא, א. שם בהוספות נב, ג."],["1784","62","<b>מרוחק</b>: ב ובפלח הרמון כאן: מריחוק."]]],[4801940375,"ובאמת אין ערוך<sup data-n=\"1785\">63</sup> להם כלל לגבי אור האלקי הנ\"ל לכן גם ריחוק הערך דבריאה הוא שוה בהשוואה אמיתית עם ריחוק הערך דעשי' כו'. ..). ובחי' אור וחיות המדות דאצי' נק' בחי' סוכ\"ע ואין הכוונה סובב ומקיף מלמעלה<sup data-n=\"1786\">64</sup> רק כדוגמת העיגול שאין בו מעלה ומטה<sup data-n=\"1787\">65</sup>, כך אור האלקי נמצא בהשוואה כנ\"ל, אבל הוא ממלא תוכו ותוך תוכו עד דלית אתר פנוי מיני' כו', ולכן נאמר את השמים ואת הארץ אני מלא<sup data-n=\"1788\">66</sup> כו' שממלא תוכם ותוך תוכם בהעלם בהשוואה אמיתי' לשמים דבריאה עם ארץ דעשי' כנ\"ל וד\"ל.\n<b>והנה</b><sup data-n=\"1789\">67</sup> בחי' זאת הוא בחי' רוח דאדה\"ע וכמו למטה באדם גילוי החיות מן הלב לכל האברים אינו בא בבחי' גילוי לחוץ מן הנפש לזולתו הנבדל רק הוא פועל קיום החיות המתפשט מן הכבד לחוץ ע\"י שהוא מאיר בו בהעלם כו', כן למעלה בחי' סובב הגם שהארתו הוא בהעלם מ\"מ פועל פעולה גדולה קיום החיות דממלא וקיום התהוות הנבראים כו' (... וזהו ברוך חי לעד וקיים<sup data-n=\"1790\">68</sup> כו' שנק' חי מצד שהוא ממכ\"ע, וקיים מצד שהוא סוכ\"ע כו' וד\"ל. ..). והנה בחי' סובב וממלא הנ\"ל שהם בחי' המדות ומל' נק' שמים וארץ<sup data-n=\"1791\">69</sup> כמו השמים מקיפים לארץ והארץ מוקף מהם, כן למעלה בחי' מל' נק' דיבור<sup data-n=\"1792\">70</sup> והדיבור בטל ונכלל בבחי' המדות עליונות דאצי' וכמשל האדם ביטול הדיבור בעודו בשכלו כשמשכיל איך לדבר, אך למטה באדם שמדבר אז יצא הדבור לחוץ ונפרד מן השכל והמח', אך למעלה גם אחר שנגלה בחי' דבר ה' אינו נפרד ממקורו כי אין שייך למעלה יציאות הדיבור לחוץ כי אין לך דבר חוץ ממנו וא\"כ בחי' דבר ה' שהוא בחי' עש\"מ וחילופים ותמורות שלהם שמהוים כל הנבראים מאין ליש גם עכשיו לאחר שנבראו המה בטלים במקורם שהם המדות דאצי' כמו קודם הבריאה בלי שום שינוי כלל (... וזהו אני הוי' לא שניתי<sup data-n=\"1793\">71</sup> מקודם הבריא' לאחר הבריאה כו' והוי' זה הוא בבחי' המדות דאצי' כו'. ..), ולכן נקרא המדות בשם שמים והמל' שהוא בחי' הדיבור נק' ארץ כי כמו למטה הארץ מוקף מן השמים והשמים מקיפים לארץ כן למעלה הדיבור הוא מוקף ובטל במקורו שהוא בחי' המדות כו' וד\"ל<sup data-n=\"1794\">72</sup>.",[["1785","63","<b>ערוך</b>: ניתוסף ע\"פ ב."],["1786","64","<b>ואין הכוונה סובב ומקיף מלמעלה</b>: ראה תניא פמ\"ח סז, סע\"ב ובמ\"מ הגהות והע\"ק לשם. תו\"ח ויקהל ח\"ב שפח, ב. וש\"נ. סה\"מ תרכ\"ט ע' קסו. וש\"נ. תרל\"ב ח\"א ע' פח. וש\"נ. לעיל ע' קכב. לקמן מאמר ד\"ה וספרתם הה' על יד הערה 41. ד\"ה שבת שבתון על יד הערה 47. ד\"ה והתהלכתי תרכ\"ב על יד הערה 26."],["1787","65","<b>העיגול שאין בו מעלה ומטה</b>: ראה מאמרי אדה\"א נ\"ך ע' תמז. וש\"נ. תו\"ח שמות ח\"א לז, ד. וש\"נ."],["1788","66","<b>את השמים. . מלא</b>: ירמי' כג, כד. ראה גם לקמן מאמר ד\"ה את שבתותי תקצ\"ח ובהערה 85. תו\"ח בשלח ח\"א קסו, ג. וש\"נ."],["1789","67","<b>והנה</b>: ראה פלח הרמון כאן מד, ד."],["1790","68","<b>ברוך חי לעד וקיים</b>: נוסח ברוך שאמר."],["1791","69","<b>סובב וממלא. . שמים וארץ</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' קכו. שה\"א נח, א ובהנסמן במ\"מ לשם."],["1792","70","<b>מל' נק' דיבור</b>: ראה זהר לך פו, ב. ע\"ח שער מוחין דצלם שכ\"ג, ספ\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפב. וש\"נ."],["1793","71","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["1794","72","<b>וד\"ל</b>: ב ניתוסף: (עכ\"מ מכי\"ק ונראה שחסר תשלום המאמר). ראה ההמשך בפלח הרמון כאן."]]],[4801940101,"<b>[שנת תו\"ר]</b>\n<b>ענין</b> מצות מילה<sup data-n=\"1795\">1</sup> ביאר הרמב\"ם<sup data-n=\"1796\">2</sup> הטעם להתיש כח המתאווה כו', ובס' פרי הארץ<sup data-n=\"1797\">3</sup> אמר עליו הוציא מפיו דברים העומדים ברומו של עולם אעפ\"י שלא כיוון בהם, וביאור הענין הנה כח המתאוה בבחי' אלקות הוא המתאוה לצאת מגדרי הכלי ולהיות כלה שארי<sup data-n=\"1798\">4</sup> כו', הוא בחי' אה\"ר חותם הבולט מלמטלמ\"ע, וגורם המשכה מלמעלה בחי' חותם שוקע יולדת נקבה<sup data-n=\"1799\">6</sup> מ\"ע התלוים בו\"ה<sup data-n=\"1800\">7</sup> כלים ואותיות דכח הירידה<sup data-n=\"1801\">8</sup> המסתירים על האור כו' כנ\"ל באריכות<sup data-n=\"1802\">5</sup>. אבל בחי' יראה עילאה הוא מופשט מכל מיני עונג ובטל במציאות מכל וכל חותם שוקע ממטלמ\"ע, וגורם המשכה מלמעלה חותם בולט יולדת<sup data-n=\"1803\">11</sup> זכר<sup data-n=\"1804\">10</sup> מל\"ת התלוים בי\"ה<sup data-n=\"1805\">12</sup> כלים ואותיות דכח העילוי<sup data-n=\"1806\">13</sup> כנ\"ל<sup data-n=\"1807\">9</sup> שמגלים האור בלי הסתר כלל, והנה מצות מילה אעפ\"י שהיא מצות עשה, מ\"מ ענינה כמו ל\"ת להעביר הערלה מקור הרע, ובזה נותנים כח ועוז בנפש הנולד שיוכל להיות כל ימיו בו בחי' הפשטה מכל מיני עונג רק ביטול<sup data-n=\"1808\">14</sup> במציאות דבחי' יראה שגורם הגלוי די\"ה שרש מל\"ת כידוע דשמי עם י\"ה שס\"ה<sup data-n=\"1809\">15</sup>, וזהו מילה מל י\"ה<sup data-n=\"1810\">16</sup> פריעה פרע י\"ה<sup data-n=\"1811\">17</sup>, הכל לגלות בחי' י\"ה בנפש, ומציצה מצץ י\"ה, להעביר פסולת הדקה דדמים הרותחים מבחי' י\"ה, וזהו הכוונה להתיש כח המתאוה דאה\"ר לבא לבחי' יראה עילאה שלמעלה<sup data-n=\"1812\">19</sup> מאה'<sup data-n=\"1813\">20</sup> ששרשה בחכ\"ע בחי' י\"ה כו' וד\"ל.",[["1795","1","<b>ענין מצות מילה</b>: לע\"ע לא נתברר אם מאמר זה הוא הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ או שזהו דרוש עצמו.\nראה גם בס' נתיב רש\"י ירושלים תרנ\"ה כז, ב ושם הפתיחא: מי יעלה לנו השמימה — יודפס בע\"ה בפלח הרמון לפ' נצבים. עוד ע\"ד המאמר ראה לקמן ברשימת הכת\"י."],["1796","2","<b>מצות מילה ביאר הרמב\"ם</b>: במו\"נ ח\"ג, פל\"ה ופמ\"ט."],["1797","3","<b>ובס' פרי הארץ</b>: להרמ\"מ מוויטעפסק פ' לך בסופה ד, א."],["1798","4","<b>כלה שארי</b>: תהלים עג, כו."],["1799","6","<b>יולדת נקבה</b>: ברכות ס, א. נדה לא, א. ראה ויק\"ר ספי\"ד."],["1800","7","<b>מ\"ע התלוים בו\"ה</b>: נסמן לקמן בהערה 15."],["1801","8","<b>ואותיות דכח הירידה</b>: פלח הרמון שם קיח, א ואילך."],["1802","5","<b>אה\"ר חותם הבולט. . כנ\"ל באריכות</b>: פלח הרמון שה\"ש קיג, ב. קיט, א."],["1803","11","<b>יולדת זכר</b>: נסמן לעיל בהערה 6."],["1804","10","<b>יולדת זכר</b>: ניתוסף ע\"פ ג."],["1805","12","<b>מל\"ת התלוים בי\"ה</b>: נסמן לקמן בהערה 15."],["1806","13","<b>ואותיות דכח העילוי</b>: פלח הרמון שם קיח, א ואילך."],["1807","9","<b>יראה. . כנ\"ל</b>: פלח הרמון שם קיג, ב ואילך. קיט, א."],["1808","14","<b>ביטול</b>: א: בחי' ביטול."],["1809","15","<b>דשמי עם י\"ה שס\"ה</b>: ראה שמות ג, טו. ת\"ז בהקדמה ד, סע\"ב. ה, א. לקו\"ת פקודי ג, ב ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ג ע' תתקי. וש\"נ. תו\"ח בא ח\"א קיד, א. וש\"נ. סה\"מ תרכ\"ז ע' קכט. וש\"נ."],["1810","16","<b>מילה מל י\"ה</b>: ראה ת\"ז תכ\"ב סח, א. תו\"א לך יב, א. ביאוה\"ז בראשית ד, ב. סידור שער המילה קמג, ג. תו\"ח מקץ צד, א הערה 2. סהמ\"צ להצ\"צ ח, ב."],["1811","17","<b>פריעה פרע י\"ה</b>: ראה ע\"ח שער האונאה של\"ג, פ\"ג. טעמי המצות [להאריז\"ל] לך סוד מצות מילה ופריעה. ביאוה\"ז בראשית ד, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' פג.\n18)ומציצה מצץ י\"ה: ראה גם לעיל מאמר ד\"ה למנצח על השמינית על יד הערה *69."],["1812","19","<b>יראה עילאה שלמעלה מאה'</b>: ראה גם לעיל מאמר ד\"ה אשה כי תזריע תרכ\"ג פ\"ג."],["1813","20","<b>מאה'</b>: א: מא\"ר מאהבה רבה."]]],[4801940102,"<b>[פ' דברים תקצ\"ו פרילוק]</b>\n<b>במדרש</b> איתא והצרוע<sup data-n=\"1814\">2</sup> אשר בו הנגע זה בהמ\"ק<sup data-n=\"1815\">1</sup> כמאמר ובא אל הכהן זה הקב\"ה שבא לירמי' וא' כנגע לי נראה לי בבית<sup data-n=\"1816\">3</sup>, בגדיו יהיו פרומים זהו בגדי כהונה. והנה דברים אלו אין להם הבנה ויש להקדים לזה ענין תפלה במקום קרבן<sup data-n=\"1817\">4</sup> כי בזמן בהמ\"ק קיים<sup data-n=\"1818\">5</sup> שאז הי' הקרבנות עצמן קרובין ע\"ג המזבח נאמר וביום שמחת לבו<sup data-n=\"1819\">6</sup> זה בנין בהמ\"ק ועכשיו שאין קרבנות התפלה שהיא עבודה שבלב<sup data-n=\"1820\">7</sup> הוא במקום שמחת לבו שע\"י הקרבנות ויש להבין מה ענין לתפלה דאיהו רחמי<sup data-n=\"1821\">8</sup> להיות כנגד תמידין דאת הכבש<sup data-n=\"1822\">9</sup> כו'. יש להקדים<sup data-n=\"1823\">10</sup> תכלית ירידת הנשמה בגוף הלא מתחלה היתה בג\"ע בתכלית הביטול כמאמר ויניחהו בג\"ע<sup data-n=\"1824\">11</sup> וא\"כ למה ירדה ירידה עצומה כזה להיות במאסר חומר הגוף וע\"כ לומר שזהו צורך עלי'<sup data-n=\"1825\">12</sup> וי\"ל ממה תתהווה העלי' ומהו העלי'.\n<b>אך</b> הנה ידוע שיש שכל ומדות בנה\"א ושכל ומדות שבנה\"ט כי זלעו\"ז עשה האלקים<sup data-n=\"1826\">13</sup> וענין השכל שבנה\"א הוא להשיג איך שהוא אחד לאחר שנבה\"ע כמו קודם שנבה\"ע בלי שום שינוי כלל ואני הוי' לא שניתי<sup data-n=\"1827\">14</sup> משום דכולא קמי' כל\"ח<sup data-n=\"1828\">15</sup> כי רק ברוך שם שכל הברכות וההמשכות הוא הארה בעלמא מבחי' שם בלבד, ומזה נמשך מדות שבנה\"א שזהו ואהבת את הוי' אלקיך<sup data-n=\"1829\">16</sup>, ולעו\"ז יש נפש השכלית המשכלת עניני עוה\"ז שמשכל הנ\"ל נולד אה' ותשוקה בעניני עוה\"ז כו' וכמ\"ש חכמים המה להרע<sup data-n=\"1830\">17</sup> כו' וכל עיקר ירידת הנשמה הוא בשביל ההתפכות דנה\"ט היינו לקרב אל השכל שבנה\"ט שגם היא תשכיל איך דכולא קמי' כל\"ח כנ\"ל ואזי יהי' ואהבת בכל לבבך בשני יצריך<sup data-n=\"1831\">18</sup> גם ביצה\"ר שהוא מדות דנה\"ט שמתהפכים לאהבת",[["1814","2","<b>והצרוע אשר בו הנגע</b>: תזריע יג, מה. ראה פתיחתא דאיכ\"ר כא. יל\"ש עה\"פ (סוף רמז תקנא). בהערה הבאה."],["1815","1","<b>במדרש איתא והצרוע. . זה בהמ\"ק</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ. ראה גם המאמר שלאח\"ז."],["1816","3","<b>ובא אל הכהן. . בבית</b>: ראה מצורע יד, לה. ויק\"ר פי\"ז, ז."],["1817","4","<b>תפלה במקום קרבן</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["1818","5","<b>בהמ\"ק קיים</b>: ניתוסף ע\"פ ב."],["1819","6","<b>וביום שמחת לבו</b>: שה\"ש ג, יא. תענית כו, ב (במשנה)."],["1820","7","<b>התפלה שהיא עבודה שבלב</b>: ראה ספרי (ופרש\"י) עקב יא, יג. תענית ב, סע\"א. רמב\"ם ריש הלכות תפלה. אוה\"ת עקב ע' תרח. לקמן סוף פיסקא והנה כ\"ז."],["1821","8","<b>לתפלה דאיהו רחמי</b>: ברכות כ, ב. כו, א."],["1822","9","<b>דאת הכבש</b>: פינחס כח, ד."],["1823","10","<b>להקדים</b>: ב: להבין."],["1824","11","<b>ויניחהו בג\"ע</b>: בראשית ב, טו."],["1825","12","<b>ירידה. . צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["1826","13","<b>כי זלעו\"ז עשה האלקים</b>: קהלת ז, יד. ראה סה\"מ תרל\"ח ס\"ע קלד ואילך."],["1827","14","<b>ואני הוי' לא שניתי</b>: מלאכי ג, ו."],["1828","15","<b>דכולא קמי' כל\"ח</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה פ\"א (ז, רע\"א). מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1829","16","<b>ואהבת את הוי' אלקיך</b>: ואתחנן ו, ה."],["1830","17","<b>חכמים המה להרע</b>: ירמי' ד, כב."],["1831","18","<b>ואהבת. . בשני יצריך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, א במשנה. ראה מאמרי אדה\"א בראשית ע' שסג ואילך. שערי אורה ו, א הערה 9."]]],[4801940166,"ה' ואזי ע\"י ירידה זו תתעלה הנפה\"א בעלוי יותר מכמו שהיתה בג\"ע כו', אך י\"ל איך תופס מקום כ\"כ אהבת הנה\"ט להעלות לנה\"א הנה הוא ע\"ד לא על הלחם לבדו<sup data-n=\"1832\">19</sup> יחי' האדם כי על כל מוצא פי הוי' יחי' האדם דהנה לכאורה אינו מובן הלא מדבר גבוה מחי וצומח ואיך יחי' האדם<sup data-n=\"1833\">20</sup> מהם, אך הענין הוא דמצד שרשם המה יותר גבוהים מנפש האדם וראי' שבהמה כחה חזקה יותר מן האדם ולכן כשתכלל בנפש האדם יתוסף בו אור וחיות וזהו כי על כל מוצא פי ה'<sup data-n=\"1834\">21</sup> יחי' האדם שהוא מקור החיות דצו\"ח מצד שרשם [... שנק' מוצא פי הוי' דתיקון כי התהו מקור התיקון<sup data-n=\"1835\">22</sup> כו'. ..], וכך הוא בענין התהפכות הנה\"ט לאהבת ה' שגורמת תוס' אור וחיות בנה\"א מצד שרש הנה\"ב שגבוה מנה\"א כו' וד\"ל. וזהו צורך העלי' כו'.\n<b>והנה</b> כדי<sup data-n=\"1836\">23</sup> לבא לבחי' ואהבת בכל לבבך שבק\"ש צריך הכנה לזה ונק' עבודה שבלב והיא ההתבוננות בפסד\"ז בב\"ש והי' העולם וברוך אומר ועושה שאומר בכל יום מחדש וכמאמר המחדש בטובו בכל יום תמיד<sup data-n=\"1837\">24</sup> וענין החידוש הוא ע\"ד שאנו רואים בגשמיות שנאמר וזרח השמש ובא השמש<sup data-n=\"1838\">25</sup> כך למעלה שמשא עילאה הוא בחי' הוי' ומגן הוא אלקים<sup data-n=\"1839\">26</sup> שהוא הנרתק לשמש, ובכל עת ורגע נעשה חידוש מע\"ב שהו\"ע הזריחה מתוך הנרתק, וזהו הקיום דהשתל', ומהתבוננות זאת יבא לבחי' ואהבת בכל לבבך כו' וד\"ל. אך כמשל המאכל שאינו מחי' לנפש האדם עד שנתברר מתחלה ונעשה דם בכבד ואח\"כ מהכבד עולה מובחר הדם ללב ומתאחד עם הנפש ואז מוסיף תוס' אור וחיות דוקא כך הוא בענין העבודה שבלב כשמתאחד אה' הנה\"ט בנה\"א דייקא אז נעשה תוס' עילוי בנה\"א, וענין ההתאחדות הוא באמת ויציב שאנו אומרים ונחמד ונעים הדבר הזה שבק\"ש, כי ענין אחד ואהבת אינו בחי' אתהפכא עדיין רק בחי' אתכפייא לבד כי זה ג\"כ נק' רצון כמו כופין אותו הנאמר בקרבנות<sup data-n=\"1840\">27</sup> אבל שיהי' אהבת הנה\"ט במתיקות ועונג באלקות כמו שנה\"א מרגיש מתיקות ועונג זהו בחי' אתהפכא שעי\"ז דוקא תתעלה נה\"א בתוס' עילוי מכמו שהיתה מתחלה כו' וד\"ל.\n<b>והנה</b> כמו שאנו רואים דלבא פליג לכל שייפין<sup data-n=\"1841\">28</sup> היינו כשניתוסף ונתרבה על רביעית דם שהנשמה תלוי' בו<sup data-n=\"1842\">29</sup> מצד בירורי המאכלים אז נמשך ממנו דם",[["1832","19","<b>לא על הלחם לבדו</b>: עקב ח, ג. ראה גם פלח הרמון בשלח ע' קצב ואילך. יתרו ע' רלו. מאמרי אדה\"א הנחות תקע\"ז ע' קכא ואילך. וש\"נ."],["1833","20","<b>האדם</b>: ניתוסף ע\"פ ב."],["1834","21","<b>ה'</b>: ניתוסף ע\"פ ב."],["1835","22","<b>התהו מקור התיקון</b>: ראה גם לקמן במאמר שלאח\"ז על יד הערה 62. ד\"ה והניף הכהן תקפ\"ו על יד הערה 57. פלח הרמון בשלח ע' קצב."],["1836","23","<b>כדי</b>: ניתוסף ע\"פ ב."],["1837","24","<b>המחדש בטובו בכל יום תמיד</b>: ברכת ק\"ש שחרית."],["1838","25","<b>וזרח השמש ובא השמש</b>: קהלת א, ה."],["1839","26","<b>שמשא. . הוי' ומגן הוא אלקים</b>: תהלים פד, יב. ראה שער היחוה\"א רפ\"ד. מאמרי אדה\"א דברים ח\"ב ע' ת. וש\"נ. נ\"ך ע' שצה. וש\"נ."],["1840","27","<b>כופין אותו הנאמר בקרבנות</b>: תו\"כ ויקרא א, ג. ר\"ה ו, א."],["1841","28","<b>דלבא פליג לכל שייפין</b>: ראה זהר שלח קסא, ב. שע\"ת סט, ב הערה 12."],["1842","29","<b>רביעית דם שהנשמה תלוי' בו</b>: ראה שבת לא, סע\"ב. מאמרי אדה\"א הנחות תקע\"ז ע' ע. וש\"נ."]]],[4801940225,"עם החיות המלובש בו בכל האיברים, אך עיקר הדם נמשך בשס\"ה גידין שמהם עיקר החיות ואח\"כ שיורי הדם נמשך באיברים ומזה חיות הבשר ואח\"כ סובב הולך הדם מן האיברים אל הלב ואז נעשה בחי' מקבל מהם, נמצא שיש בלב בחי' משפיע ומקבל שמתחילה משפיע להם ואח\"כ מקבל מהם וחוזר ומשפיע כו' כידוע בס' הרפואה כו'. כך הוא בענין העבודה שבחי' רמ\"ח פיקודין הוא בחי' רמ\"ח איברים דמלכא<sup data-n=\"1843\">30</sup> כי כל אבר הוא בחי' כלי לחיות הנפש המלובש בו שע\"י יומשך בגילוי, כך למעלה ע\"י המצות נמשך גילוי אוא\"ס למטה כמו ע\"י ג\"ח נעשה למעלה דרועא ימינא דקוב\"ה וע\"י גבור הכובש את יצרו<sup data-n=\"1844\">31</sup> נעשה בחי' דרועא שמאלא ועי\"ז נמשך גילוי אוא\"ס למטה בעולמות ובנפש כמאמר פותח את ידיך<sup data-n=\"1845\">32</sup> ומשביע לכל חי רצון [... כי תרין דרועין הם מקור המ\"ע והל\"ת. ..] וע\"י ל\"ת נמשך עיקר החיות שזהו כמו הגידין. וזהו שמי עם י\"ה שס\"ה<sup data-n=\"1846\">33</sup> וזכרי עם ו\"ה רמ\"ח כי על ידי הל\"ת נמשך חיות היותר פנימי כו'.\n<b>והנה</b> ע\"י התפלה שנק' עבודה שבלב נמשך אור וחיות בכל מצוה והוא מה שאמרו מצות צריכות כוונה<sup data-n=\"1847\">34</sup> ומצוה בלא כוונה<sup data-n=\"1848\">35</sup> כגוף בלא נשמה והמשכת הנשמה בהם שהוא חיות הפנימי' דאא\"ס הנמשך בכל המצות הוא ע\"י התפלה, וזהו שמברכין ברוך אתה ה' שבכל מצוה ומצוה נמשך שם הוי' שהוא תוס' אורות בכלים שהם<sup data-n=\"1849\">36</sup> המצות מבחי' אא\"ס עצמו, וזהו שהתפלה נק' עבודה שבלב שהיא כדוגמת הלב דפליג לכל שייפין כך התפלה ממשיך אור וחיות מבחי' אא\"ס עצמו בכל המצות. אך אעפ\"כ גם התפלה מקבל חיות מן המצות כדוגמת הלב שמקבל מאברים כך ע\"י המצות ביום העבר נמשך לו כח ועוז על התפלה דלמחר שיכוון בכוונה יתירה ולכן מניחים טו\"ת קודם התפלה, וזהו ענין יפה שעה אחת<sup data-n=\"1850\">37</sup> בתשובה ומע\"ט כו' כי תשובה הוא השבת הנפש למקורה ושרשה בתפלה עי\"ז נעשה המעשים טובים כלומר מאירים<sup data-n=\"1851\">38</sup> באוא\"ס עצמו וזהו יותר טוב מכל חיי העוה\"ב כי בעוה\"ב נשמות נהנין מזיו<sup data-n=\"1852\">39</sup> בלבד משא\"כ במצות ע\"י התפלה מאיר אא\"ס בעצמותו ומהותו שלמעלה מבחי' זיו, וזהו תחת אשר לא עבדת<sup data-n=\"1853\">40</sup> כו' בשמחה ובטוב לבב שהשמחה היא של מצוה מזה כאשר מתבונן שאין ערוך תענוגי עוה\"ז לגבי תענוג עוה\"ב כמאמר מוטב דלידיינו<sup data-n=\"1854\">41</sup> ואין ערוך מתענוגי עוה\"ב לגבי המשכות אא\"ס שנמשך ע\"י",[["1843","30","<b>רמ\"ח פיקודין. . רמ\"ח איברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["1844","31","<b>גבור הכובש את יצרו</b>: אבות פ\"ד, מ\"א."],["1845","32","<b>פותח את ידיך</b>: תהלים קמה, טז."],["1846","33","<b>שמי עם י\"ה שס\"ה</b>: ראה שמות ג, טו. ת\"ז בהקדמה ד, סע\"ב. ה, א. לקו\"ת פקודי ג, ב ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ג ע' תתקי. וש\"נ. תו\"ח בא ח\"א קיד, א. וש\"נ. סה\"מ תרכ\"ז ע' קכט. וש\"נ."],["1847","34","<b>מצות צריכות כוונה</b>: ערובין צה, סע\"ב."],["1848","35","<b>ומצוה בלא כוונה</b>: ראה לקו\"ת להאריז\"ל עקב ח, א. תניא פל\"ח (נ, א. נא, א)."],["1849","36","<b>שהם</b>: ב: ושרש."],["1850","37","<b>יפה שעה אחת</b>: אבות פ\"ב, מי\"ז."],["1851","38","<b>תשובה. . המעשים טובים כלומר מאירים</b>: ראה גם שע\"ת עב, ד ובהערה 26."],["1852","39","<b>בעוה\"ב נשמות נהנין מזיו</b>: ראה ברכות יז, א."],["1853","40","<b>תחת אשר לא עבדת</b>: תבוא כח, מז."],["1854","41","<b>מוטב דלידיינו</b>: חגיגה טו, ב. ראה גם לעיל ס\"ע קט ואילך ובהערה 48."]]],[4801940278,"המצות א\"כ יהי' שמחתו במצות יותר גדולה עד שיפקיר כל התענוגים לגביהם, אך זהו מצד טוב לבב כי טוב הוא בחי' אור<sup data-n=\"1855\">42</sup> שמאיר הלבב שבתפלה בכל המצות ועי\"ז נמשך השמחה שבהם מבחי' עצמות אא\"ס כו'<sup data-n=\"1856\">43</sup>.\n<b>והנה</b> כמו שבעבודה למטה יש בחי' לב ואברים ומקבלים דין מן דין כך למעלה קוב\"ה שהוא הוי' לבא דכל עלמין<sup data-n=\"1857\">44</sup>, כי הנה כתיב על הכסא כמראה אדם<sup data-n=\"1858\">45</sup> הגם שאין לו גוף<sup data-n=\"1859\">46</sup> ודמות הגוף אעפ\"כ כחות אלקיים המשפיעים בהשתל' הוא כדוגמת אדם שלמטה, למשל כח המשגיח על כל הנבראים נק' עיני ה' וכן כח השמיעה כו' נק' איברים דשכינתא וחיות הפנימי' שבאיברים אלו הוא בחי' לבא דכל עלמין כמשל הלב שהוא באמצעי' דכל האברים ומחי' לכולם כך למעלה אא\"ס המחי' כל העולמות שנק' ממכ\"ע נק' ליבא דכל עלמין והוא ל\"ב ויאמר אלקים דמע\"ב<sup data-n=\"1860\">47</sup> והוא משפיע אור וחיות לכולם, אך אעפ\"כ ג\"כ הוא מקבל מכולם כי ע\"י ביטול הנבראים בנשמות ומלאכים והעלאת מ\"ן במעשה התחתונים שעולים לאשתאבא בגופא דמלכא<sup data-n=\"1861\">48</sup> עי\"ז נמשך תוס' אור וחיות מבחי' סוכ\"ע [שהוא בחי' כי לא אדם] לבחי' ממכ\"ע כמאמר ישראל מפרנסין לאביהם שבשמים<sup data-n=\"1862\">49</sup> אך אחר שמקבל על ידם תוס' אור וחיות מבחי' הסובב<sup data-n=\"1863\">50</sup> הוא נעשה משפיע לכולם ונמצא שהוא כדוגמת הלב ואברים שמקבלים זה מזה כו' וד\"ל.\n<b>והנה</b> כ\"ז הוא עכשיו בזמה\"ג שהתפלה במקום קרבן כמאמרם תפלה כנגד תמידים תקנום<sup data-n=\"1864\">51</sup> אך מלשון זה<sup data-n=\"1865\">52</sup> נראה שהקרבן עצמו גבוה מן התפלה ולכן בזמן הבית לא היו צריכים לתפלה<sup data-n=\"1866\">53</sup> ולכן אנו אומרים ושם נעשה כמצות רצוניך<sup data-n=\"1867\">54</sup> דמשמע שעכשיו ע\"י התפלה אינו עדיין כמצות רצונך. אך הענין הוא דבזמן הבית הי' ג\"כ ענין העלאת הקרבן מצד הבהמה שהיו שורפין אותה ע\"ג המזבח ומתעלית לשרשה וע\"י התשובה שהי' בעת הקרבת הקרבן מצד זה הי' גורמים למעלה תוס'",[["1855","42","<b>טוב הוא בחי' אור</b>: ראה גם ב\"ר פצ\"ב, ו."],["1856","43","<b>כו'</b>: ב: כ\"ז הוא בזה\"ג ואין לו אלא התפלה. ואולי מיותר."],["1857","44","<b>קוב\"ה. . לבא דכל עלמין</b>: מובא בשם הזהר במאמרי אדה\"ז תקס\"ח ח\"א ס\"ע יד (מאמרי אדה\"א הנחות תקע\"ז ע' רסד). ראה גם הנסמן ע\"ז בתקס\"ח ח\"ב ע' תשמו."],["1858","45","<b>על הכסא כמראה אדם</b>: ראה יחזקאל א, כו."],["1859","46","<b>שאין לו גוף</b>: ע\"פ פיוט יגדל. פיה\"מ להרמב\"ם מס' סנהדרין פ\"י היסוד הג'."],["1860","47","<b>ל\"ב ויאמר אלקים דמע\"ב</b>: נמנו בפרטיות בתקז\"ח קיב, ג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכה. וש\"נ. שעה\"י קלב, א ובהערה 3."],["1861","48","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' מה. תו\"ח בראשית מ, ב הערה 25."],["1862","49","<b>ישראל מפרנסין לאביהם שבשמים</b>: זהר ויקרא ז, ב. ראה גם תו\"ח משפטים ח\"ב רצג, ד הערה 52. סה\"מ תרכ\"ט ע' קיב."],["1863","50","<b>הסובב</b>: ב: סוכ\"ע."],["1864","51","<b>תפלה כנגד תמידים תקנום</b>: ראה ברכות כו, ב. לקו\"ת פינחס עז, ג."],["1865","52","<b>זה</b>: ניתוסף ע\"פ ב."],["1866","53","<b>בזמן הבית לא היו צריכים לתפלה</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' שכב. מאמרי אדה\"א דברים ח\"ב ע' תקסד. נ\"ך ע' דש."],["1867","54","<b>ושם נעשה [ב ניתוסף: ל</b>פניך] כמצות רצונך: מוסף ליו\"ט [בדילוג]. ראה ד\"ה אוסרי לגפן תקס\"ד נדפס בתו\"ח ויחי רלו, א. רלח, א. מאמרי אדה\"א שמות ח\"א ע' רכו. וש\"נ. תו\"ח שמות ח\"א כב, ג. וש\"נ."]]],[4801940328,"אורות מבחי' סוכ\"ע לבחי' ממכ\"ע, וזהו ריח ניחוח לה'<sup data-n=\"1868\">55</sup> ריח הוא בחי' ההעלאה וניחוח הוא בחי' המשכה בתוס' אור להוי' וזהו כמו העבודה דעכשיו שע\"י התפלה רק הוא יותר גבוה ולכן הי' נפעל ענין ההעלאה וההמשכה בהתגלות לעין כל כמו אש שלמעלה שהי' יורד ע\"ג המזבח<sup data-n=\"1869\">56</sup> ואכיל קרבנין<sup data-n=\"1870\">57</sup> שהיו רואים התכללות הבהמה באש שלמעלה בגילוי, משא\"כ עכשיו בזמה\"ג ענין ההעלאה וההמשכה הוא בפנימי' בהעלם ולא בגילוי וכמ\"ש אותותינו שהוא בחי' האותיות הפועלים העלאה וההמשכה לא ראינו<sup data-n=\"1871\">58</sup> כי מוסתר מאד הנהגת הוי' ומלובש בדרכי הטבע, והטעם לזה הוא מטעם המקדש שהי' פועל גילוי שכינה ולא בהעלם וכמאמר ועשו לי מקדש<sup data-n=\"1872\">59</sup> ושכנתי בתוכם. ועם זה יובן שהתפלה נק' עבודה שבלב מטעם שהוא רק בפנימי' ולא בהתגלות כלל ולכן הוא רק במקום קרבן משא\"כ בזה\"ב נא' שמחת לבו כמשל אדם בעת שמחתו נעשה אצלו פתיחת הלב עד שמגלה שמחתו לעין כל, משא\"כ כשאינו בעת שמחתו אע\"פ שיש לו עונג מאיזה דבר נעלם העונג במוחו ולבבו ואינו נראה לזולתו כלל כו' וד\"ל.\n<b>ועם</b> זה יובן ענין והצרוע אשר בו הנגע דהוא קאי על בהמ\"ק דהנה כל הנהגה הנ\"ל דלב ואיברים בגשמי' הוא רק כשהוא בריא אבל כשיארע איזה קלקול באיזה אבר אז אינו נמשך החיות מן הלב אל אבר המקולקל כלל וגם ממילא מפסיק הסיבוב והילוך מן האבר הנ\"ל אל הלב ועי\"ז יש קצת חלישות בלב מצד שאינו מקבל מכל האיברים כי חסר כח הפרטי דאבר המקולקל, כך למעלה בקוב\"ה שהוא הוי' לבא דכל עלמין כשיש איזה קלקול למטה מצד העדר מעשה התחתונים או מצד עוונות המבדילין כביכול הקלקול למעלה והוא במה שהאור נעדר היינו התוס' אור מסובב לממלא וזהו אשר בו הנגע בבהמ\"ק של מעלה שהוא הכלי שעל ידו ניתוסף האור למעלה וגם למטה בנש\"י כמאמר ושכנתי בתוכם הנ\"ל, וקלקול זה נק' בשם נגע וטעם הדבר כי הנה בס\"י אמר שאין לך למעלה מן עונג ואין לך למטה מנגע<sup data-n=\"1873\">60</sup> כי נגע הוא ענג בהיפוך אתוון<sup data-n=\"1874\">61</sup> ויובן ע\"פ מש\"א ר\"ע אם לעוברי רצונו<sup data-n=\"1875\">62</sup> כך לעושי רצונו עאכו\"כ ובאמת ק\"ו לא שייך רק בדברים הדומים זל\"ז, אך הענין הוא דבאמת שרש תענוגי עוה\"ז הוא מבחי' תענוג העליון רק שהוא מהפסולת שלו שנפל למטה כמשל המאכל המתברר באצטומכא ורוחנית שבו עולה למעלה להוסיף חיות במוח ולב ופסולת שלו נדחה למטה עד שנעשה מאכל לד\"א, כך הוא במזון ושפע עליונה הרוחניות שבו נעשה חיות בגעה\"ע וגעה\"ת והפסולת נדחה לחוץ למטה ומזה נמשך תענוגי עוה\"ז למטה וזהו מאמר ר\"ע הנ\"ל שאם הפסולת כ\"כ גדול איך הוא פנימי'",[["1868","55","<b>ריח ניחוח לה'</b>: ויקרא א, ט."],["1869","56","<b>אש שלמעלה. . המזבח</b>: תו\"כ ויקרא א, ז. יומא כא, ב."],["1870","57","<b>ואכיל קרבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שער האמונה עט, ב הערה 13."],["1871","58","<b>אותותינו. . לא ראינו</b>: תהלים עד, ט."],["1872","59","<b>ועשו לי מקדש</b>: תרומה כה, ח."],["1873","60","<b>בס\"י אמר. . למטה מנגע</b>: ראה שם [מנטובה שכ\"ב] פ\"ב, מ\"ב. תו\"ח בשלח ח\"א רב, ג הערה 963."],["1874","61","<b>נגע הוא ענג בהיפוך אתוון</b>: ראה ס\"י פ\"ב, מ\"ד ובמפרשים שם. שע\"ת נג, ד הערה 40."],["1875","62","<b>אם לעוברי רצונו</b>: ראה מכות בסופה. לקו\"ת בהעלותך לג, ד. שלח מז, א. לעיל ע' קט."]]],[4801940376,"העונג הרוחני' הנמשך לעושי רצונו וזהו\"ע הנגע ששרשו העונג שלמעלה בעילוי אחר עילוי אך שנפל למטה מטה ונעשה בחי' נגע, וענין הנגע בגשמיות הוא לבנה כמאמר בהרת עזה כשלג<sup data-n=\"1876\">63</sup> שני' לה כסיד ההיכל שאת כצמר כו' והטעם הוא כי נסתלקו הדמים ונשאר לבן כך הוא הסתלקות חיות אלקי והתעלמותו בחיצוני' דאזלעו\"ז ולכן שער לבן הוא סי' טומאה<sup data-n=\"1877\">64</sup> כי השערות הוא מקור יניקת החיצוני' וזהו\"ע והצרוע אשר בו הנגע שהוא חורבן בהמ\"ק שנעשה התגברות יניקת החיצוני' מהקדושה יתר מכפי המדה שזהו\"ע שתי חורבנות שהם שתים שהן ארבע שהוא שעבוד ארבע מלכיות שנעשה מצד הפגם בד' אותיות הוי'.\n<b>והנה</b> תיקון הנגעים נא' ע\"ז נגע כי תהי' באדם<sup data-n=\"1878\">65</sup> והובא אל הכהן כי הכהן מתקן הנגעים ע\"י ראיית הנגעים וע\"י העלאת הנרות, כי הנה עד\"מ באדם התחלת הרפואה הוא כשמבדילין הקלקול שבו בהעלם ומגלים אותו ואח\"כ יוכלו לרפאו לגמרי, כך הוא בנפש כל דרכי איש זך בעיניו<sup data-n=\"1879\">66</sup> עד שאינו מרגיש הריחוק שלו כלל רק ע\"י ההתפעלות רשפי אש באלקות אזי נבדיל ממנו כל תענוג ורצון זר עד שמרגיש אפי' דק שבדקו', ולכן בש\"ע או' סלח לנו<sup data-n=\"1880\">67</sup> וכן אחרי התפלה מצד התפעלות רשפי אש שבק\"ש מרחיק<sup data-n=\"1881\">68</sup> הריחוק שבנפשו, וגם ע\"י הראי' דראה נתתי לפניך את החיים כו' ובחרת בחיים<sup data-n=\"1882\">69</sup> כו'<sup data-n=\"1883\">70</sup> המות הוא תענוגי עוה\"ז שיש בהם הפסד וכיליון וחיים הוא תענוג ניצחי וע\"י הראי' באמת<sup data-n=\"1884\">71</sup> אלקות דכולא קמי' כל\"ח הוא בוחר בחיים וממילא נבדל ממנו כל רצון זר. וזהו\"ע ראיית הנגעים שע\"י הכהן שהוא להרגיש בנפשו כל רצון זר ולהבדיל אותו ומצד הרגשת הריחוק נגלה עצם נפשו בחילא יתיר ליכלל במהו\"ע כי מצד המנגד יותר יתגלה העצם וזהו העלאת הנרות וכ\"ז הוא ע\"י הכהן שהוא הקב\"ה למעלה כמאמר אלקיכם כהן הוא<sup data-n=\"1885\">72</sup> ולמטה ע\"י אהרן וזהו\"ע התשובה שהיא הרפואה כו' וד\"ל.\n<b>וזהו</b> והצרוע אשר בו הנגע כו'<sup data-n=\"1886\">73</sup> בגדיו יהיו פרומים אלו בגדי כהונה, כי הנה מש\"א אלקיכם כהן הוא זהו בחי' רב חסד שבעצמיות המאציל ובהשתל' רבות בעולם הבריאה הוא בחי' מיכאל כהנא רבא ונק' בגדי כהונה שהוא בחי' לבוש דרב חסד הנ\"ל והוא בחי' אש שלמעלה שהוא ארי' דאכיל קורבנין שהוא יורד בגילוי בזמן בהמ\"ק משא\"כ בזמן הגלות הגם שנעשה ענין ההעלאה ע\"י התפלה שהו\"ע התשובה שיש בזה ב' ענינים הנ\"ל דראיי' הנגעים והעלאת הנרות כנ\"ל שנעשה ע\"י רב חסד אבל הכל בפנימי' משא\"כ הלבוש דבגדי כהונה חסר עכשיו בזמה\"ג ולכן אין אש שלמעלה בגילוי וזהו בגדיו יהיו פרומים וראשו יהי' פרוע",[["1876","63","<b>בהרת עזה כשלג</b>: נגעים בתחלתה."],["1877","64","<b>שער לבן הוא סי' טומאה</b>: רמב\"ם הל' טומאת צרעת רפ\"ב."],["1878","65","<b>נגע כי תהי' באדם</b>: ראה תזריע יג, ט."],["1879","66","<b>כל דרכי איש זך בעיניו</b>: משלי טז, ב."],["1880","67","<b>בש\"ע או' סלח לנו</b>: ראה גם לקמן מאמר ד\"ה בשברי לכם תקצ\"ט ובהערה 64."],["1881","68","<b>מרחיק</b>: ב: מרגיש."],["1882","69","<b>דראה נתתי. . ובחרת בחיים</b>: ראה נצבים ל, טו. יט."],["1883","70","<b>כו'</b>: ב: כי."],["1884","71","<b>באמת</b>: שם: באמיתת."],["1885","72","<b>אלקיכם כהן הוא</b>: סנהדרין לט, א."],["1886","73","<b>כו'</b>: ב: ליתא."]]],[4801940420,"היינו כידוע דרישא שכיבא לעפרא<sup data-n=\"1887\">74</sup> והוא ענין השפלת המוח בענינים זרים בתאוות ומח\"ז והו\"ע כובד ראש כו'.\n<b>ועל</b> שפם יעטה<sup data-n=\"1888\">75</sup> הוא הסתלקות כח הדבור עד שנשאר רק בחי' אלם מאלקים<sup data-n=\"1889\">76</sup> שע\"ז נא' כרחל לפני גוזזי' נאלמה<sup data-n=\"1890\">77</sup> ולכן המה מקבלים השפע בבחי' יש נפרד ונק' גוזזי' משא\"כ בזמן הבית שהי' הדבור מאיר בגילוי הי' נכנעים לקדושה שזהו\"ע חיבור השערות כו' וד\"ל. [וכמבואר במ\"א בענין אלה מסעי<sup data-n=\"1891\">78</sup> כו'].\n<b>וטמא</b> טמא יקרא היינו שתי חורבנות הנ\"ל וארז\"ל מחויב להודיע צערו לרבים<sup data-n=\"1892\">79</sup> ורבים מבקשים עליו רחמים. וביאור הדבר היינו כמ\"ש רחל מבכה על בני' ולא אמר בוכה רק מבכה לאחרים וזהו תיקון חצות שנק' תיקון רחל והיינו ע\"י המרירות על כי איננו<sup data-n=\"1893\">80</sup> כי הנה כתי' עוברי בעמק הבכא<sup data-n=\"1894\">81</sup> שהוא הגיהנם מעין ישיתוהו והיינו מצד שמרגישים התענוג שבג\"ע איך שנשמות נהנין מזיו השכינה והמה נעדרים מזה וזהו הצער שלהם שגורם בכי' עמוקה מצד העדר העונג, והנה זה העונג שנשמות נהנין ממנו בג\"ע הוא רק בחי' זיו השכינה בלבד והארה בעלמא מבחי' מל' דאצי' אבל בבהמ\"ק נאמר ושכנתי בתוכם שהו\"ע הלבשת המל' בעצמה ומהותה בהיכל ק\"ק שבבהמ\"ק ולכן הי' אז מאיר אהוי\"ר בהתגלות והאה' הוא בחי' תשובה לדבקה בעצם אלקות והיראה הוא ג\"כ בחי' ביטול פנימי' לעצמות אלקות וא\"כ עכשיו בזה\"ג שנעדר בחי' זאת שהוא בחי' הסתלקות דעצמות אלקות א\"כ הבכי' יותר עמוקה, וענין ההסתלקות זאת יובן ע\"פ המבואר בתיבת אחד דח' וד' היינו ז' רקיעים וארץ שהו\"ע ההשתל' עד רום המעלות והביטול<sup data-n=\"1895\">82</sup> שלהם הוא בא' אלופו של עולם<sup data-n=\"1896\">83</sup> והוא בחי' הביטול דדעה עליונה דהיינו איך דכולא קמי' כל\"ח [ולעתיד נאמר והי' הוי' אחד<sup data-n=\"1897\">84</sup> ושמו אחד שיהי' הגילוי למטה כמו למעלה ויהי' למטה ג\"כ ביטול אמיתי ומעין זה הי' בביהמ\"ק] וזהו\"ע היראה שהי' בביהמ\"ק ביטל פנימי' ונק' ירושלים יראה שלם<sup data-n=\"1898\">85</sup>. והנה עכשיו מוסתר מאד היראה הנ\"ל עד",[["1887","74","<b>דרישא שכיבא לעפרא</b>: ראה זהר במדבר קיט, ב. ע\"ח שער מיעוט הירח של\"ו, פ\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' יד."],["1888","75","<b>ועל שפם יעטה</b>: המשך הכתוב והצרוע אשר בו הנגע (תזריע יג, מה)."],["1889","76","<b>אלם מאלקים</b>: ראה ע\"ח שער מוחין דקטנות שכ\"ב, ספ\"ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תפו."],["1890","77","<b>כרחל לפני גוזזי' נאלמה</b>: ראה ישעי' נג, ז. תו\"ח ויצא קסו, ג הערה 53."],["1891","78","<b>בענין אלה מסעי</b>: ראה לקו\"ת מסעי פח, ג."],["1892","79","<b>וטמא. . מחויב להודיע צערו לרבים</b>: תזריע שם. ראה שבת סז, א."],["1893","80","<b>רחל מבכה על בני'. . כי איננו</b>: ירמי' לא, יד."],["1894","81","<b>עוברי בעומק הבכא</b>: תהלים פד, ז. ערובין יט, א."],["1895","82","<b>אחד. . ז' רקיעים וארץ. . והביטול</b>: ראה שו\"ע אדה\"ז הל' ק\"ש סס\"א, ס\"ו. ראה גם לקו\"ת תזריע כג, ג. שמע\"צ פח, ב. תו\"א וארא נה, ב ואילך. סהמ\"צ להצ\"צ ע' קכד ואילך. סה\"מ תרכ\"ט ע' קסד."],["1896","83","<b>אלופו של עולם</b>: לשון ב\"ר פ\"כ, ב."],["1897","84","<b>והי' </b>[ב: יהי']<b> הוי' אחד</b>: זכרי' יד, ט."],["1898","85","<b>ירושלים יראה שלם</b>: ראה ב\"ר פנ\"ו, י. תוד\"ה הר תענית טז, א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רצה ובהנסמן במ\"מ לשם. עט\"ר שער ר\"ה ע' 56. סה\"מ תרכ\"ז ע' תיד. וש\"נ."]]],[4801940460,"שמתלבשת ביראה חיצוני' דיראת העונש והיינו מצד התלבשות אלקו' בבחי' גלות וזהו קוב\"ה בגלותא אסתלק לעילא ולעילא<sup data-n=\"1899\">86</sup> שהו\"ע הסתלקות הא' דאחד. והנה ע\"ז יתגדל המרירות ביותר ממרירות שבגיהנם והיינו כי איננו שנעדר התגלות מהו\"ע שהי' בזמן הבית, והנה עי\"ז יעורר רח\"ר על גלות השכינה הנ\"ל [ולא על עצמו] ועי\"ז יהי' הגילוי דלעתיד שיהי' למטה כמו למעלה הוי' אחד ושמו אחד ועז\"נ מי יתן טהור מטמא שהוא הגילוי דלעתיד שיהי' מצד התעוררות רח\"ר שבזמה\"ג על הסתלקות אלקות כו' וזהו לא אחד<sup data-n=\"1900\">87</sup> כו' וד\"ל.",[["1899","86","<b>קוב\"ה בגלותא אסתלק לעילא ולעילא</b>: ראה זהר ויגש רי, א. ויקרא כ, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ג. וש\"נ. תו\"ח שמות ח\"א לט, סע\"א ואילך ובהערה 72."],["1900","87","<b>מי יתן טהור מטמא. . לא אחד</b>: איוב יד, ד."]]],[4801940103,"<b>בעז\"ה פ' תזריע מצורע תקצ\"ט מה שנתחדש אצלי בענין והצרוע ששמעתי מפי אדמו\"ר שליט\"א בפרילוק בפ' דברים ורשמתי בדרך קצרה כדי שלא תשכח ממני</b>\n<b>הנה</b> להבין המדרש והצרוע זה<sup data-n=\"1901\">1</sup> בהמ\"ק<sup data-n=\"1902\">2</sup> בגדיו יהיו פרומים אלו בגדי כהונה, יש להקדים ענין בהמ\"ק שנק' שמחת לבו<sup data-n=\"1903\">3</sup>, וגם להבין מ\"ש ברמ\"ז<sup data-n=\"1904\">4</sup> מכאן שאותו בהמ\"ק בנוי ומשוכלל ברום חביון ולא חסר לו אלא להיות בעולם וכמ\"ש בונה ירושלים<sup data-n=\"1905\">5</sup> ולא יבנה ל' עתיד<sup data-n=\"1906\">6</sup> כו', כי לכאורה אינו מובן דגם ל' בונה לא יתכן דמשמע ל' הוה ובתחילת דבריו אמר בנוי ל' עבר. אך יש להקדים ענין התפילה במקום קרבן<sup data-n=\"1907\">7</sup> ואעפ\"כ אינו כמו קרבן ממש ולכן אומרים ושם נעשה כמצות רצונך<sup data-n=\"1908\">8</sup>, דמשמע דעכשיו אינו עדיין כמצות רצונך ממש, כי הנה ירידת הנשמה בגוף הוא לצורך עלי'<sup data-n=\"1909\">9</sup> ועלי' זאת הוא בתפילה, כי הנה בנשמה יש שכל ומדות והשכל הוא החוש להשיג איך שהוי' אלקינו בחי' יחיד הוא הוי' אחד<sup data-n=\"1910\">10</sup> כי גם הוי' המלובש בהשתלשלות מרכ\"ד עד סוכ\"ד במל' דמל' דעשי' נק' אחד, להיותם מיוחדים בלתי",[["1901","1","<b>הנה להבין המדרש והצרוע זה בהמ\"ק</b>: דרוש ר' הלל כנ\"ל בכותרת.\nראה המאמר שנדפס לפנ\"ז."],["1902","2","<b>והצרוע זה בהמ\"ק</b>: תזריע יג, מה [בדילוג]. ראה פתיחתא דאיכ\"ר כא. יל\"ש עה\"פ (סוף רמז תקנא). וראה גם ויק\"ר פי\"ז, ז."],["1903","3","<b>בהמ\"ק שנק' שמחת לבו</b>: שה\"ש ג, יא. תענית כו, ב (במשנה)."],["1904","4","<b>מ\"ש ברמ\"ז</b>: לזח\"ג רכא, א (קעח, ב בדפי הספר)."],["1905","5","<b>בונה ירושלים</b>: תהלים קמז, ב."],["1906","6","<b>ל' עתיד</b>: א וברמ\"ז: לעתיד."],["1907","7","<b>התפילה במקום קרבן</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["1908","8","<b>ושם נעשה </b>[א ניתוסף: כו']<b> כמצות רצונך</b>: מוסף ליו\"ט. ראה ד\"ה אוסרי לגפן תקס\"ד נדפס בתו\"ח ויחי רלו, א. רלח, א. מאמרי אדה\"א שמות ח\"א ע' רכו. וש\"נ. תו\"ח שמות ח\"א כב, ג. וש\"נ."],["1909","9","<b>ירידת הנשמה. . לצורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["1910","10","<b>יחיד. . אחד</b>: ראה גם לקמן מאמר ד\"ה ענין העבודה דיוה\"כ ובהערה 6."]]],[4801940167,"נבדלים מרכ\"ד עד סוכ\"ד וכמאמר אנת הוא דקשיר לון<sup data-n=\"1911\">11</sup> ומיחד לון והוא הוא בחי' יחיד בעצמו ואפי' בחי' א\"ס המלובש במל' דעשי' הוא בחי' יחיד ממש [וכל' רש\"י בפ' בראשית על ביאור מלת אחד<sup data-n=\"1912\">12</sup> יחיד בעולמו בעולמו דייקא כו' וד\"ל] רק אנו קורין בשם אחד מצד שלעינינו נגלה ההשתלשלות למציאות דבר ואנו מרגישים שהוא המייחדם בכדי להיות מגיד מראשית אחרית<sup data-n=\"1913\">13</sup> שהו\"ע המשכת השפע מרכד\"ר עד סוכד\"ר שהוא ע\"י היחוד דייקא ולכן אנו קורין בשם אחד אבל קמי' אין כל ההשתלשלות תופס מקום ולכן גם כשהוא נתפס הוא בלתי נתפס (דלא כפילוסופים עמב\"י שאמרו טבע קיים<sup data-n=\"1914\">14</sup> ה' יכפר בעדם כו' וד\"ל) והוא בבחי' יחיד כו' וזהו אני הוי' לא שניתי<sup data-n=\"1915\">15</sup> שגם בחי' שם הוי' המלובש בבחי' אני אחרון<sup data-n=\"1916\">16</sup> מל' דמל' דעשי' אין בו שינוי כלל.\n<b>ולקרב</b> אל השכל [מצד נה\"ט המסתיר אבל הנשמה בעצמה כשאינה מלובשת בנה\"ט אין צריך לקרב אל ההשגה רק רואה בבחי' ראי' דחכ' שבנה\"א כו'] אומר בשכמל\"ו<sup data-n=\"1917\">17</sup>, היינו שכללות ההשתלשלות אינו תופס מקום כלל בעצמות ע\"ד המלך עם אנשי מדינתו שיש בו ג' מדריגות, הא' עצמות ההתנשאות כמו שהוא מרומם לבדו שמבחי' זאת אין לו שייכות עם אנשי המדינה רק מה שעולה ברצונו למלוך על עם שזה נק' התנשאות על עם הוא בחי' לבוש לגבי עצם הרוממות ומלבוש זה נמשך הארה בעלמא מצומצמת על אנשי המדינה והוא במה שמלך שמו נק' עליהם כו' כי עצם הלבוש הוא בלתי מוגבל ויכול להתפשט על מדינות רבות לאין שיעור אבל שם המתפשט על אנשי המדינה הוא מצומצם לפי ערכם, אך מובן מכל הנ\"ל שהמשכת הלבוש עם השם להיות מלך על עם אינו תופס מקום כלל בעצם ההתנשאות שלו וראי' לזה שאין לו שום ירידה מעצמותו להיות משפיע התנשאות שלו על עם ואדרבה כל מה שנעלם יותר ומרומם בעצמותו יותר יומשך ההתנשאות על עם יותר לפעול בם ענין אימה וביטול כו', ולכן המלך אין רואים אותו כ\"א פ\"א בשנה, אך ביטול הזה שהוא מפשיטם לגמרי מבחי' יש הוא הסיבה שיוכלו לקבל אור פני מלך כשיתגלה פ\"א בשנה שעי\"ז יתיחדו כולם באהבה אפילו כל השרים המנגדים זה לזה כו' ויתכללו כל ההפכים שבהם, ועי\"ז הוא עיקר קיומם וזהו פנימי' הכוונה של המלוכה [משא\"כ כשמתגלה בבחי' אימה עליהם לא יפעול בשרים המנגדים רק ביטול לפי שעה בעת שרואים פניו אבל אח\"כ בעת שהולכים מלפניו יהיו מנגדים כמקדם כו'], אך גם הגילוי הזה דאור פני מלך אינו תופס מקום כלל בעצם ההתנשאות שלו להיותו הארה בעלמא ממנו כו' וד\"ל.",[["1911","11","<b>אנת הוא דקשיר לון</b>: ראה ת\"ז בהקדמה יז, א."],["1912","12","<b>רש\"י בפ' בראשית. . אחד</b>: א, ה."],["1913","13","<b>מגיד מראשית אחרית</b>: ישעי' מו, י."],["1914","14","<b>כפילוסופים עמב\"י שאמרו טבע קיים</b>: ראה פלח הרמון בראשית מה, ג. שה\"ש ס\"ע 58 ואילך. ע' קכו. שו\"ת הרשב\"א סתי\"ח הובא בס' החקירה ע' 68 ואילך. סה\"מ תרמ\"ט ע' עדר. וראה שו\"ת הרשב\"א ס\"ט. מאמרי אדה\"ז על ענינים ס\"ע לח ואילך. שם ע' מא ואילך."],["1915","15","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["1916","16","<b>אני אחרון</b>: ישעי' מד, ו."],["1917","17","<b>אומר בשכמל\"ו</b>: בק\"ש — פסחים נו, א."]]],[4801940226,"והנמשל יובן למעלה כשעלה ברצונו הפשוט להטיב<sup data-n=\"1918\">18</sup> שזהו חפץ חסד שבעצמי', וענין ההטבה הוא שכל הנבראים יהיו מרכבה להדבק בו ית' ועי\"ז יתייחדו כולם מבחי' ההתחלקות ופירוד שלהם וזהו עיקר קיומם, אך איך יהי' התכללות אחרי התחלקות שלהם לזאת נתלבש הרצון להיטיב ברצון למלוך [מח' דאנא אמלוך מל' דא\"ס<sup data-n=\"1919\">19</sup> כו']. וזהו ענין לבוש המלוכה כמאמר ה' מלך גאות לבש<sup data-n=\"1920\">20</sup>. אך הלבוש הוא בחי' א\"ס לזאת שיער בעצמו בכח<sup data-n=\"1921\">21</sup> מה שעתיד להיות בפועל, ושיעור הזה פעל הצמצום להתצמצם ולהתעלם כללות הארת מדת המלוכה שהוא בחי' א\"ס ולהיות נמשך הארה פרטי' לפ\"ע ההשתלשלות שזהו בחי' הקו שלאחר הצמצום, ובחי' הקו נמשך בכל עולם האצי' עד סופו בחי' יסוד ז\"א סיומא דגופא<sup data-n=\"1922\">22</sup> כו', שזהו בחי' הביטול בעולם הנאצלים להיות בחי' איהו וחיוהי חד כו' וגרמוהי חד<sup data-n=\"1923\">23</sup> כו', אך בבחי'<sup data-n=\"1924\">24</sup> יסוד ז\"א [מצד הארת יסוד אבא שבתוכו שהוא ארוך יעויין בב\"ז במאמר מחצית השקל<sup data-n=\"1925\">25</sup> ] להמשיך בחי' ביטול זה גם בבי\"ע עולמות הנפרדים [אעפ\"י ששם אין בחי' המשכת הקו כו' שיהי' בתכלית הביטול<sup data-n=\"1926\">26</sup> ] עד שאפי' צבא השמים היותר אחרונים כמו הגלגלים משתחוים ולכן מסבבים<sup data-n=\"1927\">27</sup> כידוע [אך מצד שאין הקו נמשך אינו מאיר בחי' ביטול הזה בבחי' התיישבות בהשגה והתפעלות שלהם רק הביטול בבחי' נקודה למעלה מן הטעם וזהו דיסוד אימא קצר<sup data-n=\"1928\">28</sup> כו' והסיבה לזה הוא מצד שהקו מסתיים ואינו נמשך בבי\"ע כו' כנ\"ל בד\"א<sup data-n=\"1929\">29</sup> כו']. וזהו ברוך יסוד ז\"א ובו נמשך שם הארת הקו שנמשך מבחי' כבוד לבוש המלוכה [כידוע דר\"י קרא למאני מכבדותא<sup data-n=\"1930\">30</sup> כו'] הנמשך מבחי' מלכותו העצמי, אך השתחואה זאת שהוא בחי' הביטול הוא הכלי שיוכלו לקבל אור פני מלך חיים שהוא בחי' ח\"ח<sup data-n=\"1931\">31</sup> הנ\"ל וזהו עשיית שלום בפמשמ\"ע ובפמשמ\"ט שזהו עיקר הכוונה והוא בחי' קיום ההשתלשלות יעוי' במא' דוהי' מעשה הצדקה<sup data-n=\"1932\">32</sup> כו' וד\"ל. ובחי' ברוך הוא יסוד ז\"א ל' נפעל<sup data-n=\"1933\">33</sup> שמקבל בתוכו כל הברכות דבחי' קו\"ח וגם הוא מקור כל הברכות להשפיע בבי\"ע כו' וד\"ל. אך לבוש המלוכה וח\"ח שניהם אינם רק הארה בעלמא מבחי' ההתנשאות עצמי' דמלכותו העצמי' הנק' מלך יחיד כו'. ונמצא שכל",[["1918","18","<b>כשעלה ברצונו הפשוט להטיב</b>: ראה ע\"ח שער עגו\"י ש\"א, ענף ב. לעיל ע' לה."],["1919","19","<b>מח' דאנא אמלוך מל' דא\"ס</b>: ראה גם לעיל ע' סט. וש\"נ."],["1920","20","<b>ה' מלך גאות לבש</b>: תהלים צג, א."],["1921","21","<b>שיער בעצמו בכח</b>: ראה מק\"מ לזהר בראשית טו, א. מאמרי אדה\"א קונטרסים ע' רא. וש\"נ. לעיל ע' פה. וש\"נ."],["1922","22","<b>יסוד ז\"א סיומא דגופא</b>: ראה ת\"ז בהקדמה יז, א. הנסמן במאמרי אדה\"א קונטרסים ע' רכד."],["1923","23","<b>איהו וחיוהי. . וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב."],["1924","24","<b>אך בבחי'</b>: א: אבל בחי'."],["1925","25","<b>בב\"ז במאמר מחצית השקל</b>: תשא נד, ג."],["1926","26","<b>כו' שיהי'. . הביטול]</b>: א: כו'] שיהיו. . הביטול."],["1927","27","<b>הגלגלים משתחוים ולכן מסבבים</b>: ראה סידור שער המילה קמב, ב. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שצד."],["1928","28","<b>דיסוד אימא קצר</b>: ראה ביאוה\"ז שם."],["1929","29","<b>כנ\"ל בד\"א</b>: א: כנלע\"ד( ) בדרך אפשר. ג: כנ\"ל בדרך אפשר."],["1930","30","<b>דר\"י קרא למאני מכבדותא</b>: ראה שבת קיג, א."],["1931","31","<b>ח\"ח</b>: חפץ חסד."],["1932","32","<b>במא' דוהי' מעשה הצדקה</b>: אגה\"ק סי\"ב."],["1933","33","<b>הוא יסוד ז\"א ל' נפעל</b>: א: ל' פעל. ג כבפנים."]]],[4801940279,"ההשתלשלות וביטולם והארת אור פני מלך חיים<sup data-n=\"1934\">34</sup> אינו תופס מקום כלל בעצמו. והנה כאשר הנשמה מתבוננת בהתבוננות זאת דביטול ההשתלשלות במקורו אזי ממילא נעשה ג\"כ בחי' ביטול בנפשו הטבעי' עד שלא תוכל להסתיר על אור הנשמה ואז נתגלה מדת המלוכה דנה\"א שהוא ואהבת היינו להיות מי לי בשמים<sup data-n=\"1935\">35</sup> כלה שארי ולבבי<sup data-n=\"1936\">36</sup> כו' [והטעם ידוע דמשכן הנשמה במוח<sup data-n=\"1937\">37</sup> ולכן אצל כל איש ישראל אין הסתר כלל במוחו ויודע האמת אם לא שפגם ח\"ו אז נעשה טמטום המוח<sup data-n=\"1938\">38</sup> וכמ\"ש עוונותי עברו ראשי<sup data-n=\"1939\">39</sup>, אבל המדות שבנה\"א מתפשטים בלב בחלל הימיני ויש שם בחי' אזלעו\"ז<sup data-n=\"1940\">40</sup> מדות דנה\"ט בחלל השמאלי להסתיר, והנה בנשמה שבמוח יש ג' בחי' הא' בחי' כתר שבה שהוא הרצון<sup data-n=\"1941\">41</sup> והתקשרות טבעי לעצמות אא\"ס מצד ששרשה משם, והב' החכמה ראי'<sup data-n=\"1942\">42</sup> בבחי' ביטול ההשתלשלות איך דכולא קמי' כלא חשיב<sup data-n=\"1943\">43</sup> וזאת הראי' הוא בעצמותה בלתי תצטרך להתבוננות, אך בחי' הג' הוא בחי' הבינה שהוא בחי' גבורות<sup data-n=\"1944\">44</sup> לדחות יניקת החיצונים גם מבחי' המדות ועי\"ז יבואו מהעלם אל הגילוי כו' וד\"ל].\n<b>אך</b> שיהי' ואהבת בכל לבבך בשני יצריך<sup data-n=\"1945\">45</sup> אינו מועיל זאת ההתבוננות דשמע ישראל ובשכמל\"ו, שזהו ביטול ההשתלשלות איך דכולא קמי' כלא חשיב שזה אינו פועל רק ביטול הכח בנה\"ט שלא יוכל להסתיר ואינו פועלת פעולתה רק הוא בבחי' שינה, ולכן אח\"כ כשהולך בחשכת עוה\"ז יכול להתהפך לאיש אחר מצד נה\"ט שניעורה משינתה ולזאת צריך התבוננות דפסוד\"ז<sup data-n=\"1946\">46</sup> לברר נה\"ט עד שחמימות רשפי אש בנה\"ט יתהפכו לאהבה את הוי' [ובדורות הראשונים שהיו נשמות גבוהות לא הי' צריכים לזה מצד שתיכף שנתחזק כח הנשמה ע\"י ההתבוננות דשמע ישראל לצאת מהעלם אל הגילוי הי' כחה גדול כ\"כ להפוך נה\"ט ג\"כ כו']. והיינו ענין ההתבוננות דברוך שאמר והי' כו' ברוך הוא ברוך אומר ועושה שכולל לכל ההתבוננות",[["1934","34","<b>אור פני מלך חיים</b>: ע\"פ משלי טז, טו."],["1935","35","<b>מי לי בשמים</b>: תהלים עג, כה."],["1936","36","<b>כלה שארי ולבבי</b>: תהלים שם, כו."],["1937","37","<b>דמשכן הנשמה במוח</b>: ראה רבינו יונה לברכות יד, סע\"ב ד\"ה הרוצה. תניא פנ\"א. מאמרי אדה\"א דברים ח\"ג ע' תתסו. וש\"נ. שמות ח\"ב ע' תקמג ואילך. קונטרסים ע' שכא. וש\"נ. לקמן מאמר ד\"ה אם בחוקותי הא' על יד הערה 79."],["1938","38","<b>טמטום המוח</b>: ראה גם לקמן מאמר ד\"ה מנין וכו' זהורית על יד הערה 66. תו\"ח שמות ח\"א ב, ב. וש\"נ."],["1939","39","<b>עוונותי עברו ראשי</b>: תהלים לח, ה."],["1940","40","<b>אזלעו\"ז</b>: קהלת ז, יד. ראה סה\"מ תרל\"ח ס\"ע קלד ואילך."],["1941","41","<b>כתר. . הרצון</b>: ראה פרדס שער עצמות וכלים ש\"ד, פ\"ח. שער הצחצחות שי\"א, פ\"ה. פ\"ו. אגה\"ק סכ\"ט. מאמרי אדה\"א הנחות תקע\"ז ע' עב. וש\"נ."],["1942","42","<b>החכמה ראי'</b>: ראה פרדס שעה\"כ שכ\"ג פ\"כ מערכת ראי'. מאמרי אדה\"א הנחות תקע\"ז ע' כז. וש\"נ. תו\"ח שמות ח\"א כז, ג. וש\"נ."],["1943","43","<b>דכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה פ\"א (ז, רע\"א). מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1944","44","<b>הבינה. . גבורות</b>: ראה זהר ויקרא י, סע\"ב. יא, רע\"א. מאמרי אדה\"א דברים ח\"ב ע' שעז. וש\"נ."],["1945","45","<b>ואהבת בכל לבבך בשני יצריך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, א במשנה. ראה מאמרי אדה\"א בראשית ע' שסג ואילך. שערי אורה ו, א הערה 9."],["1946","46","<b>התבוננות דפסוד\"ז</b>: ראה גם סה\"מ תרל\"ח ע' תנא ובהערה 37."]]],[4801940329,"דפסוד\"ז כי הנה אנו רואים בשמש שזורח במזרח ושוקע במערב ויש בזה ב' דיעות<sup data-n=\"1947\">47</sup> דחכמי אוה\"ע ששוקע תחת הכדור ודעת חכמי ישראל ששוקע למעלה מן הרקיע, הענין הוא דודאי בחיצוניות ובגשמיות שוקע תחת הכדור ואז הוא מאיר ליושבים נגד רגלינו כנראה בחוש, אך חכמי ישראל דברו בפנימי' שכל הארה שהשמש מאיר אינו מצד עצמו רק מצד שאומר שירה היינו שמתבטל ונכלל במקורו כמו שהוא למעלה מן הרקיע שהוא בחי' אלקות שהוא מה שיוצא בשיר בבחי' רצוא [כי התהוותו ממקורו האלקי מאין ליש הוא ע\"י רקיע ופרסא כו'], ועי\"ז מתחדש בו חיותו בבחי' שוב שהוא מה שנמשך בשיר בבחי' שוב, וחיות הרוחני הזה הוא הפועל בו להאיר בגשמי' ובלעדי חיות הרוחני לא הי' מאיר כלל ונמצא ששקיעתו שהוא התכללותו במקורו למעלה מן הרקיע הוא סיבת הזריחה למטה מן הרקיע, והנה כל רגע ורגע שזה נעשה ע\"י הרחקת הילוך השמש יש בו שקיעה וזריחה [כי באיזה מקום עמידתו יש אופן לאנשי איזה מקום שהוא בחי' שקיעה להם כו'] בנושא א' והיינו מצד כח הכללי האלקי הכולל כל ההשתלשלות מראש לסוף כא' שהו\"ע מח' אחת שצופה ומביט<sup data-n=\"1948\">48</sup> הפועל בו שני הפכים בנושא א' היינו בעת הרצוא יהי' בחי' שוב שלא יתבטל לגמרי ובעת השוב יהי' בחי' רצוא שלא יהי' נפרד לגמרי וענין הרוחני הזה הוא פועל בגשמי' הגלגל שהוא בחי' תנועת סיבובו שהוא בחי' רו\"ש כא' אך בגשמי' מתחלק שהרצוא שהוא השקיעה למקום זה הוא בחי' זריחה למקום אחר שהוא בחי' שוב, ומשכיל על דבר להוציא מהעלם אל הגילוי חוש נפשו האלקי' יתיישב ענין זה היטב במוחו ולבו מה שלא יתיישב אפי' בפיליסופי אוה\"ע הנק' בוערים.\n<b>והנה</b> כמו\"כ יובן למעלה למשכיל בכללות ההשתלשלות עד סוכ\"ד בענין שמשא עילאה שהוא בחי' שם הוי' וכמאמר כי שמש ומגן הוי'<sup data-n=\"1949\">49</sup> כו' והוא מקור כל ההשתלשלות כידוע דהוי' לשון התהוות<sup data-n=\"1950\">50</sup> להיותו מקור ההתהוות מאין ליש וגילוי כל ההשתלשלת מאתו הוא כדוגמת גילוי האור רק שגילוי האור למעלה פועל ההתהוות [ולא כמו במשל דשמש הגשמי כו']. והנה גילוי האור שנראה ליש הוא ע\"י הרקיע שנק' פרסא שזהו המגן דשם אלקים, אך אעפ\"כ בכל עת<sup data-n=\"1951\">51</sup> ובכל רגע נכללים כל הנבראים במקורם שזהו עליות ושקיעת אור השמש במקורו הנק' מאור וחוזרים ומתחדשים מאין ליש שזהו הזריחה של האור, וא\"כ אינו מובן מאין הוא קיומם כי מצד ביטולם והתכללות שלהם יהיו חוזרים לאין ואפס ממש. אך הנה זהו מצד בחי' מח' אחת דצופה ומביט כו', והיינו שצופה כל הפרטים כל פרט ופרט בפ\"ע בסקירה אחת שזהו מורה על רוממות המח' למעלה מבחי' אין ויש של ההשתלשלות [כי",[["1947","47","<b>ב' דיעות</b>: פסחים צד, ב."],["1948","48","<b>מח' אחת שצופה ומביט</b>: ראה ברכת זכרונות. ר\"ה יח, א. סהמ\"צ להצ\"צ ע' פב. תו\"ח שמות ח\"א מח, ב. וש\"נ."],["1949","49","<b>כי שמש ומגן הוי'</b>: תהלים פד, יב. ראה שער היחוה\"א רפ\"ד. מאמרי אדה\"א דברים ח\"ב ע' ת. וש\"נ. נ\"ך ע' שצה. וש\"נ."],["1950","50","<b>דהוי' לשון התהוות</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"ט. שער עצמות וכלים ש\"ד, ספ\"י. שער היחוה\"א פ\"ד. פ\"ז. הערה בסה\"מ ת\"ש ע' 40."],["1951","51","<b>עת</b>: א: שעה."]]],[4801940377,"ביטולם במח' נק' אין ומה שנגלים ליש ע\"י הדיבור הוא בחי' היש שלהם], לכן היא כוללת לאין ויש שלהם כא' [עי' במאמר וביום הביכורים<sup data-n=\"1952\">52</sup> ובמאמר ויהי קול<sup data-n=\"1953\">53</sup> כו'], וזהו מח' עיגולים<sup data-n=\"1954\">54</sup> [ואפשר שזהו בחי' העיגולים או העקודים התכללות דתוהו כו' ועי' בע\"ח בשער הכללים בענין נקודה שהוא למעלה מן הכתר<sup data-n=\"1955\">55</sup> כו' וד\"ל], ולכן יכול להיות שני הפכים בנושא א' בעת הרצוא יהי' שוב במציאות דבר מה וזהו כי אל דעות הוי'<sup data-n=\"1956\">56</sup> שד\"ת הוא שם הוי' ואדרבה הוא עצמות המאור דהוי' ולא גילוי האור בלבד כו'.\n<b>וזהו</b> ומבלעדי אין אלקים<sup data-n=\"1957\">57</sup> ששם אלקים אינו מבלעדי שם הוי' רק הוי' בעצמו הוא שם אלקים וכמאמר כי הוי' הוא האלקים כולא חד<sup data-n=\"1958\">58</sup> ממש כו' [משא\"כ מצד התבוננות איך דכולא קמי' יתפרש ומבלעדי אין אלקים שהשם אלקים<sup data-n=\"1959\">59</sup> אינו במציאות כלל מצד שהוא בטל לשם הוי' כו'], וזהו ברוך שאמר והי' העולם לשון עבר זהו מח' דאנא אמלוך בחי' א\"ס לבוש המלוכה בעצמו כנ\"ל למעלה מהשתלשלות, וברוך הוא, הוא בחי' מח' דצופה ומביט שהוא הגילוי ממח' דאנא אמלוך להקיף כל ההשתלשלות כא' ועי\"ז ברוך אומר ועושה בפרט בכל עת ורגע בחידוש מעשה בראשית, אך אעפ\"כ גוזר ומקיים מצד כח המח' דצופה ומביט כו' וד\"ל.\n<b>וכאשר</b> יתבונן בזה איך שגוף ההסתר המקיים מציאות ההשתלשלות שיהי' נראה לדבר מה איך שזהו גופא אלקות בעצמו דווקא וזהו כללות ענין פסוד\"ז שאין מדבר בביטול ההשתלשלות [כמו ברכת יוצר] רק בהשפעת החיות בכל פרטי ההשתלשלות בפרט איך שהכל מאתו הנה זהו הפועל אח\"כ כח ועוז בנה\"א שכאשר תבוא לואהבת כו' שיהי' בכל לבבך בשני יצריך שגם הנה\"ט תתהפך לאהבה את הוי', אך עיקר ההתהפכות הוא באמת ויציב ונחמד ונעים כו' והטעם מצד שהוא מהפך בחי' עולם מקור הנה\"ט לבחי' אלקות ע\"י ההתבוננות איך שההסתר הוא עצמות הוי' כנ\"ל ממילא נתהפך גם הנה\"ט לבחי' אלקות משא\"כ ע\"י ההתבוננות דכולא קמי' כלא חשיב שנעשה בעולם רק ביטול מציאותו לגבי אלקות כנ\"ל פועל בנה\"ט ג\"כ רק ביטול פעולתו שלא יוכל להסתיר הנק' בחי' שינה כנ\"ל ולא התהפכות כו' וד\"ל].",[["1952","52","<b>במאמר וביום הביכורים</b>: יודפס בעז\"ה בפלח הרמון במדבר."],["1953","53","<b>ובמאמר ויהי קול</b>: ישנם שני דרושים שונים בפתיחה זו משבועות שנת תקצ\"ח, אחד נדפס באוה\"ת שבועות כרך ד ע' א'תכח [ובמהדורת תשנ\"ה בכרך א בהוספות ע' 51]. והשני הנחת ר' הלל — לא נדפס לע\"ע."],["1954","54","<b>מח' עיגולים</b>: ראה גם מאמרי אדה\"ז תקס\"ז ר\"ע ריב. מאמרי אדה\"א דברים ח\"ג ע' תשצז. תו\"ח ויגש רל, ד. ויחי רמד, ד."],["1955","55","<b>בע\"ח בשער הכללים. . נקודה שהוא למעלה מן הכתר</b>: רפ\"א."],["1956","56","<b>כי אל דעות הוי'</b>: שמו\"א ב, ג."],["1957","57","<b>ומבלעדי אין אלקים</b>: ישעי' מד, ו. ראה גם לקמן מאמר ד\"ה וזכרתי הר\"ת על יד הערה 70."],["1958","58","<b>כי הוי' הוא האלקים כולא חד</b>: ראה זהר בהקדמה יב, א. תרומה קסא, ב. ראה גם לקמן מאמר ד\"ה בסוכות תשבו הב' ובהערה 35."],["1959","59","<b>שהשם אלקים</b>: ניתוסף ע\"פ א."]]],[4801940421,"<b>והנה</b> ההתהפכות דנה\"ט פועל תוס' עילוי בנה\"א שבמוח<sup data-n=\"1960\">60</sup>, והטעם ע\"ד בענין כי לא על הלחם לבדו<sup data-n=\"1961\">61</sup> כו' כי על כל מוצא פי הוי' כי פי הוי' הוא בחי' תיקון אבל מוצא פי הוי' הוא בחי' התוהו מקור התיקון<sup data-n=\"1962\">62</sup> שהו\"ע המאור דהוי' שלמעלה מגילוי אור הנק' פי הוי', ומבואר למעלה שההסתר הוא מצד המאור לכן בהיפוך החושך עצמו כמו שהוא במקומו ומציאותו לאור בא המאור לידי גילוי אור ואז נתוסף אהבה בנה\"א כ\"כ נפלאה עד שלא יכילנה הכלי ונק' בכל מאדך שלמעלה מבכל נפשך כו' [והגם שמבואר למעלה דאהבת הנה\"א הוא ג\"כ כלה שארי ולבבי היינו כליון השכל והמדות להיות נכלל בתענוג הנה\"א שזהו ג\"כ בחי' כלי שהוא כלי התענוג כידוע דבתענוג יש אותיות הנק' טעמים<sup data-n=\"1963\">63</sup> כו' ונק' אותיות החקוקים שרש נש\"י<sup data-n=\"1964\">64</sup> ואורייתא סתים כו', רק הוא למעלה מכלי השכל והמדות הנק' נקודות ותגין ואותיות וזהו כעין הסתלקות ג' תלמידי רשב\"י באד\"ר<sup data-n=\"1965\">65</sup> מצד עוצם העונג כו', אבל האהבה שניתוסף מצד הנה\"ט נעשה מאד למעלה מכלי התענוג שמואס בתענוג ג\"כ רק ליכלל לגמרי וכדוגמת הבע\"ת כו', וזהו מצד ששרשה בעולם התוהו שלמעלה מגילוי אור רק אור נכלל במאור ומאור עצמו שזהו בחי' נקודים ועקודים או עיגולים כו' וד\"ל], ונמצא שמאהבה דבכל לבבך דווקא נעשה אהבה דבכל מאדך [אך מה שאמר ביניהם ובכל נפשך, הענין הוא דמתחילה מתברר הנה\"ט בבחי' ביטול היש ע\"י שם ב\"ן שבנה\"א שהו\"ע ב' מיני התבוננות איך דכולא קמי' כו', ואיך שההסתר הוא אלקות כנ\"ל וזהו בכל לבבך ואח\"כ נעשה בירור אחר בירור ע\"י שם מ\"ה שבנה\"א המברר לב\"ן<sup data-n=\"1966\">66</sup> ונעשה מבחי' ביטול היש ביטול בעצם וזהו בכל נפשך ואח\"כ המתברר עולה לשרשו למעלה משם מ\"ה המברר<sup data-n=\"1967\">67</sup> שזהו בכל מאדך כו'. וכ\"ה תנופת העומר ע\"י הכהן<sup data-n=\"1968\">68</sup> כי קרבן העומר הוא בירור דשם ב\"ן ותנופתו ע\"י הכהן בירור אחר בירור ע\"י שם מ\"ה שורש נשמת הכהן כו' ואח\"כ וספרתם לכם ממחרת השבת<sup data-n=\"1969\">69</sup> המשכת אורות דתוהו שזהו מ\"ט שערים זפ\"ז ובשלימות הספירה נתגלה שער החמישים בחי' העקודים או עיגולים ויומא הוא דקא גרים שיהי' בו התגלות אנכי מי שאנכי<sup data-n=\"1970\">70</sup> ע\"י התו'",[["1960","60","<b>שבמוח</b>: שם: ליתא."],["1961","61","<b>כי לא על הלחם לבדו</b>: עקב ח, ג. ראה גם פלח הרמון בשלח ע' קצב ואילך. יתרו ע' רלו. מאמרי אדה\"א הנחות תקע\"ז ע' קכא ואילך. וש\"נ."],["1962","62","<b>התוהו מקור התיקון</b>: ראה גם המאמר שלפנ\"ז על יד הערה 22. ד\"ה והניף הכהן תקפ\"ו על יד הערה 57. פלח הרמון בשלח ע' קצב."],["1963","63","<b>דבתענוג יש אותיות הנק' טעמים</b>: ראה לקו\"ת שה\"ש א, ג. פלח הרמון שה\"ש ס\"ע 2."],["1964","64","<b>אותיות החקוקים שרש נש\"י</b>: ראה לקו\"ת בחוקותי מה, א. לקמן מאמר ד\"ה אם בחוקותי הג'."],["1965","65","<b>הסתלקות ג' תלמידי רשב\"י באד\"ר</b>: זהר אד\"ר נשא קמד, א-ב. ראה הערה בתו\"ח שמות ח\"א לג, ב."],["1966","66","<b>שם מ\"ה. . המברר לב\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["1967","67","<b>המתברר. . למעלה משם מ\"ה המברר</b>: ראה לקו\"ת בחוקותי מז, ג. תו\"ח וארא ח\"א ע, ג. וש\"נ."],["1968","68","<b>תנופת העומר ע\"י הכהן</b>: אמור כג, יא."],["1969","69","<b>וספרתם לכם ממחרת השבת</b>: אמור שם, טו."],["1970","70","<b>אנכי מי שאנכי</b>: ראה תניא מהדו\"ק ספמ\"ט. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."]]],[4801940461,"חטה מאכל אדם<sup data-n=\"1971\">71</sup> כו' וד\"ל]. ועי' בתו\"א במאמר דמראיהם ומעשיהם<sup data-n=\"1972\">72</sup> כו', ובמאמר וספרתם בסידור<sup data-n=\"1973\">73</sup> וברשימה שלי מאדמו\"ר<sup data-n=\"1974\">74</sup> שליט\"א<sup data-n=\"1975\">75</sup> כו'].\n<b>והנה</b> כל הנ\"ל נק' עבודה שבלב זו תפילה<sup data-n=\"1976\">76</sup> פי' עבודה ל' תיקון<sup data-n=\"1977\">77</sup> שהוא תיקון שני חללי הלב כי הנה\"ט נתברר ונתקן לעלות לשרשו ועי\"ז נתקן חלל הימני מדות דנה\"א בתוס' אור שהוא בחי' העלי' והוא כדוגמת המאכל המוסיף אור וחיות בלב ע\"י הדמים שמתבררים מהמאכל ועולים אל הלב [כי הלב מצ\"ע אין בו רק רביעית דם<sup data-n=\"1978\">78</sup> כו'], והנה מצד חיזוק הלב פליג לכל שייפין<sup data-n=\"1979\">79</sup> כן ע\"י עבודה שבלב זו תפילה ממשיך אור ושפע בכל המצות שעושה כל היום שזהו גילוי א\"ס במצות שעושה שיהי' הכוונה רק לקיים רצונו כו' וזהו מצות צריכות כוונה<sup data-n=\"1980\">80</sup>, אך הכוונה נמשך בהם ע\"י התפילה [ובמ\"א מבואר שח\"י ברכאן הוא ח\"י חוליות<sup data-n=\"1981\">81</sup> וחוט השדרה שנמשך בהם, ושני הבחי' אמת כי ע\"י הכוונה בתפילה ממשיך כוונת המצות שזהו בחי' או\"פ במצות הנק' אברים וזהו כדוגמת הלב דפליג לכל שייפין, אך המשכת אור המקיף על כללות המצות שזהו\"ע הקיום והעמדה שלהם הוא ע\"י אותיות שבתפילה שבח\"י ברכאן שזהו מקיף הכללי משא\"כ מקיפים בפרט הוא מברכות המצות בעצמם כו'] שגורם קיום והעמדה וכדוגמת חוט השדרה שנמשך באחורים דווקא לקיים ולהעמיד בנין כל האיברים וכן הוא המשכת המקיף דרך אחורים וחיצוני' כענין וימינו תחבקיני<sup data-n=\"1982\">82</sup> וכידוע ממשל המכה את חבירו ודוחהו מאחוריו<sup data-n=\"1983\">*83</sup> כו' וד\"ל. והנה כמו שבלב נתוסף עוד חיזוק מצד הדם שסובב והולך מכל האיברים ועולה אל הלב כו', כך ע\"י המצות שאדם עושה כל היום נכללים למחר בטלית ותפילין שהמה כללות המצות ופועלים התאחדות המצות בנה\"א [וכדוגמת דם האיברים העולה ונכלל בלב כו'] ועי\"ז מוסיף כח ועוז בנה\"א בתפילה וכמ\"ש כי נר מצוה<sup data-n=\"1984\">83</sup> ועי\"ז נעשה ודרך חיים בתפילה כו'. והענין כי חיות המתברר בנה\"ט כשעולה לשרשו באורות דתוהו ומעורר אורות דתוהו להיות מתגלים מהעלמם לא יוכל להתקבל בנה\"א ששרשו בחכ' דתיקון שלמטה הרבה מבחי' אורות דתוהו אך ע\"י המצות נעשו כלים לאורות הנ\"ל שמתקבלים עי\"ז בנה\"א",[["1971","71","<b>חטה מאכל אדם</b>: ראה גם לקמן מאמר ד\"ה בשברי לכם הא' ובהערה 18."],["1972","72","<b>בתו\"א במאמר דמראיהם ומעשיהם</b>: יתרו סט, ב."],["1973","73","<b>ובמאמר וספרתם בסידור</b>: שער חה\"ש שז, ג ואילך. שט, א ואילך."],["1974","74","<b>וברשימה שלי מאדמו\"ר שליט\"א</b>: ראה לקמן מאמר ד\"ה וספרתם תקצ\"ח."],["1975","75","<b>שליט\"א</b>: ניתוסף ע\"פ אג."],["1976","76","<b>עבודה שבלב זו תפילה</b>: ראה רמב\"ם ריש הלכות תפלה. המאמר שנדפס לפנ\"ז הערה 7."],["1977","77","<b>עבודה ל' תיקון</b>: ראה תו\"א בראשית ה, ב. לקו\"ת בלק ע, ג. מאמרי אדה\"ז אתהלך לאזניא ס\"ע קפו ואילך. תו\"ח יתרו ח\"ב רסח, ב. וש\"נ."],["1978","78","<b>הלב. . רביעית דם</b>: ראה שבת לא, סע\"ב. מאמרי אדה\"א הנחות תקע\"ז ע' ע. וש\"נ."],["1979","79","<b>הלב פליג לכל שייפין</b>: ראה זהר שלח קסא, ב. שע\"ת סט, ב הערה 12."],["1980","80","<b>מצות צריכות כוונה</b>: ערובין צה, סע\"ב."],["1981","81","<b>שח\"י ברכאן הוא ח\"י חוליות</b>: ברכות כח, ב. ראה לקו\"ת בלק ע, ד ואילך."],["1982","82","<b>וימינו תחבקיני</b>: שה\"ש ב, ו. ח, ג."],["1983","*83","<b>ממשל המכה את חבירו ודוחהו מאחוריו</b>: השוה גם לקמן מאמר ד\"ה ענין העבודה דיוה\"כ על יד הערה 25."],["1984","83","<b>כי נר מצוה </b>[א ניתוסף: כו']: משלי ו, כג."]]],[4801940496,"בבחי' שוב שאחר הרצוא דבכל מאדך כו', וזהו והיו הדברים כו' אשר אנכי כו' על לבבך<sup data-n=\"1985\">84</sup> לפעול בו בחי' שוב וכמו בגשמי' אפשר ג\"כ לא הי' דם הניתוסף מן המאכל נמשך באיברים אם לא ע\"י דם האיברים העולה בלב הוא ממשיכו להיות פליג לכל שייפין כו' וד\"ל.\n<b>והנה</b> הכח הזה במצות לחבר אורות דתוהו בבחי' תיקון הוא מצד שרשם באנכי שלמעלה מבחי' תוהו ותיקון שהוא בחי' העצמי' שלמעלה מבחי' מאור ואור כו', עד שבגמר התפילה נתגלה הגילוי דאנכי עצמו בבחי' גילוי ממש בנה\"א דווקא, וככה הוא למעלה בקוב\"ה שהוא לבא דכל עלמין<sup data-n=\"1986\">85</sup> שכולל ב' בחי' דז\"א ומל'<sup data-n=\"1987\">86</sup> הלב דז\"א הוא פנימי' החיות דעולם הנאצל דפליג לכל שייפין כלים די\"ס דאצי' ומל' לבא דכל עלמין דבי\"ע<sup data-n=\"1988\">87</sup> דפליג לכל שייפין מלאכים הנק' איברים דשכינתא<sup data-n=\"1989\">88</sup> כלים די\"ס דבי\"ע הוא ג\"כ באופן זה היינו שיש ב' מיני בירורין הא' המתברר מנוגה דבי\"ע בכל יום מחדש וכענין יוצר משרתים<sup data-n=\"1990\">89</sup> ועולה למעלה בבחי' מל'<sup data-n=\"1991\">90</sup> וממל' לז\"א ומוסיף כח וחיזוק מצד שרשם באורות דתוהו כו' וכדוגמת דם הניתוסף מהמאכל ועוד יש בחי' בירור למעל' בבחי' מל' הנעשה מביטול דנשמות ומלאכים אשר עומדים וקיימים משי\"ב שכבר נתקנו שזהו פועל בחי' כלים לאורות דתוהו שיוכלו להתקבל בז\"א ומל' בבחי' התיישבות בכלים כו' [והטעם הוא כי המצות שרשם בכתר דתיקון שהוא הממוצע להמשיך אורות דתוהו בכלים דחכ' בתיקון ונק' רישא דעמא דאתתקן בקדמיתא<sup data-n=\"1992\">91</sup> כו' וד\"ל]. אך כאשר נגמרו האורות דתוהו להתיישב בכלי אזי ממילא נתגלה בחי' אנכי מי שאנכי בבחי' גילוי ממש בזו\"נ שזהו תכלית הכוונה להיות לו דירה בתחתונים פרצופי זו\"נ כו', וזהו שים שלום טובה וברכה כו' וד\"ל.\n<b>ונמצא</b> שכללות ענין התפילה הוא היחוד דסובב האמיתי [שהוא מהו\"ע הנק' אנכי שלמעלה מסוכ\"ע וממכ\"ע] בממכ\"ע הנק' לבא דכל עלמין, אך בתפילה העלאה דממלא בסובב ע\"י אורות דתוהו שנעשה מצד בירור דנה\"ט הוא רק בפנימי' חי שבמדבר וכן אח\"כ ההמשכה הוא בפנימי' הנפש אבל בחיצוני' אינו נראה כלום כמאמר אותותינו לא ראינו<sup data-n=\"1993\">92</sup> שזהו האותיות המחברים סובב האמיתי בממלא אינו נמשך בבחי' ראי' וגילוי בחיצוני' אבל בבהמ\"ק הי' הבירור והעלאה בחיצוני' חי בעצם שהוא נפש הבהמה ועי\"ז הי' נראה בגילוי העלאת הממלא",[["1985","84","<b>והיו הדברים. . על לבבך</b>: ואתחנן ו, ו."],["1986","85","<b>בקוב\"ה שהוא לבא דכל עלמין</b>: מובא בשם הזהר במאמרי אדה\"ז תקס\"ח ח\"א ס\"ע יד (מאמרי אדה\"א הנחות תקע\"ז ע' רסד). ראה גם הנסמן ע\"ז בתקס\"ח ח\"ב ע' תשמו."],["1987","86","<b>בקוב\"ה. . דז\"א ומל'</b>: ראה מאמרי אדה\"ז תקס\"ו ע' סז. אוה\"ת תזריע כרך א ע' רנב."],["1988","87","<b>דבי\"ע</b>: ניתוסף ע\"פ א."],["1989","88","<b>מלאכים הנק' איברים דשכינתא</b>: ראה פרדס שער היכלות שכ\"ד, פי\"א."],["1990","89","<b>וכענין יוצר משרתים</b>: ראה גם לקמן מאמר ד\"ה וספרתם תקצ\"ח ובהערה 86."],["1991","90","<b>למעלה בבחי' מל'</b>: ניתוסף ע\"פ א."],["1992","91","<b>רישא דעמא דאתתקן בקדמיתא</b>: ראה זהר אד\"ר נשא קלה, א."],["1993","92","<b>אותותינו לא ראינו</b>: תהלים עד, ט."]]],[4801940528,"בסובב שזהו אש שלמעלה שהי' יורד על המזבח<sup data-n=\"1994\">93</sup> כו' להיות אכיל קרבנין, וגם ההמשכה שמהעלאה זאת הי' נראה בגילוי שהו\"ע גילוי דאנכי בלוחות שבארון עד שנעשה נס דמקום ארון אינו מן המדה<sup data-n=\"1995\">94</sup> כו' והטעם לזה מצד בהמ\"ק שהי' בנוי ומתוקן מבחי' דומם<sup data-n=\"1996\">95</sup> [ודווקא מבחי' דומם למטה מהכל<sup data-n=\"1997\">96</sup> כידוע דעץ הבולט פסול<sup data-n=\"1998\">97</sup> ] מכון לשבתך<sup data-n=\"1999\">*98</sup> ית'. וידוע דשורש הדומם הוא בעונג הפשוט שלמעלה מעונג המורכב [כי למטה דומם למטה מן הכל<sup data-n=\"2000\">98</sup> ולמעלה בבחי' הכתר הדומם למעלה מן הכל בבחי' כשב\"כ<sup data-n=\"2001\">99</sup> ונק' דומם העדר ההתפשטות לגמרי כו'] וידוע דעונג הוא הממשיך ההעלם לבוא לידי גילוי כמו דהוה קא בדח טובא ואי הוי קבעי מיני'<sup data-n=\"2002\">100</sup> כו', ולכן בכח עונג הפשוט להמשיך ההעלם דאנכי לידי גילוי בחיצוני' דווקא משא\"כ עונג המורכב אינו ממשיך רק בפנימי' כו', וזהו מה שנק' בהמ\"ק שמחת לבו כי שמחה הוא התגלות בחיצוני' שהו\"ע הגילוי דסובב האמיתי בלב הנק' ממכ\"ע בחיצוני' [ומעין זה מאיר בסעודה שלישית דשבת ונק' חדוותא דז\"א<sup data-n=\"2003\">101</sup> כו' שהוא ג\"כ גילוי עונג הפשוט בחצוני' המדות כו' כידוע]. והנה עם זה יובן מאמר הרמ\"ז שבהמ\"ק בנוי ומשוכלל למעלה כי באמת יש בכל עולם פנימי' וחיצוני' וכאשר נגמר הבירור בדור אחד כמו דור התנאים ששרשם הי' בבריאה<sup data-n=\"2004\">102</sup> אזי בתשלום הבירור שלהם נמשך גילוי אנכי עצם הסובב בחיצוני' העולם ההוא שזהו\"ע בהמ\"ק וכ\"ה בכל דור נתגלה בהמ\"ק בעולם ההוא שהוא שורש הדור ההוא אך כשיתברר גם בעקבים בתכלית השלימות אזי יתגלה בהמ\"ק למטה בחיצוני' וזהו בונה ירושלים ל' הוה כו' וד\"ל.\n<b>והנה</b> ענין הנגע הוא היפך עונג<sup data-n=\"2005\">103</sup> הפשוט הנ\"ל ולכן נק' סגירו דנהורא עילאה<sup data-n=\"2006\">104</sup> הסתלקות הסובב וזהו כנגע נראה לי בבית<sup data-n=\"2007\">105</sup> שהו\"ע חורבן בהמ\"ק",[["1994","93","<b>אש שלמעלה שהי' יורד על המזבח</b>: תו\"כ ויקרא א, ז. יומא כא, ב."],["1995","94","<b>דמקום ארון אינו מן המדה</b>: יומא כא, א."],["1996","95","<b>בהמ\"ק. . מבחי' דומם</b>: ראה תו\"א ר\"פ ויגש. תו\"ח שם ובהערה 1. סידור שער התפלה כא, ב. כג, ג. סה\"מ תרכ\"ט ע' כב ואילך ובהנסמן שם. מאמר ד\"ה ודוד עבדי ש\"פ ויגש תשל\"ב ס\"ב [קונט' ה' טבת תשנ\"ב — סה\"מ מלוקט ו ע' עז ואילך]. לקו\"ש שמות כרך ו' ע' 20 ובהערות שם."],["1997","96","<b>למטה מהכל</b>: ניתוסף ע\"פ א."],["1998","97","<b>דעץ הבולט פסול</b>: ראה רמב\"ם הל' בית הבחירה פ\"א, ה\"ט. וראה גם לקו\"ש מסעי כרך כח ע' 219 ואילך ובהנסמן שם. סוכות כרך כט ע' 497."],["1999","*98","<b>מכון לשבתך </b>[א: לשבתו]: בשלח טו, יז."],["2000","98","<b>למטה דומם למטה מן הכל</b>: ראה לקו\"ת מטות פא, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תתפד. וש\"נ. במדבר ח\"ב ע' תעט. ח\"ה ע' א'תשד. דברים ח\"ב ע' תרסה. וש\"נ. לעיל ע' מו. לקמן מאמר ד\"ה והניף הכהן תקפ\"ו על יד הערה 53. ד\"ה אם בחוקותי הג' על יד הערה 165."],["2001","99","<b>הדומם. . כשב\"כ</b>: ראה גם מאמרי אדה\"א במדבר ח\"ב ודברים שם. לעיל ע' מז. לקמן מאמר ד\"ה והניף הכהן שם."],["2002","100","<b>דהוה קבדח. . קבעי מיני'</b>: ראה שבת עז, ב. לעיל ע' עו."],["2003","101","<b>חדוותא דז\"א</b>: ראה זהר יתרו פח, ב. סידור סדר סעודת שבת ר, א."],["2004","102","<b>התנאים. . בבריאה</b>: ראה גם לעיל ע' יט והערה 27."],["2005","103","<b>הנגע. . עונג</b>: ראה ס\"י פ\"ב, מ\"ד ובמפרשים שם. שע\"ת נג, ד הערה 40."],["2006","104","<b>הנגע. . סגירו דנהורא עילאה</b>: ראה זהר תזריע מט, ב. ביאוה\"ז שם עב, א. עג, ב. תו\"ח שמות ח\"א מב, ג הערה 253."],["2007","105","<b>כנגע נראה לי בבית</b>: מצורע יד, לה."]]],[4801940555,"הסתלקות העונג שגורם הסתלקות דאנכי ח\"ו, ולכן יש נגעי אדם ונגעי בגדים ונגעי בתים כי את זה לעומת זה<sup data-n=\"2008\">106</sup> כו' כי בקדושה נמשך העונג הפנימי בבחי' פנימי' ומקיף ומקיף למקיף, שזהו תומ\"צ ותפילה [עי' בסידור במאמר דמזמור שיר חנוכת<sup data-n=\"2009\">107</sup> ] ולהיפך בבחי' הקליפה הסתלקות העונג מכל בחי' הנ\"ל שגורם בנין הקליפה ח\"ו בפנימי' כו', אך בזמן בהמ\"ק כשהי' הסתלקות הנ\"ל באיזה פרט מ\"מ כיון שבהמ\"ק הי' בנוי הי' תיקון לזה ע\"י הכהן הרואה את הנגעים שהי' פועל בו הרגשת הריחוק כענין ראה נתתי לפניך<sup data-n=\"2010\">108</sup> כו' שזהו ימינך פשוטה לקבל שבים<sup data-n=\"2011\">109</sup>, רב חסד כהנא רבא<sup data-n=\"2012\">110</sup> והוא המתלבש במיכאל כהנא רבא<sup data-n=\"2013\">111</sup> שנק' בגדי כהונה שעי\"ז ימין הנ\"ל מתפשטת בנשמה הנבראת מאין ליש להתעורר בתשובה ואח\"כ ושב ורפה לו<sup data-n=\"2014\">112</sup> תיקון הכלים הנפגמים והמשכות האור בהם הי' ע\"י העלאת הנרות כו' וד\"ל.\n<b>אך</b> עכשיו כיון שנחרב בהמ\"ק ונעשה הסתלקות עונג הפשוט בכללות אין כח להכהן להתלבש בנבראים מאין ליש לתקן הנגעים [והטעם לזה כי עונג הפשוט הוא הנעוץ בסופן מל' המחבר אצי' בבריאה הנק' מקדש ה' וכשנחרב בהמ\"ק נסתלק הממוצע המחבר אצי' בבריאה שהו\"ע כחב\"ד דבריאה עם אור המל' דאצי' המלובש בהם ונעשה הסתלקות עונג הפשוט], וזהו והצרוע זה בהמ\"ק שכאשר נגע נראה בבית עצמו שהוא הסתלקות עונג הפשוט כנ\"ל אזי ממילא אין לבוש להתלבש בנבראים שזהו בגדיו יהיו פרומים אלו בגדי כהונה כו' ונמצא שנחלש ג\"כ כח המעורר לתשובה כו', וראשו יהי' פרוע<sup data-n=\"2015\">113</sup> רישא שכיבת לעפרא<sup data-n=\"2016\">114</sup> הוא ענין ירידת ט\"ס דמל' בקליפות עד שלא נשאר רק הנקודה שהוא למטה בעבודה רק נקודת יהדותו כו', עי' בע\"ח שער ל\"ה פ\"ב<sup data-n=\"2017\">115</sup> כו', ולכן נחלש כח התשובה שהוא מבחי' בינה<sup data-n=\"2018\">116</sup> דמל' כו', ועל שפם יעטה<sup data-n=\"2019\">117</sup> שניטל כח הדיבור כי כח הדיבור הוא מבחי' י\"ה דאלקים שזהו בנין המל' מצד שאו\"א תקינו לה<sup data-n=\"2020\">118</sup>, אבל כאשר נהרס בנין המל' שהוא ג\"כ מצד הסתלקות דאו\"א נתמעט בנין המל' עד שאינה רק בבחי' נקודה ונחסר ג\"כ ממילא לבוש האמצעי שהוא הדיבור וכ\"ז הוא מצד הסתלקות עונג הפשוט נגע",[["2008","106","<b>כי את זה לעומת זה</b>: קהלת ז, יד. ראה סה\"מ תרל\"ח ס\"ע קלד ואילך."],["2009","107","<b>בסידור במאמר דמזמור שיר חנוכת</b>: שער התפלה כ, ג ואילך."],["2010","108","<b>ראה נתתי לפניך</b>: נצבים ל, טו."],["2011","109","<b>ימינך פשוטה לקבל שבים</b>: ע\"פ תפלת נעילה."],["2012","110","<b>רב חסד כהנא רבא</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תצ. וש\"נ. ש\"א מב, א הערה 25."],["2013","111","<b>במיכאל כהנא רבא</b>: ראה זהר ס\"ת לך פ, סע\"א ואילך. הנסמן במאמרי אדה\"א בראשית ע' נו."],["2014","112","<b>ושב ורפה לו</b>: ישעי' ו, י."],["2015","113","<b>וראשו יהי' פרוע</b>: המשך הכתוב והצרוע (תזריע יג, מה)."],["2016","114","<b>רישא שכיבת לעפרא</b>: ראה זהר במדבר קיט, ב. ע\"ח שנסמן בפנים. הנסמן במאמרי אדה\"א דברים ח\"א ע' יד."],["2017","115","<b>בע\"ח של\"ה, פ\"ב</b>: ובדפו\"א של\"ו, פ\"ב (שער מיעוט הירח)."],["2018","116","<b>התשובה. . בינה</b>: ראה זהר ס\"ת לך פ, סע\"ב. רע\"מ נשא קכב, א וסע\"ב. לקמן מאמר ד\"ה לה\"ע ההפרש בין שבת ליו\"ט תר\"ב הערה 73."],["2019","117","<b>ועל שפם יעטה</b>: המשך הכתוב והצרוע (תזריע יג, מה)."],["2020","118","<b>שאו\"א תקינו לה</b>: ראה זהר בראשית מח, ב. מט, א."]]],[4801940573,"נראה לי בבית שגרם זה, והעצה והתיקון לזה גם עכשיו וטמא טמא יקרא מחויב להודיע צערו לרבים<sup data-n=\"2021\">119</sup> ורבים מבקשים עליו רחמים וזהו רחל מבכה<sup data-n=\"2022\">120</sup> לאחרים דווקא כו'.\n<b>וביאור</b> הדברים הנה יש ג' מדריגות הנק' תשובה, הא' בינה ונק' תשובה שזהו\"ע ההתבוננות איך שההסתר גופא הוא בחי' אלקות שזהו הפועל בירור דנה\"ט כנ\"ל, והב' כאשר פגם באיזה איסורין דאורייתא או דרבנן כו' שזהו גורם עוונותי עברו ראשי כנ\"ל אזי אין עצה לזה רק בבחי' תשובה תתאה שהוא ג\"כ התבוננות בעצם הריחוק דנפשו ומצד המנגד מתעורר עצם הנשמה שאין שום פגם בה וכמאמר כולך יפה רעיתי<sup data-n=\"2023\">121</sup> כו' ושורש התשובה זאת הוא בחי' בינה שבכתר שהוא המרירות על הריחוק שזהו בחי' עצמות יותר, וזאת ההתעוררות הוא מצד עצם הניצוץ האלקי המרגיש הריחוק שהוא העדר האור ועי\"ז מתגברת האהבה עצמי' לבוא מהעלם אל הגילוי [והנה ענין הרגשת העדר האור בעצם הניצוץ אע\"פ שאין בו פגם היינו ענין העדר התוס' אור שניתוסף בו מצד שלא יוכל להשפיע למקבלים ממנו שהם כוחות הנפש וע\"ד הצדיק אבד<sup data-n=\"2024\">122</sup> המבואר בע\"ח שער הכללי' פ\"א], והג' כאשר אין כח בניצוץ האלקי להתעורר מצד הריחוק והענין הוא ע\"ד משארז\"ל ההפרש בין חורבן בית ראשון לחורבן בית שני דוויתר הקב\"ה על ג' עבירות כו' ולא וויתר על עון ביטול תורה<sup data-n=\"2025\">123</sup> וכן בענין שנאת חינם נחרב בית שני<sup data-n=\"2026\">124</sup>, והענין הוא דשני דברים אלו הם פוגמים יותר מכל העבירות כי כל העבירות כולם לא יגיעו לעצם הניצוץ כנ\"ל בענין כולך יפה רעיתי כו', אבל שתי עוונות אלו פועלים חלישות כל הכוחות שבניצוץ האלקי עצמו עד שאין בו כח להתעורר ולהמשיך אלקות בכוחות הנפש [שזהו מצד ט\"ס שבניצוץ עצמו וזהו\"ע רישא שכיבת לעפרא כנ\"ל וירידת ט\"ס לקליפות כו' רח\"ל] ולא נשאר רק הכתר שבניצוץ עצמו נקודת יהדותו בלבד ואינו מרגיש מרירות בהעדר גילוי האור כנ\"ל, והעצה לזה הוא הצעקה על כי איננו<sup data-n=\"2027\">125</sup>, העדר העצמיות שלמעלה מגילוי אור וק\"ו<sup data-n=\"2028\">126</sup> מעוברי בעומק הבכא<sup data-n=\"2029\">127</sup> כו', וצעקה זאת פועלת בכל כחות הנפש בחיצוני' שזהו\"ע הודעת צערו לרבים ועי\"ז מתעוררים רחמים גדולים מבחי' העצמיות להיות קיבוץ כל הכוחות וכמאמר וברחמים גדולים אקבצך<sup data-n=\"2030\">128</sup> וכאשר נתייחדו בו כל הכוחות בבחי' שלום נתבטל ג\"כ בכללות העולמות בחי' שנאת חינם, וזהו וטמא טמא יקרא שתי חורבנות שזהו הפגם דב\"ש דווקא כו' כנ\"ל, אזי יקרא להודיע צערו לרבים שזהו דווקא כאשר",[["2021","119","<b>וטמא. . מחויב להודיע צערו לרבים</b>: תזריע שם. ראה שבת סז, א."],["2022","120","<b>רחל מבכה</b>: ירמי' לא, יד."],["2023","121","<b>כולך יפה רעיתי</b>: שה\"ש ד, ז. ראה גם תו\"ח בא ח\"א קו, ב ובהערה 210."],["2024","122","<b>הצדיק אבד</b>: ישעי' נז, א."],["2025","123","<b>דוויתר הקב\"ה. . ולא וויתר. . ביטול תורה</b>: ראה ירושלמי חגיגה פ\"א, ה\"ז. פתיחתא דאיכ\"ר ב."],["2026","124","<b>שנאת חינם נחרב בית שני</b>: יומט ט, ב. ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' רכד. וש\"נ."],["2027","125","<b>כי איננו</b>: המשך הכתוב רחל מבכה (ירמי' לא, יד)."],["2028","126","<b>וק\"ו</b>: א: ונק'."],["2029","127","<b>מעוברי בעומק הבכא</b>: תהלים פד, ז."],["2030","128","<b>וברחמים גדולים אקבצך</b>: ישעי' נד, ז."]]],[4801940587,"הצעקה היא מצד כי איננו העדר העצמי' אז יוכל להיות מבכה לאחרים ואז כתיב מי יתן טהור מטמא<sup data-n=\"2031\">129</sup> שמטמא זה נפילה הנ\"ל דרישא שכיבת לעפרא יהי' בחי' טהור שהו\"ע תחה\"מ והי' הוי' אחד ושמו אחד<sup data-n=\"2032\">130</sup> גם בארץ הגשמי' בכללות העולם יהיה בגילוי כמו למעלה מן הטבע ויהי' נראה בגילוי למטה בחיצוני' בכל העולם [ולא כמו בבהמ\"ק שהי' נראה רק בהיכל ק\"ק] וזהו מצד לא אחד<sup data-n=\"2033\">131</sup> שהוא הצעקה על העדר העצמיות כי איננו שגורם זה הגילוי דלעתיד כו' וד\"ל.",[["2031","129","<b>מי יתן טהור מטמא</b>: איוב יד, ד."],["2032","130","<b>הוי' אחד ושמו אחד</b>: זכרי' יד, ט."],["2033","131","<b>לא אחד</b>: המשך הכתוב מי יתן טהור."]]],[4801940104,"<b>רשימה מה ששמעתי מאדמו\"ר שליט\"א בליבאויטש פסח שני תקצ\"ח</b>\n<b>כי</b> ביום הזה<sup data-n=\"2034\">2</sup> יכפר<sup data-n=\"2035\">1</sup> כו'. וי\"ל למה אמר יכפר סתם והל\"ל יכפר הוי' או אכפר כו'. וגם י\"ל מש\"א בזוהר פ' אחרי היום הזה מבע\"ל<sup data-n=\"2036\">3</sup>. ולכאורה אינו מובן קושייתו וכי היום הוא המכפר הלא הקב\"ה הוא המכפר ביום הזה וא\"כ יותר טוב לכתוב ביום הזה. אך ביאור הדברים יובן בהקדם ענין התשובה שפירושו ענין השבת הנפש למקורה ושרשה, כי ידוע שהנשמה שרשה בפנימיות העולמות כמ\"ש ויפח באפיו נשמת חיים<sup data-n=\"2037\">4</sup> מאן דנפח מתוכי' נפח<sup data-n=\"2038\">5</sup>, אך ירדה בסתר המדריגה ע\"י מאמר נעשה אדם<sup data-n=\"2039\">6</sup> ונתלבשה בחיצוניות העולמות הנמשכים מדבר ה' ורוח פיו עד שנתלבשה בחומר הגוף הגשמי ולזה הוא ענין התשובה להשיבה למקורה ושרשה שתהא<sup data-n=\"2040\">7</sup> צרורה את ה' ממש כמו בתחלה קודם בואה לגוף כו'. אך י\"ל למה עשה ה' כזאת להורידה בירידה עצומה כ\"כ והלואי שתוכל להשיב השבה מעליותא כי כל הדרכים בחזקת סכנה<sup data-n=\"2041\">8</sup>, ואפי' אם תשוב השבה מעלייתא אין שום יתרון בזה כיון שהשבתה הוא למקורה ושרשה בלבד כו' ועכ\"ל<sup data-n=\"2042\">9</sup> דירידה זאת צורך עלי'<sup data-n=\"2043\">10</sup> כו'.",[["2034","2","<b>כי ביום הזה יכפר</b>: אחרי טז, ל."],["2035","1","<b>כי ביום הזה יכפר</b>: הנחת ר' הלל מהדרוש שנדפס אח\"כ בלקו\"ת ר\"פ אחרי כב, ג. וראה הנסמן במ\"מ לשם.\nמאמר זה נזכר בלקוטי ביאורים לדרך חיים ווארשא תרכ\"ח נ, סע\"א ואילך."],["2036","3","<b>בזוהר פ' אחרי היום הזה מבע\"ל</b>: ג נרשם עה\"ג: ח\"ג דס\"ח ב'. ח\"ב קפ\"ה ב'."],["2037","4","<b>ויפח באפיו נשמת חיים</b>: בראשית ב, ז."],["2038","5","<b>מאן דנפח מתוכי' נפח</b>: בלקו\"ת כאן בשם הזהר. ראה תניא רפ\"ב. שה\"א צח, א הערה 5."],["2039","6","<b>מאמר נעשה אדם</b>: בראשית א, כו."],["2040","7","<b>שתהא</b>: ג: עד שתהי'."],["2041","8","<b>כל הדרכים בחזקת סכנה</b>: ירושלמי ברכות פ\"ד, ה\"ד. קה\"ר ג, ב (ב)."],["2042","9","<b>כו' ועכ\"ל</b>: ג: כנ\"ל וע\"כ לומר."],["2043","10","<b>דירידה זאת צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."]]],[4801940168,"וענין העלי' יובן ע\"פ מ\"ש כל הנק' בשמי<sup data-n=\"2044\">11</sup> דקאי על נש\"י שנקראים בשמו של הקב\"ה להיותם חלק אלוה ממעל ממש<sup data-n=\"2045\">12</sup> לכבודי בראתיו כו' פי' מה שנבראו שם<sup data-n=\"2046\">13</sup> הנשמות מאין ליש וירדו למטה עד עשי' גשמי' כמ\"ש אף עשיתיו הוא הכל לכבודו כענין ר\"י קארי למאני' מכבדותא<sup data-n=\"2047\">14</sup> שהוא לעשות לבושי' לבחי' דבר הוי' המחי' ומהוה כל העולמות, להיות ידוע דדבר ה' הוא בחי' גבורה ורשפי אש וכמ\"ש הלא דברי כאש<sup data-n=\"2048\">15</sup>, ומבשרי אחזה<sup data-n=\"2049\">16</sup> שהדיבור יוצא ע\"י ה' מוצאות הפה ומקורו הוא הבל הלב אשר שם משכן יסוד האש<sup data-n=\"2050\">17</sup> [... רק קצת מתערב בהבל הזה בעברו דרך הריאה והקנה ממים והלחלוחיות שבריאה. ..], וראי' לדבר שהדיבור פועל באדם התלהבות ורשפי אש הן כשמדבר בענין אהבה ותשוקה לדבר מה הן כשמדבר בעניני קפידא וכעס, וכעד\"ז בתפילה ותורה הקול יעורר בו אהבה והתפעלות רשפי אש בחיות רב יותר. והנה אנו רואים בטבע האש אשר טבעו להסתלק במקורו<sup data-n=\"2051\">18</sup> אם לא שנאחז בפתילה ועצים שאז יתקיים זמן מה לפ\"ע הפתילה והעצים, כך למעלה בחי' דבר ה' ורוח פיו המחי' את כל העולמות הוא כטבע האש להסתלק במקורו וא\"כ היו העולמות מסתלקים במקורם והיו לאין ואפס, ולזה צריך ענין הלבושים דתומ\"צ ותפלה לפעול בבחי' דבר ה' ב' דברים, הא' התגלות הדיבור מהעלמו שזהו ענין התפשטותו להוות עולמות עד לאין קץ ושיעור וקיומו בבחי' נצחי' ושלא יחזור למקורו כטבע האש בכדי שלא יחזרו העולמות להיות אין ואפס כבתחלה, והב' השפלת הדיבור להוות עולמות נבראים מאין ליש מוגבלים ומחודשים כמ\"ש עכשיו כי מצד עצם התגלותו הוא בערך א\"ס והי' מתהווה ממנו עולמות ג\"כ בבחי' א\"ס ומה שמתהווה ממנו עולמות בערך שהם עכשיו מחודשים ומוגבלים הוא השפלה וירידה גדולה לבחי' דבר ה' לאשתעי מילין דהדיוטא דלאו אורחא דמלכא<sup data-n=\"2052\">19</sup> כו'. וכמו ההפרש באדם התחתון בין כשמדבר דברי תורה ותפלה ובין כשמדבר עניני ביתו שזהו בחי' השפלת הדיבור ומכ\"ש כשמשיח שיחה בטילה שזהו ירידה גדולה לבחי' דבורו להתלבש בשיחה בטילה או<sup data-n=\"2053\">20</sup> כמו המלך שיש לו אוצרות כסף וזהב ומשפיל א\"ע לדבר בעניני קיבוץ שברי חרסי אדמה כו' כן יותר מכן<sup data-n=\"2054\">21</sup> לאין קץ כבי' למעלה ההפרש בין התגלות דבר ה' להיות מתפלל או יושב ועוסק בתורה כבי' לבחי' דבר ה' להוות עולמות ומכ\"ש עולמות בגדר שהן עכשיו מחודשים מאין ליש ומוגבלים שזהו כמשל שיחה בטילה דלאו אורחא כו', כי המשל אינו דומה לנמשל",[["2044","11","<b>כל הנק' בשמי</b>: ישעי' מג, ז [ושם: ולכבודי]."],["2045","12","<b>חלק אלוה ממעל ממש</b>: ראה איוב לא, ב. תניא רפ\"ב. תו\"ח וארא ח\"א נא, ד. וש\"נ."],["2046","13","<b>שם</b>: אג: ליתא."],["2047","14","<b>ר\"י קארי למאני' מכבדותא</b>: ראה שבת קיג, א."],["2048","15","<b>הלא </b>[א ניתוסף: כה]<b> דברי כאש</b>: ירמי' כג, כט."],["2049","16","<b>ומבשרי אחזה</b>: איוב יט, כו."],["2050","17","<b>הלב אשר שם משכן יסוד האש</b>: ראה תניא פ\"ג. מאמרי אדה\"א בראשית ע' שצ. וש\"נ. וראה לקו\"ת כאן (כה, ג)."],["2051","18","<b>בטבע האש. . להסתלק במקורו</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ד, ה\"ב. תניא פי\"ט. תו\"ח בשלח ח\"א רלט, רע\"ג. וש\"נ. סה\"מ תרל\"ח ע' תצא ובהערה 15."],["2052","19","<b>לאשתעי מילין דהדיוטא דלאו אורחא דמלכא</b>: ראה זהר בהעלותך קמט, ב. סידור שער התפלה יח, סע\"ד. לקו\"ת כאן (כה, ד)."],["2053","20","<b>או</b>: ניתוסף ע\"פ אג."],["2054","21","<b>כו' כן. . מכן</b>: א: כך יותר מכן. ג: כך יובן מכאן."]]],[4801940227,"כלל כי באמת כסף וזהב המה ג\"כ עפר ודומם כמו חרסי אדמה רק שנזדככו עד שנעשו דבר יקר וכן במשל האדם כשמדבר דברי חכמה או עניני שיחה שיש להם ערך זע\"ז אבל למעלה כבי' אין ערוך מבלתי בע\"ג לבע\"ג, אך לזה הוא ענין הלבושי' דתומ\"צ לפעול ב' בחי' הנ\"ל הא' התגלות הדיבור ממקורו וקיומו בבחי' נצחי' והב' השפלתו בג' עולמות דבי\"ע כו'.\n<b>והנה</b> כללות הלבושי' הגורמים קיום העולמות המה שלשה לבושי' כמאמר על שלשה דברים העולם עומד<sup data-n=\"2055\">22</sup> תורה ועבודה וגמ\"ח, וג' לבושי' אלו גורמים השפלת דבר ה' בג' עולמות בי\"ע הנק' בראתיו יצרתיו אף עשיתיו<sup data-n=\"2056\">23</sup>, כי הנה ג' עולמות הנ\"ל עולם הבריאה הוא עולם המחשבה כמשל המחשבה באדם שמתאחדת עמו ואינה נבדלת ממנו בבחי' פירוד וגילוי לזולתו אבל הדיבור מתגלה בבחי' פירוד קצת ממנו אבל מ\"מ הוא סמוך לו אבל אותיות המעשה כמו אותיות הכתב המה נפרדים לגמרי ממנו ויוכלו להתקיים אפי' כשמסלק ידיו מהם, משא\"כ הדיבור כשפוסק מלדבר נפסק ומתבטל, כך הוא<sup data-n=\"2057\">24</sup> למעלה עולם הבריאה שהוא בחי' נשמות ומלאכים דבריאה המה בתכלית הביטול והיחוד בבחי' אלקות ואינם נפרדים כלל ממנו כדוגמת המחשבה באדם, ועולם היצירה שהוא בחי' נשמות ומלאכים דיצירה המה נפרדים קצת בבחי' יש אבל מ\"מ המה קרובים לבחי' אלקות המחי' אותם וזהו ענין יוצר אור ובורא חושך<sup data-n=\"2058\">25</sup> שהבריאה היא בבחי' ההעלם אבל היצירה הוא גילוי ההעלם אבל נשמות ומלאכים דעשי' מרחוק ה' נראה עליהם<sup data-n=\"2059\">26</sup> אע\"פ שהמה ג\"כ בטלים בביטול גמור לבחי' אלקות כי אפי' גלגל היותר חיצוני נאמר עליהם וצבא השמים לך משתחוים<sup data-n=\"2060\">27</sup> מ\"מ ביטול זה הוא מצד האור האלקי החופף עליהם בבחי' מקיף ויאיר בהם בבחי' הודאה מרחוק בלבד. ונמצא שיש בבחי' דבר ה' וכח האלקי המחי' ומהווה אותם ג' צמצומים כללים וג' מיני ירידות והשפלות שונות הנק' בד\"כ ג' עולמות בי\"ע.\n<b>וזהו</b> הטעם דעל שלשה דברים העולם עומד, שהמה ג' לבושים דתורה ועבודה וגמ\"ח שזהו גורם ג' בחי' ירידות אור האלקי להחיות ג' עולמות בי\"ע, כי העבודה הם הקרבנות שזהו לבוש המחשבה כי עיקר עבודת הקרבנות תלוי במחשבה<sup data-n=\"2061\">28</sup> שהוא בחי' הכהן המקריב שהי' מקריב אותו ברעותא דלבא ובביטול רצון כי עבודת הכהנים בחשאי<sup data-n=\"2062\">29</sup> [... משא\"כ הלוים עבודתם לארמא קלא<sup data-n=\"2063\">30</sup> כו'. ..], ואע\"פ",[["2055","22","<b>על שלשה דברים העולם עומד</b>: ראה אבות פ\"א, מ\"ב."],["2056","23","<b>בי\"ע הנק' בראתיו. . עשיתיו</b>: ישעי' מג, ז. ראה גם לקמן ד\"ה את שבתותי תרי\"ב ובהערה 25."],["2057","24","<b>הוא</b>: אג: ליתא."],["2058","25","<b>יוצר אור ובורא חושך</b>: ישעי מה, ז. ראה פע\"ח שער הק\"ש ש\"ח, פ\"א. הנסמן בתו\"ח בשלח ח\"א קמד, ג הערה 41. סה\"מ תרכ\"ז ע' רפו. וש\"נ."],["2059","26","<b>מרחוק ה' נראה עליהם </b>[אג: להם]: ע\"פ ירמי' לא, ב."],["2060","27","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו."],["2061","28","<b>עיקר עבודת הקרבנות תלוי במחשבה</b>: ראה זבחים מו, ב. רמב\"ם הל' מעשה הקרבנות פ\"ד, ה\"י. הי\"א."],["2062","29","<b>ברעותא דלבא. . הכהנים בחשאי</b>: ראה זהר בשלח נז, א. שמיני לט, א. אמור פח, ב. קרח קעז, ב. סה\"מ תרכ\"ט ע' רז. וש\"נ."],["2063","30","<b>הלוים עבודתם לארמא קלא</b>: ראה זהר שמיני וקרח וסה\"מ תרכ\"ט שבהערה שלפנ\"ז."]]],[4801940280,"שההקרבה הוא במעשה בפועל ממש מ\"מ עיקר ההקרבה תלוי במחשבה ולכן נפסל במחשבה לאכול חוץ לזמנו<sup data-n=\"2064\">31</sup> כו'. והנה עכשיו תפלה במקום קרבן<sup data-n=\"2065\">32</sup> עיקרה ג\"כ במחשבה שהוא בחי' מס\"נ באחד<sup data-n=\"2066\">33</sup> ואהוי\"ר שזהו מצות התלוי' במחשבה, ולכן אפי' לדעת הפוסקים בשאר מצות דלא בעי כוונה<sup data-n=\"2067\">34</sup> מ\"מ בק\"ש בפסוק ראשון הכל מודים דבעי כוונה<sup data-n=\"2068\">35</sup> בלב דוקא, ואע\"פ שמוכרח להיות ג\"כ קריאה בפה<sup data-n=\"2069\">36</sup> מ\"מ העיקר הוא כוונת הלב, ונמצא שהעבודה וכן<sup data-n=\"2070\">37</sup> התפלה<sup data-n=\"2071\">38</sup> במקום קרבן היא כנגד לבוש המחשבה וע\"י לבוש המחשבה הוא ממשיך תוס' גילוי אור מדבר ה' המחי' ומהוה בעולם הבריאה ולהיות קיום בבחי' נצחי' כענין לעולם ה' דברך נצב בשמים<sup data-n=\"2072\">39</sup> כו' כנ\"ל, ולבוש השני הוא בחי' התורה שהוא כנגד לבוש הדיבור ועיקר מצות לימוד התורה הוא בדיבור<sup data-n=\"2073\">40</sup> כמאמר ודברת בם<sup data-n=\"2074\">41</sup> וכן וידבר אלקים את כל הדברים האלה לאמור<sup data-n=\"2075\">42</sup> ועי\"ז ממשיך אור דבר ה' להחיות עולם היצירה כו', ולבוש הג' הוא לבוש המעשה שזהו ענין הצדקה וגמ\"ח וכללות המצות שבמעשה בפו\"מ נק' בשם צדקה וגמ\"ח ועי\"ז ממשיך אור דבר ה' בעולם העשי' כו'.\n<b>והנה</b> לא ראי זה כראי זה שיש יתרון ומעלה בת\"ת ובמצות מעשיות<sup data-n=\"2076\">43</sup> מבתפלה במה שהאור מאיר ע\"י בריבוי ובהתפשטות יותר עד שמאיר למקום רחוק יותר כמו בעלמא דאתגלי' שהוא בחי' יצי' ועשי' כמו המשל דאבוקה שמאיר יותר מאור הנר מצד ריבוי העצים שנאחז בהם האור יותר אבל מ\"מ יש יתרון ומעלה באור הנר אשר האור שלו צלול ביותר, וכן אנו מוצאים ב' אופנים אלו בכה\"ח<sup data-n=\"2077\">44</sup> הא' אשר בריבוי הכלים הוא ריבוי האור יותר והב' הוא אשר ריבוי האור במיעוט הכלי דוקא כמו אור השכל שנתפס בכלי המוח דייקא שהוא כלי קטנה והרגל שהוא כלי<sup data-n=\"2078\">45</sup> יותר גדולה והחיות שבו במיעוט יותר. והענין הוא ששניהם אמת כי ריבוי והתפשטות האור הוא תלוי בריבוי הכלים דייקא כמו משל האבוקה הנ\"ל שכל מה שמתרבה בעצם<sup data-n=\"2079\">46</sup> האבוקה יותר גדולה ומאירה למרחוק יותר אבל זיכוך וצלילת",[["2064","31","<b>נפסל במחשבה לאכול חוץ לזמנו</b>: ראה זבחים כז, ב. רמב\"ם הל' פסולי המוקדשין רפי\"ג."],["2065","32","<b>תפלה במקום קרבן</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["2066","33","<b>מס\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["2067","34","<b>בשאר מצות דלא בעי כוונה</b>: ראה שו\"ע אדה\"ז הל' ק\"ש ס\"ס, ס\"ה."],["2068","35","<b>בק\"ש בפסוק ראשון. . כוונה</b>: ברכות יג, ב. שו\"ע שם."],["2069","36","<b>בק\"ש. . שמוכרח. . קריאה בפה</b>: שו\"ע אדה\"ז שם סס\"ב, ס\"ג."],["2070","37","<b>שמוכרח. . קריאה בפה. . וכן התפלה</b>: ראה שו\"ע אדה\"ז הל' תפלה סק\"א, ס\"ד."],["2071","38","<b>העיקר הוא כוונת הלב. . התפלה</b>: ראה לקו\"ש אמור כרך כב ע' 117."],["2072","39","<b>לעולם ה' דברך נצב בשמים</b>: תהלים קיט, פט."],["2073","40","<b>מצות לימוד התורה הוא בדיבור</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב. מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. תו\"ח וארא ח\"א פ, ג. וש\"נ."],["2074","41","<b>ודברת בם</b>: ואתחנן ו, ז."],["2075","42","<b>וידבר אלקים. . לאמור</b>: יתרו כ, א."],["2076","43","<b>ובמצות מעשיות</b>: ניתוסף ע\"פ א."],["2077","44","<b>בכה\"ח</b>: אג: בכתבי החסידות."],["2078","45","<b>כלי</b>: ניתוסף ע\"פ אג."],["2079","46","<b>שמתרבה בעצם</b>: שם: שמרבה בעצים."]]],[4801940330,"האור ורוחניותו בעומק יותר בעא\"ע הוא במיעוט הכלים דייקא, וכן הוא בתפלה ותומ\"צ שע\"י התומ\"צ נעשה ריבוי האור בהתפשטות למרחוק יותר משא\"כ עומק צלילותו של האור בבחי' הרגשת הביטול בתכלית תלוי בענין העבודה שבתפלה, ולכן בודקין החמץ לאור הנר<sup data-n=\"2080\">47</sup> דוקא כי פירוד והבדלת תערובת יש הוא נפרד ונבדל ע\"י הרגשת אלקות במחשבה דייקא הנק' אור הנר, וכל מה שמייגע בנפשו בעבודת התפלה להרגיש חיות אלקות בנפשו יותר נפרד ונבדל כל מיני תערובות יש אפי' תכלית הדקות שבו<sup data-n=\"2081\">48</sup> כו' וד\"ל.\n<b>והנה</b> להבין מאין יש כח בג' לבושי' אלו שהמה מחודו\"מ שבנפש האדם שכ\"ז הוא בבחי' אותיות הנבראים מאין ליש ואיך בכחם לחבר דבר ה' שיהי' נשפל בג' עולמות הנבראים להחיותם הלא דבר ה' הוא בחי' כח אלקי בלתי מוגבל כלל, אך הענין הוא שכמו שיש ג' לבושי' מחדו\"מ בג' עולמות דבי\"ע כך יש ג' לבושי' אלו למעלה בבחי' האצי' שזהו בחי' בי\"ע דאצי'<sup data-n=\"2082\">49</sup> והוא בחי' ג' כלים פנימי ואמצעי וחיצון<sup data-n=\"2083\">50</sup> ובד\"כ הוא בחי' בינה ז\"א ומל', והנה בחי' כלים הפנימי' נעשים נשמה לעשר ספירות דבריאה והוא בחי' לבוש המחשבה דאצילות וכלים האמצעי' הוא בחי' נשמה לעולם היצירה לי\"ס שבו והוא בחי' לבוש הדיבור דאצי' וכלים החיצוני' הוא בחי' נשמה לי\"ס דעשי' והוא בחי' לבוש המעשה דאצילות. והנה ג' לבושים אלו הוא מעצמות האצילות דשם איהו וחיוהי וגרמוהי חד<sup data-n=\"2084\">51</sup> והמה למעלה מבחי' דבר ה' שהוא מקור עולמות הנבראים כמ\"ש כלול בבחי' אצילות [... הנק' כבוד נברא<sup data-n=\"2085\">52</sup> כתר מל' דבוק בחזה דז\"א<sup data-n=\"2086\">53</sup> כמשל התכללות הדיבור בהבל הלב משא\"כ ג' לבושים אלו המה בבחי' בינה ומדות ומל' דז\"א עצמו הנק' כבוד נאצל<sup data-n=\"2087\">54</sup> כו'. ..].\n<b>והנה</b> ידוע דעיקר עבודת האדם בתפלה ותומ\"צ הוא רק בבחי' ביטול רצון כמו בתפלה העיקר הוא הכוונה ורצון אליו ולא למדותיו<sup data-n=\"2088\">55</sup> שזהו ענין למס\"נ באחד בבחי' מי לי בשמים<sup data-n=\"2089\">56</sup> ועמך לא חפצתי כו' וכן בתורה העיקר הוא בחי' הביטול לדבר ה' המלובש באורייתא דמחכ\"ע נפקת<sup data-n=\"2090\">57</sup> והוא וחכמתו א'<sup data-n=\"2091\">58</sup> וזהו עיקר",[["2080","47","<b>בודקין </b>[שם ניתוסף: את]<b> החמץ לאור הנר</b>: פסחים ב, א."],["2081","48","<b>שבו</b>: ניתוסף ע\"פ אג."],["2082","49","<b>בי\"ע דאצי'</b>: ראה ע\"ח שער כללות אבי\"ע שמ\"ב, פ\"ד. וראה גם לקמן ביאור מאמר ד\"ה שבת שבתון ובהערה 38."],["2083","50","<b>ג' כלים פנימי ואמצעי וחיצון</b>: ראה ע\"ח שער המוחין ש\"כ, פ\"ה."],["2084","51","<b>איהו וחיוהי וגרמוהי חד</b>: ת\"ז בהקדמה ג, ב."],["2085","52","<b>כבוד נברא</b>: ראה לקו\"ת שה\"ש מז, ב ואילך. מאמרי אדה\"א דרושי חתונה ח\"א ע' א. וש\"נ. תו\"ח וישב ר, ג ובהערה 47. לקמן מאמר ד\"ה בסוכות תשבו תרכ\"ב הערה 83."],["2086","53","<b>כתר מל' דבוק בחזה דז\"א</b>: ראה ע\"ח שער מוחין דצלם שכ\"ג, ספ\"ה. שער הירח של\"ה, פ\"א. פע\"ח שער התפלה ש\"א, פ\"ז."],["2087","54","<b>כבוד נאצל</b>: ראה הערה דלעיל כבוד נברא."],["2088","55","<b>אליו ולא למדותיו</b>: ואתחנן ד, ז. במאמרי אדה\"ז תקס\"ג ח\"א ע' קכו: שארז\"ל בספרי. ראה פרדס שער הכוונה של\"ב, פ\"ב. מאמרי אדה\"א ויקרא ח\"א ע' נ. וש\"נ. נ\"ך ע' לד. וש\"נ."],["2089","56","<b>מי לי בשמים</b>: תהלים עג, כה."],["2090","57","<b>באורייתא דמחכ\"ע נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["2091","58","<b>והוא וחכמתו א'</b>: תניא פ\"ב."]]],[4801940378,"עסק התורה להמשיך בה אוא\"ס ב\"ה שזהו ענין לשמה לשם התורה עצמה<sup data-n=\"2092\">59</sup> לקשרה באוא\"ס. וכן במעשה המצות לא נתנו אלא לצרף בהם את הבריות<sup data-n=\"2093\">60</sup> שהוא ביטול הרצון לקיים רצון ה' המלובש בהם. והנה ביטול הרצון הוא למעלה אפי' מאותיות המחשבה כי הרצון אין בו אותיות עדיין רק הוא מקור האותיות כי מה שרוצה הוא מחשב ולכן ע\"י ביטול הרצון מגיע לבחי' אוא\"ס שלמעלה אפי' מבחי' כלים דאצי' כי אפי' ח\"ע דאצי' מקור התורה הוא ג\"כ בחי' כלי ומאין תמצא ליש אבל אוא\"ס הוא למעלה מבחי' ח\"ע ולכן לית מחשבה תפיסא בי' כלל<sup data-n=\"2094\">61</sup> רק ביטול הרצון מעורר אוא\"ס להמשיכו מחדש בכלים דאצילות, ועי\"ז פועל ג\"כ התקשרות והתחברות דג' כלים אלו שבאצי' פנימי ואמצעי וחיצון להתחבר במחשבה דיבור ומעשה דבי\"ע עד שמתלבשים בנפש האדם ממש במחדו\"מ שלו כמו כל הקורא ושונה<sup data-n=\"2095\">62</sup> הקב\"ה שונה כו' שמתלבש דבר ה' שהוא בחי' הדיבור דאצי' בדיבור שבשרש נפש האדם בעולם היצי' עד שיורד ומתלבש בדיבור שבנה\"א<sup data-n=\"2096\">63</sup> בגופו כמו אני המשנה המדברת בפיך<sup data-n=\"2097\">64</sup> כו' שדבר ה' מדבר בפיו ממש וכעד\"ז במצות מעשיות מתלבשים מצות עליונות במצות שעושה אותם האדם רק שהוא בהעלם כו'.\n<b>והנה</b> עתה יובן ענין הנ\"ל איך שביכולת ג' לבושים אלו בתפלה ותומ\"צ שבנפש האדם לחבר ולהמשיך דבר ה' בג' עולמות דבי\"ע ולהתקיים בקיום נצחי שזהו מצד שרשם בלבושים עליונים דאצילות המלובשים בהם שהמה למעלה מבחי' דבר ה' המקור לבי'ע שהוא בחי' הארה בעלמא מעצם אור האצי' משא\"כ שרש הלבושים אלו הוא בעצמו' האצי' וזהו כמשל אור הנר הנאחז בפתילה שהוא ע\"י השמן כי השמן הוא מקור האור [... והראי' כי צלילות האור הוא לפי\"ע צלילת השמן כו'. ..] ולכן ביכולתו לפעול אחיזת האור בפתילה וקיומו עד כלות השמן כך למעלה יובן למשכיל בג' לבושים אלו שהמה בבחי' אצילות שהמה מקור דבר ה' המחי' ומהוה כו' ולכן ביכולתם לפעול אחיזת אור האלקי בעולמות וקיומו כענין לעולם ה' דברך נצב בשמים כו'.\n<b>ובזה</b> יובן ענין ח\"י ברכאן דצלותא<sup data-n=\"2098\">65</sup> וח\"י ברכות השחר<sup data-n=\"2099\">66</sup> כי הברכה הוא המשכת אוא\"ס שבכלים ולבושים דאבי\"ע ולכן אומרים ברוך אתה כי אתה לנוכח",[["2092","59","<b>לשמה לשם התורה עצמה</b>: ראה פע\"ח שער הנהגת הלימוד. מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. שה\"א סט, ב ובהערה 26. סה\"מ תרכ\"ז ס\"ע רסח ואילך. וש\"נ. לקמן מאמר ד\"ה שבת שבתון על יד הערה 95."],["2093","60","<b>לצרף בהם את הבריות</b>: ראה תנחומא שמיני ז-ח. ב\"ר רפמ\"ד. אוה\"ת שמיני ע' נב ואילך. המשך מים רבים תרל\"ו פק\"י ע' קטו. סה\"מ תרל\"ח ס\"ע יח ואילך. לקו\"ש אבות כרך יז ע' 415 הערה 53. שופטים כרך יט ע' 182 הערה 42."],["2094","61","<b>לית מחשבה תפיסא בי' כלל</b>: ראה ת\"ז בהקדמה יז, א."],["2095","62","<b>כל הקורא ושונה</b>: ראה תדא\"ר רפי\"ח. מאמרי אדה\"א דברים ח\"ב ע' שפז. וש\"נ. תו\"ח וארא ח\"א נח, ג. וש\"נ."],["2096","63","<b>שבנה\"א</b>: ניתוסף ע\"פ אג."],["2097","64","<b>אני המשנה המדברת בפיך</b>: ראה מגיד משרים פ' ויחי. בא. תשא. שע\"ת פ, ג ובהערה 26. תו\"ח תצוה ח\"ב שסב, ד. וש\"נ."],["2098","65","<b>ח\"י ברכאן דצלותא</b>: זהר בראשית כו, א."],["2099","66","<b>וח\"י ברכות השחר</b>: ראה תו\"ח וארא נ, א הערה 25."]]],[4801940422,"הוא ביטול הרצון אליו ולא למדותיו ועי\"ז ממשיך גילוי אלקות בבחי' הוי' אלקינו שהוא בחי' כלים דאצי' שרשי עצם הנשמות ואז נעשה התחברות ג\"כ כלים דאצי' בלבושי' דבי\"ע וממילא נעשה מלך העולם שהוא בחי' אחיזת האור האלקי דדבר ה' בעולמות להחיותם כו', ולכן יש ח\"י ברכות להיות שבחי' ג' כלים כל א' כלול מג' כמו כלי הפנימי שהוא בחי' שכל כלול מג' בחי' חב\"ד וכלי אמצעי חג\"ת וכלי החיצון נה\"י ויש ט' בחי' מלמעלה למטה שהוא בחי'<sup data-n=\"2100\">67</sup> כלים דאצילות וט' בחי' מלמטה למעלה שזהו בחי' ח\"י ברכאן, רק ח\"י ברכאן דצלותא הוא בבחי' פנימי' האצי' שזהו המשכה פנימי' לנשמות וח\"י ברכאן דברכות השחר הוא בעולם היצי' שהוא בחי' המשכה חיצוני' למלאכים כמבואר במ\"א בענין רוכב על כרוב קל<sup data-n=\"2101\">68</sup> כו'. אך כללות ח\"י ברכאן הוא בחי' המשכת אוא\"ס עצמו שלמעלה אפי' מכלים דאצי' בכל בחי' הכלים דאצי' ודבי\"ע ולכן המה במספר ח\"י דוקא כו' וד\"ל. ולכן מברכים אותם בכל יום כי המחדש בטובו בכ\"י<sup data-n=\"2102\">69</sup> וצריך להמשיך המשכה חדשה בכל יום בבחי' כלים דבי\"ע<sup data-n=\"2103\">70</sup> כו' וד\"ל [... ובזה אפשר להבין קצת ענין ירידת הנשמה בגוף לצורך עלי' כי ידוע דחלק הנשמה היורדת בגוף שרשה בהבל לב אדה\"ע כמו כל העולמות רק ששרשה בפנימי' ההבל וכמ\"ש ויפח באפיו מאן דנפח מתוכי' נפח והוא ע\"ד ירידת פנימי' המל' בבי\"ע שהוא בחי' נשמה הכללית בכדי לברר כל העולמות ולהפכם מחושך לאור כ\"ה בנשמה בפרט שיורדת ומתלבשת בגוף בכדי להפכו מחושך לאור ועז\"נ טהורה היא אתה בראתה<sup data-n=\"2104\">71</sup> כו' ואתה נפחת כו' אבל שרש עצם הנשמה בכלים דאצי' עצמם אינו יורדת ומתלבשת בגוף שזהו בחי' ישראל עלה במחשבה<sup data-n=\"2105\">72</sup> עצם המחשבה [... ולא בחי' דיבור שבמחשבה הנק' הרהור בלבד שזהו בחי' שרש הנשמה בבחי' פנימי' המל' שהוא המתלבש בגוף כו'. ..], וזהו ג\"כ מה דמתקשראן באורייתא<sup data-n=\"2106\">73</sup> כי אורייתא וישראל הוא בחי' אורות וכלים דאצי' ומתקשראן זב\"ז וכמבואר בענין עולת תמיד כו', ונמצא שיש עלי' לנשמה ששרשה בבחי' פנימי' ההבל ע\"י התלבשותה בגוף ומהפכת בחי' נה\"ט בבחי' ביטול רצון וע\"י ביטול רצון הזה עוסקת בתפלה ותומ\"צ ממשכת ע\"ע לבושי' עליוני' אשר שרשם בכלים דאצי' עצמם ונמשכו בנשמה בבחי' מקיפים ופנימי' משא\"כ כמ\"ש בשרשה לא תוכל לקבל מבחי' הכלים דאצי' כ\"א הארה בעלמא כו' וד\"ל. ..], אך עיקר העלי' הוא ע\"י התשובה כמשי\"ת<sup data-n=\"2107\">74</sup>.\n<b>והנה</b> את זה לעומת זה עשה האלקים<sup data-n=\"2108\">75</sup> כי כמו שיש בחי' דבר ה' שהוא בחי' מל' דקדושה המחי' ומהוה כל העולמות ושרשה מבחי' אש בבחי' טבע",[["2100","67","<b>בחי'</b>: ניתוסף ע\"פ אג."],["2101","68","<b>רוכב על כרוב קל</b>: ע\"ז ג, ב. ראה תו\"א יתרו עג, ג."],["2102","69","<b>המחדש בטובו בכ\"י</b>: ברכת יוצר."],["2103","70","<b>דבי\"ע</b>: אג: דאבי\"ע."],["2104","71","<b>טהורה היא אתה בראתה</b>: ברכת אלקי נשמה."],["2105","72","<b>ישראל עלה במחשבה</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248."],["2106","73","<b>ישראל. . דמתקשראן באורייתא</b>: ראה זהר אחרי עג, א."],["2107","74","<b>וד\"ל</b>:.). . כמשי\"ת: א: וד\"ל:.). והשאר ליתא. ג: וד\"ל). . כמשי\"ת)."],["2108","75","<b>את זה לעומת זה עשה האלקים</b>: קהלת ז, יד. ראה סה\"מ תרל\"ח ס\"ע קלד ואילך."]]],[4801940462,"הסתלקות וע\"י הלבושים דתורה ומצות ותפלה עושים בנין המל' שתהי' בפרצוף שלם להשפיע בבי\"ע ולא תסתלק ח\"ו למעלה, ועז\"נ כבוד חכמים ינחלו<sup data-n=\"2109\">76</sup> שבחי' מל' הנק' חכמה תתאה נוחלת בחי' לבושי' הנק' כבוד להיות שרשם בל\"ב נתיבות החכ\"ע<sup data-n=\"2110\">77</sup> בתורה הנק' כבוד, כן יש זלעו\"ז בחי' מל' דקליפה הנק' אש זרה ונבנית ג\"כ ע\"י הלבושים דמח' ודיבור ומעשה שעז\"נ וכסיל מרים קלון<sup data-n=\"2111\">78</sup> שנעשה הרמה לבחי' קלון שהוא בחי' המל' דקליפה כי אין לה קיום ג\"כ רק ע\"י הלבושים והיינו ע\"י המחשבות והדיבורים וכל המעשים אשר לא לה' המה וכאשר האדם נמשך ח\"ו בג' לבושי' הנ\"ל אזי נזרק ונתרחק בריחוק אחר ריחוק מבחי' הקדושה וכמ\"ש ואת נפש אויביך יקלענה בתוך כף הקלע<sup data-n=\"2112\">79</sup> כי כף הקלע הוא בחי' המחשבה אשר לא לה' המה המלבישים את הנפש מראשה ועד רגלה ועי\"ז נזרק למרחוק יותר בבחי' פירוד מאלקות ח\"ו. והנה גם בג' לבושים אלו<sup data-n=\"2113\">80</sup> שבזלע\"ז לא ראי זה כראי זה<sup data-n=\"2114\">81</sup> כי ידוע דהרהורי עבירה קשים מעבירה<sup data-n=\"2115\">82</sup> ואעפ\"כ אין עונשין אלא על המעשה, הענין הוא כי כמו שבסט' דקדושה עיקר הביטול לבחי' אלקות הוא במח' דייקא כך להיפוך ח\"ו עיקר הריחוק הוא בבחי' המחשבה, אך אעפ\"כ העונש שהוא מניעת ההתפשטות שפע אור האלקי בנפשו אינו אלא דייקא ע\"י המעשה [... ויובן ע\"ד מ\"ש בביאורי זוהר במאמר כשושנה בענין כי על אפי<sup data-n=\"2116\">83</sup> כו' שיכול להיות סילוק פנימי' הרצון ואעפ\"כ בחיצוני' יכול להיות כל היחודים עליונים כו' יעו\"ש, כן גם בכאן עיקר הריחוק שהוא מצד סילוק רצונו ית' ממנו הוא ע\"י הרהורי עבירה אך אעפ\"כ יכול להיות המשכת אלקות בנפשו בחיצוני' והעונש של מניעת השפע אינו רק מצד המעשה כו' וד\"ל. ..]. והנה כאשר כבר נמשך בג' לבושים דאת זה לעומת זה ח\"ו אין תקנה כ\"א ע\"י התשובה שזהו בחי' חילא יתיר<sup data-n=\"2117\">84</sup> וכמו ראב\"ד שיצתה נשמתו בבכי'<sup data-n=\"2118\">85</sup> ואמר רבי עליו יש קונה עולמו כו'.\n<b>וביאור</b> ענין דמשכין לי' בחילא יתיר הנה ידוע דאית רצון ואית רצון<sup data-n=\"2119\">86</sup>, שיש רצון הנולד ע\"פ טעם ושכל וכן יש רצון שלמעלה מן הטעם אבל מ\"מ הוא מקור לטעם ושכל וכמ\"ש רואים בענין הרצון שהוא למעלה מן המח' ושכל אך אעפ\"כ נולדו ממנו מחשבה ושכל לחשוב ולהשכיל מה שהוא רוצה [... והנה גם",[["2109","76","<b>כבוד חכמים ינחלו</b>: משלי ג, לה."],["2110","77","<b>בל\"ב נתיבות החכ\"ע</b>: ראה ס\"י פ\"א, מ\"א. הנסמן במאמרי אדה\"א בראשית ע' ג."],["2111","78","<b>וכסיל </b>[אג: וכסילים]<b> מרים קלון</b>: סיום הכתוב כבוד חכמים (משלי ג, לה)."],["2112","79","<b>ואת נפש אויביך. . הקלע</b>: שמו\"א כה, כט."],["2113","80","<b>גם. . אלו</b>: ניתוסף ע\"פ אג."],["2114","81","<b>לא ראי זה כראי זה</b>: ברכות לה, א."],["2115","82","<b>דהרהורי עבירה קשים מעבירה</b>: ראה יומא כט, א. לקמן מאמר ד\"ה אם בחוקותי הג' על יד הערה 49. מאמרי אדה\"א דברים ח\"א ע' קיד. וש\"נ. שע\"ת ד, ד ובהערה 29. המשך זאת חנוכת המזבח תר\"ם פט\"ז."],["2116","83","<b>בביאורי זוהר. . כי על אפי</b>: בראשית א, א."],["2117","84","<b>התשובה. . חילא יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. תו\"ח שמות ח\"א לז, א. וש\"נ."],["2118","85","<b>ראב\"ד שיצתה נשמתו בבכי'</b>: ע\"ז יז, א. ראה סה\"מ תרמ\"ו ע' יט."],["2119","86","<b>דאית רצון ואית רצון</b>: מובא בכ\"מ בשם הזהר [ראה הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תרמז־ תו\"ח בשלח ח\"א קצט, א הערה 774] ראה זהר אד\"ר נשא קכט, א: מצחא דאיקרי רצון כו'."]]],[4801940497,"הרצון שלמעלה מטעם ושכל רק שהוא מקור לטעם ושכל נק' ג\"כ רצון הנולד ע\"פ הטעם והיינו שהולידתו הוא מצד הטעם כמוס ולכן נעשה מקור לשכל וטעם הנולד<sup data-n=\"2120\">87</sup> במחשבה כו' וד\"ל. ..], אבל אית רצון שהוא למעלה מן הטעם לגמרי ואינו נעשה מקור לשכל וטעם כלל [... והיינו מצד שהוא למעלה מטעם הכמוס כו'. ..]. והנה ע\"י התשובה מעומקא דליבא וע\"י מרירות על ריחוקו מה' עי\"ז נתגלה עצם הרצון הפשוט שבנפש שלמעלה מן הטעם לגמרי עד שמואס בחייו ומוסר נפשו לגמרי וכמו ראב\"ד אשר יצתה נשמתו כו', והנה זהו בחי' חילא יתיר שהוא בחי' נקודת הרצה\"פ שבנפש שנתגלה בבע\"ת האמיתים כמו ראב\"ד ולכן אמר רבי עליו יש קונה עולמו בשעה א' כו' כי צדיקים גמורים<sup data-n=\"2121\">88</sup> ממשיכים אלקות בנפשם ע\"י תפלה ותומ\"צ התלויים בזמן ומקום ואם חסר מצוה א' האור נעדר וכן כשעבר על ל\"ת נעשה פגם בנפשו וא\"א לתקן זה ע\"י תומ\"צ שיעשה מחדש כי מה מועיל זה למה שכבר עבר משא\"כ כח התשובה המגיע בעצם נקודת הרצון הוא משלים כל החסרונות והפגמים [... ושרש הדברים הנה ידוע דגם החכמה מאין תמצא<sup data-n=\"2122\">89</sup> והוא ג\"כ בחי' כלי ולכן בחי' ג' כלים הוא בחי' חב\"ד חג\"ת נה\"י נמצא שהתחלת הכלים הוא מחכמה (... והגם שפנימיות החכמה הוא בחי' אור שזהו בחי' תורה ששרשה בבחי' אורות כנ\"ל מ\"מ הוא בחי' אורות המלובשים בכלים כו'. ..) אבל הרצון הוא בחי' האור שלמעלה מבחי' הכלים אבל הוא מקור האורות המלובשים בכלים ולכן ע\"י תומ\"צ התלויים בזמן ומקום<sup data-n=\"2123\">90</sup> ממשיכים מבחי' מקור האורות להתלבש בכלים אבל כשחסר איזה מצוה לא יוכל להשלים מבחי' הרצון מקור האורות שהוא ג\"כ בבחי' זמן רק שהזמן שם בהעלם אבל מבחי' הרצון העצמי שלמעלה מבחי' מקור האורות שהוא למעלה מן הזמן לגמרי יוכל להשלים כל פגם וחסרון הבא בזמן ומקום כו' וד\"ל. ..].\n<b>והנה</b> ראב\"ד בכחו הי' להגיע לנקודת הרצון בתשובה שלימה מעצמו עד שיצתה נשמתו, אבל אנחנו שאין בכח שלנו לעשות תשובה מעצמינו לזה ניתן לנו יוהכ\"פ שהוא יום התשובה להיות שבו מאיר מקור הרחמים מלמעלה מצ\"ע בלתי אתעדל\"ת כלל ועי\"ז מעורר כללות נש\"י שיחזרו בתשובה שלימה שהוא ענין בקשת הרחמים, וזהו מה שאנו או' השיבנו ה' אליך<sup data-n=\"2124\">91</sup> ונשובה והיינו ע\"י חדש ימינו כקדם פי' הדברים שיש בחי' ימות עולם כמאמר המתנשא מימות עולם<sup data-n=\"2125\">92</sup> והוא בחי' אתעדל\"ע המתעורר ונמשך ע\"י אתעדל\"ת [... מבחי' עולם שנה נפש ולכן נק' ימות עולם שבאים ונמשכים ע\"י התעוררות דעולם כו'. ..] ויש בחי' ימי קדם שזהו בחי' אתעדל\"ע המתעורר מעצמו ואין מעה\"ת<sup data-n=\"2126\">93</sup> מגיע לשם כלל לכן נק' קדם שזהו קודם ההשתלשלות, וכן הי' בתחלת ההשתלשלות הי' בחי' ההתעוררות מעצמו בלי",[["2120","87","<b>הנולד</b>: אג: הנגלה."],["2121","88","<b>גמורים</b>: שם: ליתא."],["2122","89","<b>החכמה מאין תמצא</b>: איוב כח, יב."],["2123","90","<b>ומקום</b>: שם: ליתא."],["2124","91","<b>השיבנו ה' אליך</b>: איכה ה, כא."],["2125","92","<b>המתנשא מימות עולם</b>: ע\"פ ברכת יוצר."],["2126","93","<b>מעה\"ת</b>: מעשי התחתונים."]]],[4801940529,"אתעדל\"ת כלל רק מצד<sup data-n=\"2127\">95</sup> כי חפץ חסד הוא<sup data-n=\"2128\">94</sup> ע\"כ עלה ברצונו להיטיב כו'. והנה יוהכ\"פ הוא יום המאיר בו מימי קדם ולכן אז זמן התעוררות רח\"ר הבאים מלמעלה על כללות נש\"י לעוררם בתשובה שלימה, שזהו ההתעוררות רח\"ר שמעוררים ע\"ע מצד עומקא דליבא המתגלה בהם מצד הרגשת הריחוק דייקא הנק' חילא יתיר, וזהו שאנו מבקשים חדש ימינו כקדם, להיות שמעצמינו אין בנו כח כמו ראב\"ד לעורר גילוי נקודת הלב שהוא הרצון שלמעלה מן הטעם לגמרי כו' לכן אנו<sup data-n=\"2129\">96</sup> מבקשים שיאיר מבחי' קדם שהוא כח המתעורר מעצמו בלי אתעדל\"ת ועי\"ז יומשך בנו כח ועוז לעורר נקודת הלב כנ\"ל וזהו השיבנו כו' כנ\"ל, אך עיקר סליחת ומחילת כל העונות זהו בא אח\"כ כשמתעוררים בתשובה מלמטה למעלה, והיינו כשמעורר רח\"ר על נפשו מצד שמתבונן עוצם הירידה דעולמות עד שכל העולמות אינם רק מחשבה א' מן העצמי' כמאמר צופה ומביט עד סוף כו' בסקירה א'<sup data-n=\"2130\">97</sup> נמצא זהו ירידה עצומה לגבי העצמות, ואח\"כ מתבונן בעוצם ירידת נפשו שירדה ממדריגה למדריגה עד שנתלבשה בתחתית המדריגות דכל העולמות שהוא חומר מאסר הגוף המסתיר על אור האלקי ומצד זה מבקש מעומקא דליבא אלקי עולם ברחמיך הרבים<sup data-n=\"2131\">98</sup> רחם עלינו כו' [... ובחי' תשובה זאת שמצד הריחוק שייך גם במי שלא עבר עבירה, שמרגיש הריחוק מצד עצם חומר הגוף המסתיר ומכש\"כ במי שעבר עבירה כו', וזהו העלי' שמצד הירידה שמתעלית לבחי' עצם הרצה\"פ שלמעלה משרש הנשמה כמשי\"ת. ..]. ועי\"ז מעורר למעלה מקור הרחמים עליונים שנק' אב הרחמים, וממילא נמשכים י\"ג מדה\"ר להיות נושא עון ועובר על פשע<sup data-n=\"2132\">99</sup> כו'.\n<b>והנה</b> להבין שרש ענין אב הרחמים מהו הנה יש להקדים הנאמר במשה בעת שקרא והמשיך י\"ג מדה\"ר כמאמר ויקרא ה' ה' אל רחום<sup data-n=\"2133\">100</sup> כו' נאמר לו אז מקודם מפי הקב\"ה הנה מקום אתי ונצבת<sup data-n=\"2134\">101</sup> כו' והי' בעבור כבודי ושמתיך בנקרת הצור<sup data-n=\"2135\">102</sup>. ביאור הדברים הנה כתי' אין קדוש כהוי'<sup data-n=\"2136\">103</sup> ואין צור כאלקינו, כי הנה בחי' המשכות אורות בכלים דאצי' נק' הוי', וכן המשכות אורות בכלים דבי\"ע נק' אלקיך, והוא כמו האש הנאחז בפתילה ועצים שמאיר בגילוי אור לכן נאמר כי הוי' אלקיך אש אוכלה הוא<sup data-n=\"2137\">104</sup>. והנה המשכת אורות בכלים באצי' הוא בחי' ירידת והמשכת אוא\"ס להתלבש בכלים דאבי\"ע ונק' בחי' זאת קדוש בוי\"ו שהוא ירידת קדושת העצמו' שעז\"נ אין קדוש כהוי', וזהו מה שאומרים ג\"פ קדוש עד שנעשה מכה\"כ<sup data-n=\"2138\">105</sup> שהוא בחי' כבוד דתורה אור שנמשך למטה מטה בג' מיני כלים דאצילות ובג' לבושים דמחשבה דבור ומעשה דבי\"ע עד שאפי' ארץ הגשמי האירה מכבודו<sup data-n=\"2139\">106</sup>",[["2127","95","<b>רק מצד</b>: ניתוסף ע\"פ ג."],["2128","94","<b>בתחלת ההשתלשלות. . כי חפץ חסד הוא</b>: מיכה ז, יח. ראה ע\"ח שער דרושי הנקודות ש\"ח, ספ\"ו."],["2129","96","<b>מן הטעם. . אנו</b>: אג: לגמרי מן הטעם כנ\"ל ולכן."],["2130","97","<b>צופה ומביט. . בסקירה א'</b>: ראה ברכת זכרונות. ר\"ה יח, א. סהמ\"צ להצ\"צ ע' פב. תו\"ח שמות ח\"א מח, ב. וש\"נ."],["2131","98","<b>אלקי עולם ברחמיך הרבים</b>: ברכת יוצר."],["2132","99","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח."],["2133","100","<b>ויקרא ה' ה' אל רחום</b>: תשא לד, ו."],["2134","101","<b>הנה מקום אתי ונצבת</b>: תשא לג, כא."],["2135","102","<b>והי' בעבור כבודי. . הצור</b>: תשא שם, כב."],["2136","103","<b>אין קדוש כהוי'</b>: שמו\"א כ, ב [בדילוג]."],["2137","104","<b>כי הוי' אלקיך אש אוכלה הוא</b>: ואתחנן ד, כד."],["2138","105","<b>ג\"פ קדוש. . מכה\"כ</b>: ישעי' ו, ג."],["2139","106","<b>ארץ. . האירה מכבודו</b>: יחזקאל מג, ב."]]],[4801940556,"כבוד דתורה [... ויש בחי' שם הוי' הנעלם המקור לגילוי שם הוי' הזה שהוא ע\"ד דוגמא התכללות האש במקורו כשלהבת הקשורה בגחלת<sup data-n=\"2140\">107</sup> שזהו בחי' אורות שלמעלה מבחי' כלים אבל הוא בחי' מקור ושרש להתלבש בכלים, והוא ע\"ד הקבלה בבחי' חיצוניות הכתר שהוא שרש וראש לנאצלים<sup data-n=\"2141\">108</sup> וכנ\"ל בענין הרצון שלמעלה מן הטעם אבל הוא מקור לבחי' טעם דחכמה כו' וגם זה נק' קדוש בוא\"ו כו' וד\"ל. ..], אבל מש\"א אין צור כאלקינו [דאלקים הוא שרש היותר ראשון דנש\"י כמו שהן בפנימי' ועצמות רצון הנעלם שלמעלה מן הטעם לגמרי שעז\"נ כי רוצה הוי' בעמו<sup data-n=\"2142\">109</sup> והוא בחי' מחשבתן של ישראל קדמה לכל<sup data-n=\"2143\">110</sup> כו'] בחי' צור הוא מקור מוצא האש, שכאשר צריכין להוציא אש מחדש לגמרי שלא הי' מעולם בגדר אש מוציאין אותו ע\"י הכאה בצור [... משא\"כ שלהבת הקשורה בגחלת הוא בגדר אש רק שהוא אש נעלם. ..], ולכן כאשר נכבה האור לגמרי מדליקין אותו מחדש ע\"י הכאה באבן החלמיש כו', ולמעלה זהו בחי' אור הנעלם בעצמי' שאינו עדיין בגדר מקור ושרש להתגלות אורות בכלים, ומשם יוכל להיות מילוי כל החסרונות וטהרת כל הפגמים עד שיוכל להיות שזדונות נעשו כזכיות<sup data-n=\"2144\">111</sup>, וזהו בחי' מקור י\"ג מדה\"ר ששרשם ומקורם במקור מוצא האש.\n<b>ועם</b> זה יתפרש הנה מקום אתי שזהו התכללות אורות בכלים כמ\"ש כלולים בעצמותו ממש שאינו בגדר מקור ושרש להתהוות אורות בכלים בגילוי כו', והי' בעבור כבודי מצד מניעת מעשה התחתונים ושמתיך בנקרת הצור להמשיך משם י\"ג מדה\"ר להיות נושא עון ועובר על פשע כו'. וזהו ענין ברוך כבוד הוי' ממקומו<sup data-n=\"2145\">112</sup>, שכאשר אין כבוד הוי' שהוא כבוד דתורה מאיר בגילוי מצד חסרון ומניעת הכשר מעשה התחתונים, אזי ממשיכים כבוד הוי' ממקומו העצמי שהוא בחי' הנה מקום אתי כו'. ולכן אופנים אומרים ברוך<sup data-n=\"2146\">113</sup>, להיות שהתפעלותם ברעש מצד המנגד שהוא החומר שלהם המסתיר על אור ה' וכאשר יוצאי' מן הכלי המנגדת ומסתרת אזי יוכלו להגיע לעורר המשכת כבוד הוי' ממקומו העצמי שהוא בחי' צור וזהו ע\"ד התשובה בנפש האדם כו' וד\"ל.\n<b>וזהו</b> כי ביום הזה וא' בזוהר היום הזה מבע\"ל, כי לכאורה יוהכ\"פ ששרשו בבינה<sup data-n=\"2147\">114</sup> שלמעלה ממקור התומ\"צ [... כי מקור התומ\"צ הוא בחי' ז\"א ומל'<sup data-n=\"2148\">115</sup> דאצי' אבל בחי' בינה למעלה מהם כו'. ..] והוא המשלים כל החסרונות, אבל באמת אינו כן רק הוא המעורר מקור הרחמים להיות נמשך לנש\"י לעוררם בתשובה מצד",[["2140","107","<b>כשלהבת הקשורה בגחלת</b>: ס\"י פ\"א, מ\"ז."],["2141","108","<b>חיצוניות הכתר. . לנאצלים</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א."],["2142","109","<b>כי רוצה הוי' בעמו</b>: תהלים קמט, ד."],["2143","110","<b>מחשבתן של ישראל קדמה לכל</b>: ב\"ר פ\"א, ד."],["2144","111","<b>שזדונות נעשו כזכיות</b>: ראה יומא פו, ב."],["2145","112","<b>ברוך כבוד הוי' ממקומו</b>: יחזקאל ג, יב."],["2146","113","<b>אופנים אומרים ברוך</b>: חולין צב, רע\"א ובתוד\"ה ברוך."],["2147","114","<b>יוהכ\"פ ששרשו בבינה</b>: ראה תז\"ח צג, ג. פרדס שעה\"כ שכ\"ג, פ\"י מערכת יום בסופו. לקו\"ת מסעי צ, א. סידור שער יוהכ\"פ רמט, ד ואילך."],["2148","115","<b>התומ\"צ. . ז\"א ומל'</b>: ראה אגה\"ק ס\"כ (קלא, א). לקו\"ת במדבר יז, א."]]],[4801940574,"שמאיר בו מבחי' ימי קדם, אבל עיקר הסליחות הוא מבחי' מקור הרחמים שנמשך אחר התשובה להיות נושא עוון ועובר על פשע שזהו מבחי' סתימא דכל סתימין<sup data-n=\"2149\">116</sup> שנק' בחי' צור שבא ונמשך בבחי' גילוי ממש לנש\"י ביום הזה ולכן א' יכפר סתם<sup data-n=\"2150\">117</sup> להיות ידוע דשם הוי' הוא משמות שאינם נמחקים<sup data-n=\"2151\">118</sup> והטעם הוא מצד שהוא בחי' כלי לאוא\"ס השוכן בתוכו ונמצא שאינו שורה בו רק מבחי' האור המקור להתלבשות אורות בכלים כנ\"ל אבל בחי' אנכי אינו משמות שאינם נמחקים ואעפ\"כ הוא מורה על בחי' סדכ\"ס שלמעלה מבחי' מקור האורות המתלבשים בכלים, והטעם הוא כי שם אנכי אינו בחי' כלי לאור רק הוא הוראה בעלמא על העצמו', כי להיות אור נעלם לא יוכל להתלבש בבחי' האותיות בהלבשה ממש רק בא ומאיר באותיות בהעלם עד שאינם רק מורים בהוראה בלבד על עצמות, וזהו בחי' רדל\"א<sup data-n=\"2152\">119</sup> בלשון הקבלה, ולכן א' יכפר סתם, וזהו בחי' לפני הוי' שהוא למעלה משם הוי'<sup data-n=\"2153\">120</sup>, וזהו תטהרו כי תטהרו בגימט' תר\"ך<sup data-n=\"2154\">121</sup> כי תר\"ך עמודי אור<sup data-n=\"2155\">122</sup> הוא בחי' רמ\"ח מ\"ע ושס\"ה ל\"ת וז' מצות דרבנן<sup data-n=\"2156\">123</sup> שהמה כלים ולבושים להמשכת האור בהם כנ\"ל בענין אש אוכלה אבל ע\"י העדר מעה\"ת נעשה הסתלקות האור ח\"ו כטבע האש כנ\"ל, אך ע\"י התשובה נמשך כלים חדשים שהוא בחי' הזדונות שנעשה כזכיות ממש ונעשו כלים להמשכות האור כו' וד\"ל [... וטעם הדברים להיות שהם בחי' הריחוק שגרמו בחי' חילא יתיר כמבואר בלק\"א<sup data-n=\"2157\">124</sup> ולכן נעשה מהן לבושים וכלים להמשכת האור הנעלם שבא ע\"י התשובה כו' וד\"ל. ..] ולכן כה\"ג דייקא הוא האומר תטהרו וכמאמר ואף הוא הי' מתכוין<sup data-n=\"2158\">125</sup> כו' [... וטעם הדברים אפשר ע\"פ המבואר למעלה שהכהן הוא ביטול הרצון שעבודתו בחשאי ברעותא דליבא והנה כהן סתם הוא בחי' ביטול הרצון המורכב שנעשה מקור לטעם ודעת אבל בחי' גילוי נקודת הלב שהוא בחי' ביטול הרצון הפשוט שלמעלה מן הטעם לגמרי שאין נעשה אפי' בחי' מקור לטעם ודעת זהו בחי' כה\"ג ומשם יוכל להיות דייקא סליחת עוונות עד שזדונות נעשו כזכיות ולכן הוא האומר תטהרו בגימט' תר\"ך שזהו בחי' התהפכות הזדונות שנעשו כזכיות בבחי' עמודי אור כו' וד\"ל. ..].",[["2149","116","<b>סתימא דכל סתימין</b>: ראה זהר בהקדמה ב, א. ועוד."],["2150","117","<b>יכפר סתם</b>: ראה גם לקמן מאמר ד\"ה וידבר. . אלה הם מועדי תר\"כ על יד הערה 69."],["2151","118","<b>דשם הוי'. . שאינם נמחקים</b>: רמב\"ם הל' יסודי התורה פ\"ו, ה\"ב."],["2152","119","<b>בחי' רדל\"א</b>: ראה זהר אד\"ז האזינו רפח, א. ע\"ח שער א\"א שי\"ג, פ\"ב. לקו\"ת ראה כא, ב. יו\"כ עא, ג-ד."],["2153","120","<b>לפני הוי'. . משם הוי'</b>: אחרי טז, ל. ראה גם לעיל ע' קכד."],["2154","121","<b>תטהרו בגימט' תר\"ך</b>: בלקו\"ת כאן כו, רע\"ד מציין: לרמ\"ז ס\"פ אחרי תטהרו בגימ' כת\"ר."],["2155","122","<b>תר\"ך עמודי אור</b>: ראה פרדס שער מהות והנהגה ש\"ח, פ\"ג. לקו\"ת להאריז\"ל חבקוק. מאמרי אדה\"א ויקרא ח\"ב ע' תסא. וש\"נ. תו\"ח בראשית מה, ג הערה 32."],["2156","123","<b>רמ\"ח מ\"ע ושס\"ה ל\"ת וז' מצות דרבנן</b>: נסמן לעיל במאמר ד\"ה אשה כי תזריע תרכ\"ג פ\"ב."],["2157","124","<b>כמבואר בלק\"א</b>: פ\"ז."],["2158","125","<b>ואף הוא הי' מתכוין</b>: סדר עבודה ליוה\"כ."]]],[4801940105,"<b>ענין</b> העבודה דיוה\"כ<sup data-n=\"2159\">1</sup> שצריך לזה ד' תנאים הא' עיצומו של יום<sup data-n=\"2160\">2</sup> זה דייקא כי ביום אחר לא יפעול העובד מה שפועל ביום זה, הב' שהעבודה צ\"ל בכה\"ג<sup data-n=\"2161\">3</sup> דייקא ולא בכהן אחר, הג' צ\"ל הכ\"ג מלובש בד' בגדים<sup data-n=\"2162\">4</sup> שהם בגדי פשתן דייקא ויהיו לבנים דייקא, הד' עיקר העבודה היא עבודת הקטורת הנעשית לפני ולפנים<sup data-n=\"2163\">5</sup> בהיכל ק\"ק כו'. והענין יובן ע\"פ הידוע בענין ההפרש שבין יחיד לאחד<sup data-n=\"2164\">6</sup> כי אחד הוא התאחדות דברים מחולקים בלה\"ק ויש ב' אופנים בזה, הא' התאחדות אחרי ההתחלקות, והב' יחודם קודם התחלקותם כו', ועד\"ז למעלה כשעלה ברצוה\"פ להטיב<sup data-n=\"2165\">7</sup> או מח' דאנא אמלוך<sup data-n=\"2166\">8</sup> שזהו בחי' חסד ומל' דא\"ס שלפני הצמצום נק' אחד להיותם מקור להתפשטות רק מצד שכח ההתפשטות הוא בלי שיעור כי כל יכול להאציל ספי' עד אין קץ ומספר ולא עשר בלבד לכן נק' בשם א\"ס כי א\"ס להתפשטותו כו' ונק' אחד ע\"ד הב' בחי' יחוד שקודם ההתחלקות ונק' אחה\"פ להיותו מקור להתחלקיות לאין שיעור [משא\"כ מחה\"ק שלאחר הצמצום שכוללת רק ע\"ס דאבי\"ע ולא יותר נק' סתם אחד], משא\"כ בחי' יחיד הוא בחי' העצמו' כמו שהוא לבדו שנבדל מגדר גילוי והתפשטות לגמרי עד שגם בשם א\"ס לא יתכן לקרותו ולכן גם שהוא כל יכול כו' מ\"מ היכולת הוא בהעלם ג\"כ ואינה בגדר גילוי כמו העצמו' [ולכן למעלה גילוי היכולת להיות מקור להשפעה הוא ע\"י רצון דייקא שהוא בחי' ירידת העצמו' שזהו הרצון להטיב ולא בחיוב והכרח ח\"ו כו'] כי אין היכולת נבדלת מן העצמו' רק היכולת הוא העצמו' והעצמו' הוא היכולת ולא שהיכולת היא מתאחדת בעצם ולכן נק' בשם יחיד שאין שני לו שיתכן לומר שמתאחד בו כו' [וזהו ענין י\"ס שבבחי' יחיד היינו היכולת להאציל י\"ס שאינה נבדלת מן העצם כנ\"ל ועיין בשער היחוד סי' י' וי\"א].\n<b>והנה</b> בחי' הרצון הפשוט להיטיב ולהיות מלך על עם כו' יתכן לקרותו בשם ראשית להיותו מקור האמיתי דהשפעה והתפשטות, ועל זה נאמר המגיד מראשית אחרית<sup data-n=\"2167\">9</sup> שהוא ההמשכה מרצה\"פ הנק' ראשית עד מל' דאצי' שנק' אחרית",[["2159","1","<b>ענין העבודה דיוה\"כ</b>: לע\"ע לא נתברר אם דרוש זה הוא הנחת ר' הלל מדרושי רבותינו (כ\"ק אדמו\"ר האמצעי או כ\"ק אדמו\"ר הצ\"צ) או שזהו דרוש עצמו.\nלמאמר זה ראה מאמרי אדה\"א דברים ח\"ד ע' א'רלב ואילך. עט\"ר שער יוה\"כ ע' כט ואילך."],["2160","2","<b>עיצומו של יום</b>: אחרי טז, ל. ראה שבועות יג, א. (לקו\"ש יו\"כ כרך ד ע' 1150)."],["2161","3","<b>שהעבודה צ\"ל בכה\"ג</b>: ראה יומא לב, סע\"ב."],["2162","4","<b>הכ\"ג מלובש בד' בגדים</b>: אחרי טז, ד. ראה לקו\"ש אחרי כרך כב ע' 89 ואילך."],["2163","5","<b>הקטורת הנעשית לפני ולפנים</b>: ראה יומא מג, ב (במשנה). ראה לקו\"ש וילך כרך יד ע' 127 ואילך."],["2164","6","<b>ההפרש שבין יחיד לאחד</b>: ראה גם תו\"א וארא נה, ב. מאמרי אדה\"א בראשית ע' תק. וש\"נ. תו\"ח שמות ח\"א מז, א. וש\"נ. סה\"מ תרכ\"ז ע' קע. וש\"נ. תרכ\"ט ע' לא. וש\"נ."],["2165","7","<b>כשעלה ברצוה\"פ להטיב</b>: ראה ע\"ח שער עגו\"י ש\"א, ענף ב. לעיל ע' לה ובהערה 62."],["2166","8","<b>מח' דאנא אמלוך</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ז ”וכמ\"ש בזהר בפי' וימלוך אנא אמלוך\". הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצד. וראה גם לקמן ביאור על מאמר ד\"ה את שבתותי תרי\"ב ע' תטו."],["2167","9","<b>המגיד מראשית אחרית</b>: נוסח שטר תנאים ע\"פ ישעי' מו, י."]]],[4801940169,"בבחי' אצי' או עד מל' דמל' דעשי' שנק' אחרית לכל המדריגות משא\"כ בחי' קדם הוא בחי' העצמו' שאינו מקור להשפעה והתפשטות כלל, ועם זה יובן ענין עיצומו של יום שהוא יום מימי קדם ולכן נתגלה בו בחי' חסד הפשוט שבעצמו' שלמעלה מבחי' הרצון להיטיב והוא בחי' חסד שבבחי' יחיד שלמעלה מאחד והוא בחי' טבע הטוב שממנו נמשך הרצון להיטיב<sup data-n=\"2168\">10</sup> כו'. משא\"כ ימי כל השנה אפי' שבתות וימים טובים לא נגלה בהם רק בחי' ימות עולם שמקבלים מבחי' חסד עולם שהוא הרצון להיטיב שהוא מקור האמיתי דבחי' עולם כו', ולכן העבודה בכה\"ג דייקא ששרשו ג\"כ הוא בחי' חסד דלגיו שנק' רב חסד<sup data-n=\"2169\">11</sup>, שהוא חסד הפשוט שבעצמו' בחי' יחיד כו' משא\"כ כהן הדיוט הוא בחי' חסד<sup data-n=\"2170\">12</sup> עולם כו'. ולכן העבודה בבגדי פשתן ולבנים דייקא כי ידוע בענין הפשתן שנק' בד מצד שעולה בד בבד<sup data-n=\"2171\">13</sup> כי הנה כל הזרעים מגרעין אחד צומח כמה גבעולים נמצא שהגבעולים מתחלקין רק בשרשן שהוא גרעין הנזרע מתאחדים המה, משא\"כ בפשתן גרעין הנזרע צומח רק גבעול אחד ונמצא שהוא אחד בעצם ולא מתאחד עם זולתו. והנה ידוע בענין הבגדים הגם שהם נפרדים מן האדם מ\"מ היא הנותנת שישרה בהם מבחי' המקיפים<sup data-n=\"2172\">14</sup>, ויובן מרב המשפיע שכל לתלמידו שמצמצם עצמי' שכלו רק נקודה אחת בלבד נשארת בבחי' גילוי לצורך המקבל והיא המתגלית למקבל אח\"כ בדיבור משא\"כ עצמי' שכל הרב נשאר בבחי' העלם אך אעפ\"כ הוא מלובש באותיות הדיבור רק התלבשותו בבחי' העלם ומקיף בבחי' חיצוני' האותיות [ולכן אחר מ' שנין קאי' אדעתי' דרבי'<sup data-n=\"2173\">15</sup> כו'] דייקא משא\"כ פנימי' האותיות הם כלים לגילוי הנקודה בלבד כו' וד\"ל.\n<b>ובזה</b> יובן הטעם שהעבודה צ\"ל בבגדי פשתן להיות שביום זה ההמשכה הוא מבחי' יחיד דייקא לכן גם המקיפים הנמשכים על אדם העובד שהוא כה\"ג דייקא הם מקיפים שנמשכים מבחי' יחיד שלמעלה מאחד כו', ולכן צ\"ל בגדי בד שהוא ג\"כ בבחי' יחיד בעצם מתחילת הוויתו כו', ולכן צריכים להיות לבנים דייקא כי לבן הוא גוון עצמי<sup data-n=\"2174\">16</sup>, משא\"כ כל הגוונין הם רק מורכבים, נמצא שהלובן מורה",[["2168","10","<b>טבע הטוב. . להיטיב</b>: ראה שער היחוד והאמונה פ\"ד ובמ\"מ הגהות והע\"ק לשם. מאמרי אדה\"א קונטרסים ע' ה. וש\"נ. תו\"ח בראשית ל, ב הערה 4. לעיל ע' עז."],["2169","11","<b>בכה\"ג. . רב חסד</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תצ. וש\"נ. ש\"א מב, א הערה 25."],["2170","12","<b>כהן הדיוט. . חסד</b>: ראה זהר נשא קמה, ב. צו כז, א. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["2171","13","<b>הפשתן. . בד בבד</b>: ראה רש\"י ותוס' זבחים יח, ב. תו\"ח תרומה ח\"ב שז, א."],["2172","14","<b>הבגדים. . שישרה בהם מבחי' המקיפים</b>: ראה ספר הכונות (קארץ תקמ\"ד) ה, ב. ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"ג. פע\"ח שער התפלה ש\"א, פ\"ב. מאמרי אדה\"א קונטרסים ס\"ע יא ואילך. וש\"נ. תו\"ח בשלח ח\"א קפ, ג. וש\"נ."],["2173","15","<b>אחר מ' שנין קאי' אדעתי' דרבי'</b>: ראה ע\"ז ה, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. תו\"ח בשלח ח\"א ריז, ג הערה 418. המשך וככה תרל\"ז ספל\"ה. לקמן מאמר ד\"ה אם בחוקותי הג' על יד הערה 34."],["2174","16","<b>לבן הוא גוון עצמי</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תפד. וש\"נ. דברים ח\"ד ע' א'רלו-א'רלז."]]],[4801940228,"על גילוי העצמי' שלמעלה מבחי' מקור להתפשטות [והגם שבבחי' קוין יש בחי' קו הימין שהוא בחי' גוון לבן היינו בחי' לובן המוגבל בבחי' קו כמו הלובן שבתוך חלל האותיות שהשחור מגבילו אבל עצם הלובן אינו מוגבל כמו הלבן המקיף ולכן כל אות שאין גויל מקיפה<sup data-n=\"2175\">17</sup> כו', אך גם לובן המוגבל בבחי' קו שרשו בבחי' העצמו' ולכן הימין מתגבר לעולם על השמאל<sup data-n=\"2176\">18</sup> ולכן מחמת זה לא תמה זכות אבות<sup data-n=\"2177\">19</sup> מחמת אברהם ששרשו בקו הימין ושורש קו הימין הוא בחי' חסד הפשוט כנ\"ל וד\"ל], והוא בחי' הגילוי דיחיד כנ\"ל.\n<b>והנה</b> להבין ענין הבגדים בפרט שהם ד' כתונות ומכנסיים ואבנט ומצנפת כו', כי הנה הגם שמבואר למעלה שכללות ענין הבגדים אילו הם בחי' מקיפים מבחי' יחיד [ובנפש הוא גילוי מקיפים דיחידה כו'] מ\"מ ידוע שגם בבחי' יחידה כלול וגנוז בהעלם בחי' נרנ\"ח נמצא שיש ב' בחי' עצמות היחידה ובחי' נרנ\"ח הגנוזים בה [וכן למעלה מבחי'<sup data-n=\"2178\">20</sup> העצמות הנק' יחיד גנוז בחי' י\"ס כנ\"ל], והנה ג' לבושים המצנפת והכתונת ומכנסיים הם לבושים ומקיפים לחב\"ד חג\"ת נה\"י המצנפת הוא לבוש הראש הוא המקיף לחב\"ד ונמשך מבחי' חב\"ד הגנוז בבחי' יחיד, הכתונת לבוש הגוף הוא המקיף לחג\"ת ונמשך מבחי' חג\"ת שבבחי' יחיד, המכנסיים לבוש הרגל הוא המקיף לנה\"י ונמשך מבחי' נה\"י שבבחי' יחיד, אך לבוש הד' הוא האבנט אינו נצרך ללבוש כלל כי כבר הגוף לבוש מראשו עד רגלו רק נעשה לדבק המקיפים עם הפנימים כמו שבגשמיות פעולתו הוא לדבק הלבושים שיהי' צמודים ומדובקים בגוף.\n<b>וביאור</b> ענין חיבור המקיף בפנימי' יש להבין ענין המשכת המקיפים ע\"י לבישת הבגדים כנ\"ל [או מה שמבואר תמיד שע\"י עשיות המצות עושין לבושין וממשיכים בחי' מקיפים בלבושים] צ\"ל מהו, הלא בלא\"ה את השמים ואת הארץ אני מלא<sup data-n=\"2179\">21</sup> בבחי' העלם כידוע, אך הענין הוא דמה שהוא ית'<sup data-n=\"2180\">22</sup> סוכ\"ע הוא בהעלם גמור ואינו מאיר כלל [ואעפ\"כ הוא פועל קיום ההשתלשלות בכאו\"א שיתקיים במציאותו כמו שנאצל ונברא ע\"פ קו המדה בתחילת ההשתלשלות], משא\"כ בחי' אורות מקיפים הנמשכים ע\"י לבישת הבגדים [או ע\"י קיום המצות] היינו כאשר נמשכים בבחי' גילוי קצת רק שאינם נתפסים בכלי המקבל בדרך או\"פ ולכן מוכרח להיות איזה כלי שיהי' נתפס בו גילוי המקיפים כמו לבישת הבגדים [או עשיות המצות ופעולתם הוא שמירת המקבל שלא יפול ממדריגתו כמו לעולם ידור אדם במקום רבו<sup data-n=\"2181\">23</sup> שכל זמן ששמעי בן גרא קיים לא נשא שלמה כו' נמצא שמקום רבו הוא שומר",[["2175","17","<b>כל אות שאין גויל מקיפה</b>: מנחות לד, סע\"א."],["2176","18","<b>הימין מתגבר. . השמאל</b>: ראה שבת סא, א. לק\"ט ויחי מח, יד. שו\"ע אדה\"ז הל' השכמת הבקר ס\"ב, ס\"ד (במהדו\"ק ומהדו\"ת)."],["2177","19","<b>לא תמה זכות אבות</b>: שבת נה, א."],["2178","20","<b>מבחי'</b>: אוצ\"ל: בבחי'."],["2179","21","<b>את השמים ואת הארץ אני מלא</b>: ירמי' כג, כד."],["2180","22","<b>ית'</b>: אינו ברור בהכת\"י, ואולי כצ\"ל."],["2181","23","<b>לעולם ידור אדם במקום רבו</b>: ברכות ח, סע\"א."]]],[4801940281,"עליו, וכן שומר מצוה לא ידע דבר רע<sup data-n=\"2182\">24</sup> והיינו כאשר נזדמן לו דבר עבירה שלא הי' יכול לכבוש תאוותו מצד עצמו רק מצד שעשה מצוה מכבר והמשיך בחי' מקיף על נפשו אינו מניחו לעשות העבירה ואינו יודע בעצמו מי אינו מניחו והוא הכאת המקיף בפנימי כמשל הדוחף לחברו מאחוריו<sup data-n=\"2183\">25</sup> [כמו אם בשבט הכהו<sup data-n=\"2184\">26</sup> כו'] [משא\"כ מצד בחי' הסובב הוא רק קיום הטבעת הנברא וזה הוטבע בהשתלשלות בחי' נפילה כמו שהי' בעולם התוהו כו'], אך ענין חיבור ודיבוק המקיף בפנימי הוא כשהמקיף עושה רושם בבחי' הפנימי ואעפ\"כ אינו מאיר בדרך או\"פ ממש והיינו ע\"ד דברים היוצאים מן הלב<sup data-n=\"2185\">27</sup> נכנסים ללב כמו תפלת צדיק<sup data-n=\"2186\">28</sup> שעושה רושם ממש בלב השומע והוא קבוע בתמידות בלב השומע עד שמעורר אותו לפרקים לתשובה או לעשיות מצות [משא\"כ שמירה הנ\"ל הוא מרחוק ואינו רק לסור מרע כנ\"ל], זהו בחי' דיבוק וחיבור המקיף בפנימי וזהו פעולת האבנט כנ\"ל וד\"ל.\n<b>אך</b> עוד ענין אחד פועל האבנט ויובן בהקדם ענין מדות המצנפת והאבנט שהמצנפת מידתה הי' שש עשרה אמה והאבנט הי' מדתו ל\"ב אמה<sup data-n=\"2187\">29</sup> בכופל מהמצנפת כו', והענין הוא כי יש ד' מוחין חו\"ב ומוח הדעת שכולל בתוכו שני מוחין ולכן נחלק לחו\"ג<sup data-n=\"2188\">30</sup> ובכל מוח יש בו ח' חדרים והוא כנגד שמונה אותיות דהוי' אדני כו' ולכן כללות מספרם הוא שלשים ושנים כנגד ל\"ב שבילין<sup data-n=\"2189\">31</sup> כידוע דאית חכמתא עילאה סתימאה כו' ואית חכמתא דמתפתחא לל\"ב שבילין כו', וטעם התחלקות המוחין כאו\"א לח' כנגד ח' אותיות הנ\"ל, הנה ידוע דמקור עולמות הנבראים מאין ליש הוא שתי שמות דהוי' אדני, כי הוי' הוא בחי' צמצום והתפשטות<sup data-n=\"2190\">32</sup> המשכה והתפשטות [שזהו ע\"י המידות דאצי' שהם התחלת המשכה להיות מקור לעולמות כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"2191\">33</sup> כו'] עד שמתלבש בלבוש מלכות [שזהו בחי' אדני<sup data-n=\"2192\">34</sup> אנת אשתמודע אדון על כולא<sup data-n=\"2193\">35</sup> ] להיות מלך על",[["2182","24","<b>שומר מצוה לא ידע דבר רע</b>: קהלת ח, ה. ראה גם לקמן מאמר ד\"ה והתהלכתי תרכ\"ב על יד הערה 78."],["2183","25","<b>כמשל הדוחף לחבירו מאחוריו</b>: השוה גם לעיל מאמר ד\"ה הנה וכו' והצרוע תקצ\"ט על יד הערה *83."],["2184","26","<b>אם בשבט הכהו</b>: ראה משפטים כא, כ. ראה גם מאמרי אדה\"א שמות ח\"א ע' יד. וש\"נ. תו\"ח משפטים ח\"ב רצג, א. וש\"נ."],["2185","27","<b>דברים היוצאים מן הלב</b>: ספר הישר לר\"ת שי\"ג. הובא של\"ה שער האותיות אות כ (סט, א). שירת ישראל לר' משה בן עזרא (ירושלים תשכ\"ז ע' קנו). לעיל ע' מ."],["2186","28","<b>כמו תפלת צדיק</b>: ראה גם לקמן מאמר ד\"ה שבת שבתון ובהערה 69."],["2187","29","<b>שהמצנפת. . שש עשרה. . והאבנט. . ל\"ב אמה</b>: רמב\"ם ספ\"ח מהל' כלי המקדש."],["2188","30","<b>הדעת שכולל. . לחו\"ג</b>: ראה ע\"ח שער תיקון הנוקבא של\"ד, פ\"ג. מאמרי אדה\"א בראשית ע' ד. וש\"נ. תו\"ח וארא ח\"א נז, ד הערה 14."],["2189","31","<b>מוח. . ח' חדרים. . ל\"ב שבילין</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'רמב. וש\"נ."],["2190","32","<b>הוי'. . צמצום והתפשטות</b>: ראה אגה\"ת פ\"ד. לקו\"ת בשלח א, א."],["2191","33","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם לעיל ע' קיג ובהערה 90."],["2192","34","<b>מלכות. . אדני</b>: ראה זהר ויקרא יא, א. ראה מאמרי אדה\"א בראשית ע' קצז. וש\"נ. תו\"ח נח סד, ג הערה 44."],["2193","35","<b>אנת אשתמודע אדון על כולא</b>: ת\"ז בהקדמה יז, רע\"ב. ראה גם לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב ובהערה 56."]]],[4801940331,"עם הנבראים בפ\"מ כו', והנה ידוע דעצמות אא\"ס לאו מכל אינון מדות כלל<sup data-n=\"2194\">36</sup> לכן כאשר צריך להתלבש במדות הוא ע\"י אמצעית המוחין וידוע שכל ממוצע צ\"ל להיות<sup data-n=\"2195\">38</sup> כלול משני הבחי'<sup data-n=\"2196\">37</sup> המתחברים על ידו ולכן המוחין מצד הפנימי' שלהם מתלבש בהם בחי' א\"ס כו' ומצד החיצוני' שלהם כוללים בתוכם ח' חדרים שהם שרש בחי' הוי' אדני כו' וד\"ל], והנה ידוע דעצם המוחין הם שנים<sup data-n=\"2197\">39</sup> שהם בחי' חו\"ב ומוח הג' שהוא בחי' הדעת הנחלק לחו\"ג עיקר פעולתו לחבר המוחין שבמוח אל הלב כו' ונמצא שבלב מתקבץ כל הד' בחי' כי עצמותו הוא בחי' מדות וכל המדות נכללים בשני מדות הראשונים שהם חו\"ג שהם עיקריים וכל המדות הם ענפים כמ\"ש בלק\"א ח\"א פ\"ג אך גם המוחין נמשכים בו בדרך התלבשות בפנימיותו נמצא שיש בו ד' בחי' כ\"א כלול מח' ולכן נק' בשם ל\"ב ע\"ש קיבוץ הל\"ב בחי'<sup data-n=\"2198\">40</sup> שמתקבצים כולם בו, ולכן הי' מדות המצנפת ט\"ז אמה להיותה רק לבוש ומקיף אל עצם המוחין שהם חו\"ב שיש בהם רק ששה עשר בחי' משא\"כ מדת האבנט הי' ל\"ב מצד שחגירתו הי' כנגד הלב<sup data-n=\"2199\">41</sup> שזהו שליש העליון שבגוף מקום חיבור המוחין עם המדות ושם מתקבצין כל הל\"ב בחי' יחד כנ\"ל וד\"ל, וא\"כ זה יורה על פעולת האבנט שהוא ג\"כ לחבר ולייחד המוחין עם המדות מלבד פעולתו לייחד המקיף בפנימי כו' וד\"ל [ויובן ע\"פ הקדמה הידועה בענין שרש הדעת שהוא למעלה מבחי' חו\"ב רק שרשו בבחי' הכתר<sup data-n=\"2200\">42</sup> וכן עד\"ז האבנט למטה בכה\"ג הוא בבחי' הדעת לייחד המוחין במדות ושרשו במקיף דיחידה לכן פועל לחבר המקיף בפנימי כנ\"ל].",[["2194","36","<b>לאו מכל אינון מדות כלל</b>: ראה ת\"ז בהקדמה יז, ב."],["2195","38","<b>להיות</b>: כנראה שתיבה זו מיותרת."],["2196","37","<b>ממוצע. . כלול משני הבחי'</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. סידור שער הל\"ג בעומר שו, ב. אוה\"ת בשלח ע' תקע ואילך."],["2197","39","<b>דעצם המוחין הם שנים</b>: ראה מאמרי אדה\"א דברים ח\"ד כאן ע' א'רמב. עט\"ר לה, ב."],["2198","40","<b>ל\"ב ע\"ש קיבוץ הל\"ב בחי'</b>: ראה ע\"ח שער פרצופי זו\"ן של\"א, פ\"ד. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תמב."],["2199","41","<b>האבנט. . כנגד הלב</b>: ראה רמב\"ם הל' כלי המקדש פ\"י, ה\"א-ב."],["2200","42","<b>שרש הדעת. . בבחי' הכתר</b>: ראה לקו\"ת שלח נ, א."]]],[4801940106,"<b>הנחה בד\"א ואין להשען ע\"ז כלל</b>\n<b>מנין</b> שקושרין לשון של זהורית בראש שעיר המשתלח שנאמר אם יהיו חטאיכם כשנים<sup data-n=\"2201\">2</sup> כשלג ילבינו (משנה במס' שבת דפ\"ו ע\"א). ובגמרא שם דפ\"ט ע\"ב)<sup data-n=\"2202\">3</sup> כשנים כשני מבע\"ל א\"ר יצחק אמר להם הקב\"ה לישראל אם יהיו חטאיכם כשנים הללו שסדורות ובאות משי\"ב ועד עכשיו כשלג ילבינו. ובירושלמי (שבת פ\"ט ה\"ג ויומא פ\"ו ה\"ה) ר' אליעזר אומר אם יהיו חטאיכם כשנים שבין שמים לארץ כשלג ילבינו יותר מכן כצמר יהיו, ר' יהושע אומר אם יהיו חטאיכם כשנים כשני אבות כשלג ילבינו יותר מכן כצמר יהיו. והנה<sup data-n=\"2203\">4</sup> ע\"ד הפשוט<sup data-n=\"2204\">5</sup> הפי' כשני אבות הם כימי השמים על הארץ כי שני האבות הם תק\"ב<sup data-n=\"2205\">6</sup> וב' שנים הראשונים דאברהם אינם בחשבון כמ\"ד בן ג' שנים הכיר את בוראו<sup data-n=\"2206\">7</sup>, והפי' כשני האבות כמה שהיו עובדים את ה' והיו מרכבה להכי לא קחשיב הב' שנים קודם שהכיר [ואולי<sup data-n=\"2207\">8</sup> ב' שנים קודם שהכיר הם ב' מקיפים דחי' ויחידה קודם ההכרה דחכ'], נמצא לא נחשבו שני האבות רק ת\"ק שנים והוא כמו מן הארץ עד לרקיע מהלך ת\"ק שנה, וא\"כ צריך להבין הפלוגתא שבין ר\"א לר\"י שבירושלמי. וגם למה מדד ר\"י החטאים בשני האבות שהיו עובדי ה' והיו מרכבה<sup data-n=\"2208\">9</sup>. וגם צ\"ל פי' הגמ' כשנים הללו שהם סדורות ובאות מששת ימי בראשית כו'. ומה בין הגמ' להירושלמי. עוד צ\"ל דהלא התלמוד והירושלמי מפרשים הפסוק אם יהיו חטאיכם כשנים כו', ונמצא לדברי כולם אם יהיו חטאיכם רק כשנים הללו שהן סדורות ובאות משימ\"ב כו' לפי' הגמ' או להירושלמי אם יהיו חטאיכם רק כשנים שבין שמים לארץ כו' לדברי ר\"א, או יהיו חטאיכם רק כשני האבות לדברי ר\"י, אז כשלג ילבינו. יותר מכן זהו פי' אם יאדימו כתולע<sup data-n=\"2209\">10</sup> כצמר יהיו, והפי' הפשוט שאם החטאים יתירים על כשנים לכל השיטות הנ\"ל והיינו אם יאדימו כתולע אז אפי' ע\"י תשובה לא יהיו",[["2201","2","<b>אם יהיו חטאיכם כשנים</b>: ישעי' א, יח."],["2202","3","<b>ובגמ' שם דפ\"ט ע\"ב)</b>: כנצ\"ל: ובגמ' (שם דפ\"ט ע\"ב)."],["2203","4","<b>ובירושלמי. . והנה</b>: א: ובירושלמי מקשה ג\"כ הכי כשני מבע\"ל ומתרץ אם יהיו חטאיכם כשני האבות כשלג ילבינו, ומסיים יתר על כן כצמר יהיו, וצ\"ל בזה כמה ענינים א, מהו החילוק בין בבלי לירושלמי דהנה."],["2204","5","<b>ע\"ד הפשוט</b>: ראה גם שירי קרבן לירושלמי שבת כאן בסופו. אוה\"ת נ\"ך כרך ג וסה\"מ תרכ\"ט שבהערה 1."],["2205","6","<b>שני האבות הם תק\"ב</b>: אברהם חי קע\"ה ויצחק ק\"פ ויעקב קמ\"ז (אוה\"ת כאן ע' א'קעז)."],["2206","7","<b>בן ג' שנים הכיר את בוראו</b>: נדרים לב, סע\"א. מאמרי אדה\"א ויקרא ח\"א ע' פ. וש\"נ. הנחות תקע\"ז ע' קע. וש\"נ. סה\"מ ליקוט ח\"ב ע' מ."],["2207","8","<b>והפי'. . [ואולי</b>: א: [והפי'. . ואולי."],["2208","9","<b>האבות. . מרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. תו\"ח נח מט, ד ובהערה 42."],["2209","10","<b>וא\"כ צריך להבין. . כתולע</b>: א: לפי\"ז צריך לפרש מרובים מן הארץ עד לרקיע, ויש להבין למה נקט הבבלי הפלגת ההגזמה דריבוי העוונות על הזמן דידו\"ב (דשי\"ב ), והירושלמי נקט ההפלגה במקום אם יהיו מן הארץ עד לרקיע. ב, למה צריך לזה מדות שני האבות יאמר כמדת השנים שמן הארץ עד לרקיע ולמה נקטו שני האבות שעבדו את ד' למדוד בהן עוונות ח\"ו. ג, מהו דקדוק הלשון שהן סדורות ובאות. ד, דהנה לפי האמת לא נוכל לפרש ההפלגה ע\"ד ההגזמה מאחר שהירושלמי מסיים יתר על כן משמע שהוא מדה מכוונת ומדוקדקת שאם החטאים רק כשני האבות אזי ע\"ש (ע\"י ) תשובה כשלג כו' אבל יתר ע\"כ שהוא פיר' על מה שכתוב אם יאדימו אזי כצמר יהיו כמשי\"ת, ולפ\"ז גם הבבלי דנקט המדה בשנים שמשי\"ב ועד עכשיו הלא (הוא ) ג\"כ מדה מצומצמת ומכוונת שהרי הפסוק מסיים אם יאדימו ואין זה פי' ההפלגה על הריבוי בדרך הגזמה והוא פלא וז\"ל (וצ\"ל ) הטי\"ב מהו מדת שי\"ב לדעת הבבלי ומדת שני האבות לדעת הירושלמי. ה, סיום הירושלמי יתר ע\"כ צריך להבין כי יש בזה ב' משמעות כי הנה ע\"ד הפשוט הכוונה שאם החטאים יתירים על מדת שני האבות."]]],[4801940170,"לבנים כשלג רק כצמר שנמוך במראה הלבנונית מן השלג כדתנן במראות נגעים בהרת עזה כשלג<sup data-n=\"2210\">11</sup> כו' שאת כצמר לבן כו', ולהיפוך אפשר לפרש למעליותא שמה שאמר כצמר יהיו קאי על מדריגת התשובה שצ\"ל בעומק יותר לעורר למעלה בחי' צמר שאף שאינו לבן כמו שלג עכ\"ז הוא<sup data-n=\"2211\">12</sup> בחי' גבוה יותר מבחי' שלג כמ\"ש לבושי' כתלג חיור<sup data-n=\"2212\">13</sup> ושער רישי' כעמר נקא, נמצא שבחי' השלג הוא רק לבושי' אבל הצמר נק' שער רישי' שהוא נחשב עצמי' לגבי לבושים כדמצינו בענין הטבילה (כי התשובה נמשל למקוה כמ\"ש מקוה ישראל<sup data-n=\"2213\">14</sup> כו' שהובא על מה שארז\"ל אשריכם ישראל כו' ומי מטהר אתכם<sup data-n=\"2214\">15</sup> כו') טבל את גופו ולא טבל את בגדיו עלתה לו טבילה אבל טבל כו' ולא טבל את שערו<sup data-n=\"2215\">16</sup> ואפי' מקצת שערו לא עלתה לו טבילה<sup data-n=\"2216\">17</sup>, מכלל שהם נחשבים מכלל עצמי' האדם, וכן מפרש בסידור ע\"פ הנותן שלג כצמר<sup data-n=\"2217\">18</sup>, שבשלג שהוא בחי' ח\"ס דא\"א מאיר בחי' צמר שהוא בחי' גלגלתא שמאיר בו חסד דע\"י והוא שבחו של מקום כמבואר שם באריכות. והנה לפ\"ז יתפרש הכתוב אם יהיו חטאיכם רק כשנים לכל הפי' הנ\"ל<sup data-n=\"2218\">19</sup>, אז אפי' כשלג ג\"כ ילבינו, היינו שאם יעורר בתשובתו למע' רק בחי' שלג שהוא י\"ג מדות דא\"א יומשך משם ג\"כ הסליחה, אבל אם יאדימו כתולע שהוא יותר מכן אז אין מספיק התשו' כשלג היינו<sup data-n=\"2219\">20</sup> מבחי' יג\"מ דא\"א אא\"כ כצמר יהיו דהיינו שיעורר למעלה בחי' צמר שהוא בחי' ע\"י אזי משם יוכל להמשיך לו הסליחה<sup data-n=\"2220\">21</sup>. והנה להבין כל הנ\"ל יש להקדים שלשה חילוקי כפרה שהי' רי\"ש דורש<sup data-n=\"2221\">22</sup>, עבר על מ\"ע ושב אינו זז משם עד שמוחלין לו עבר על מל\"ת תשובה תולה ויוה\"כ מכפר, עבר על",[["2210","11","<b>בהרת עזה כשלג</b>: ראה נגעים פ\"א, מ\"א."],["2211","12","<b>שאף שאינו. . הוא</b>: א: שהוא."],["2212","13","<b>לבושי' כתלג חיור</b>: דניאל ז, ט."],["2213","14","<b>מקוה ישראל</b>: ירמי' יז, יג."],["2214","15","<b>אשריכם ישראל. . אתכם</b>: יומא פה, ב."],["2215","16","<b>ולא טבל את שערו</b>: ראה רמב\"ם הל' מקוואות פ\"א, ה\"ז."],["2216","17","<b>ואפי'. . טבילה</b>: א: לא עלתה כו'."],["2217","18","<b>בסידור ע\"פ הנותן שלג כצמר</b>: שחרית סג, ב ואילך."],["2218","19","<b>הכתוב. . הנ\"ל</b>: א: הפסוק בסגנון שאם יהי' חטאיכם רק כשנים שהוא כשי\"ב לפי' הבבלי או כשני האבות לפי' הירושלמי."],["2219","20","<b>כשלג היינו</b>: א: ליתא."],["2220","21","<b>הסליחה</b>: שם ניתוסף: לפ\"ז צ\"ל איך כוונת הכתוב אם כפי' הא' הנ\"ל או כפי' הב' [ולפי הכלל שבכ\"מ שהכתוב סובל ב' פירושים שניהם אמת א\"כ אינו מובן מאחר שיתעורר בתשובה ממונה (מעולה ) בחי' (מבחי' ) ומדריגת יותר הגבוה למה יהי' הלבנונית מועט ובפרט שלפי האמת מוכרח לומר שהצמר יותר גרוע לבנינותו מן השלג וא\"כ צ\"ל למה]."],["2221","22","<b>שלשה חילוקי כפרה שהי' רי\"ש דורש</b>: ראה יומא פו, א. לקו\"ש אחרי כרך יז ע' 194 ואילך. וש\"נ."]]],[4801940229,"כריתות ומב\"ד תשובה ויוה\"כ תולין ויסורין ממרקין שנאמר ופקדתי בשבט פשעם<sup data-n=\"2222\">23</sup> כו', ולהבין למה הוא כן<sup data-n=\"2223\">24</sup>.\nב) <b>הנה</b> איתא בת\"ז (בהקדמה דף ד' סע\"ב ודף ה' ע\"א) שמי עם י\"ה<sup data-n=\"2224\">25</sup> שס\"ה ל\"ת זכרי עם ו\"ה רמ\"ח מ\"ע<sup data-n=\"2225\">26</sup>. ולהבין זה מפני מה מ\"ע שרשם בו\"ה ומל\"ת בי\"ה. דהנה אנו רואים בנפש האדם שלעשות מ\"ע אין מספיק שיעורר המוחין שלו רק צריך דוקא לעורר המדות, כאשר אנו רואים בחוש שכמה בני אדם שמכירים ויודעים בשכלם שראוי ונכון לעשות מ\"ע וכן ללמוד ולהתפלל מ\"מ כ\"ז שאין לו חשק בלב לא יזדרז לעשות מצות וכן ללמוד ולהתפלל, וכמבואר בתניא שהלב חומרי וגשמי<sup data-n=\"2226\">27</sup> וקרוב לאברי המעשה, והטעם ע\"ז הוא מחמת שהשכל הוא ראשית הגילוי מן הנפש והוא עדיין קרוב למקור<sup data-n=\"2227\">28</sup> ולכן הוא רחוק עדיין מאברי המעשה, ולכן ציור הגוף שהוא מכוון בדוגמת ציור הנפש הראש שבו משכן השכל הוא ממעל לאברי הגוף והלב משכנו בתוך הגוף, והשכל שבמוח נק' אור המאיר לעצמו, וביכלתו להשכיל השכלות שאינם שייכים כלל לזולת ולפועל, משא\"כ המדות שבלב נק' אור המאיר לזולתו, ולכן לא יתכן גילוי מדה בלב אם לא שיתגלה ממנה איזה תנועה בפועל, ולכן כלי המוח הוא קר ולח, וכלי הלב הוא חם, ולכן גידי הדם שמן הלב ממשיכים חום הטבעי בכל האברים, וגידי המוח מצננים דוקא, וכן מי שהוא בעל מדות הוא איש נלבב ומחומם<sup data-n=\"2228\">29</sup> אבל מי שהוא בעל מוחי' הוא מיושב ומצונן, וא\"כ כדי לקיים מ\"ע בזריזות שצריך לזה זירוז ותנועה קלה אין זה כ\"א ע\"י שיעורר מדות שבלב דוקא, כידוע שתנועת החי הוא מהחום הטבעי כדרך האש להתנענע, ולכן מי שמרובה בדמים הוא זריז, כמ\"ש ע\"פ והוא אדמוני כו' גבי דוד<sup data-n=\"2229\">30</sup>, ודבר זה ידוע שעשר כוחות שבנפש הם דוגמא לעשר ספירות<sup data-n=\"2230\">31</sup> עליונות שנשתלשלו מהם המרומזים בשם הוי'<sup data-n=\"2231\">32</sup>, ולכן כשם שע\"י מ\"ע מעורר ו\"ה שבנפשו כן למעלה ויעורר עי\"ז בחי' ו\"ה שהוא מדות עליונות (שהם מקור העולמות כמשי\"ת) וע\"ז אמר זכרי עם ו\"ה רמ\"ח מ\"ע, אבל לענין מל\"ת שאין שייך התפעלות וזריזות בדבר שאינו שייך כ\"א בשב ואל תעשה, אדרבה שם העיקר צריך לעורר ולחזק את המוחין שיהי' מוח שליט על הלב<sup data-n=\"2232\">33</sup>, שאף שהלב שלו מלא התפעלות אל ההיפוך ר\"ל ויצרו בוער כו' מ\"מ צריך למשול ולהתאפק על רוח תאוותו ולצנן את רתיחת הדמים מהלב ע\"י",[["2222","23","<b>ופקדתי בשבט פשעם</b>: תהלים פט, לג."],["2223","24","<b>כן</b>: א ניתוסף: והוא הקדמה להבין הכללים פי' הבבלי ופי' הירושלמי בענין השנים, ויתר מכאן שהוא פי' אם יאדימו וממילא יתבארו כל פרטי הדקדוקים בעז\"ה."],["2224","25","<b>שמי עם י\"ה</b>: ראה גם לעיל מאמר ד\"ה במדרש איתא והצרוע תקצ\"ו הערה 33."],["2225","26","<b>מ\"ע</b>: א ניתוסף: שצריך זירוז."],["2226","27","<b>וכמבואר בתניא שהלב חומרי וגשמי</b>: פט\"ז."],["2227","28","<b>למקור</b>: א ניתוסף: והוא בעילוי אל מקורו."],["2228","29","<b>ומחומם</b>: שם: הוא רתחן."],["2229","30","<b>והוא אדמוני. . דוד</b>: שמו\"א טז, יב. ראה גם סה\"מ תר\"ל ע' שיב וע' שיח."],["2230","31","<b>שעשר כוחות. . לעשר ספירות</b>: ראה תניא פ\"ג."],["2231","32","<b>לעשר ספירות עליונות. . המרומזים בשם הוי'</b>: אגה\"ת פ\"ד."],["2232","33","<b>מוח שליט על הלב</b>: ראה תניא פי\"ב. מאמרי אדה\"א דברים ח\"ב ע' תצ. וש\"נ."]]],[4801940282,"המוחין שפעולתם לקרר דוקא ולכן גם למעלה מעורר עי\"ז בחי' י\"ה שהוא המוחין עליונים ולכן שמי עם י\"ה שס\"ה ל\"ת.\nג) <b>והנה</b> כ\"ז הוא כשמקיים מ\"ע מעורר בחי' ו\"ה וע\"י ל\"ת בחי' י\"ה כנ\"ל, וממילא מובן שאם עבר על מ\"ע (אבל מל\"ת לא עבר ח\"ו מעולם) פגם עי\"ז למעלה בחי' מדות עליונות ובנפשו ניכר שלא האיר את מדות שבנה\"א, ויש אצלו טמטום הלב<sup data-n=\"2233\">34</sup>, כי המוחין לא פגם, והראי' שלא עבר על מל\"ת מעולם, שניכר שמוח שליט על לבו שלא לעשות רע בפועל מפני פחד ה', וא\"כ למה מטעם זה לא נזדרז לעשות מ\"ע ג\"כ, אע\"כ הטעם כנ\"ל כי המוחין מרוממים ומנושאים עדיין מלנענע אברי המעשה הן מצד האור הן מצד הכלי כנ\"ל באריכות. וע\"כ התיקון לזה הוא תשו' שהוא בינה<sup data-n=\"2234\">35</sup> כמ\"ש המקובלים<sup data-n=\"2235\">36</sup>, וכמ\"ש במד\"ר מנין לתשו' שקדמה לעולם<sup data-n=\"2236\">37</sup> שנאמר בטרם הרים יולדו<sup data-n=\"2237\">38</sup> מאותה שעה תשב אנוש<sup data-n=\"2238\">39</sup> כו', ואין הכוונה קדימה זמנית כי קודם שנבה\"ע לא הי' מי שיחטא ומי שישוב, אע\"כ הכוונה היא קדימה במעלה, כי עולם הוא מדות כמ\"ש עולם חסד יבנה<sup data-n=\"2239\">40</sup> שהמדות הוא מקור העולמות כמו שנת' באדם שהמדות הם מקור לפועל והמוחין מרוממים מן הפעולה עדיין כנ\"ל, כ\"ה למעלה כי עצמי' אא\"ס<sup data-n=\"2240\">41</sup> הוא פשוט בתכלית הפשיטות ואינו מקור עדיין לעולמות, אמרו<sup data-n=\"2241\">42</sup> אנת הוא דאפיקת עשר תקונין<sup data-n=\"2242\">43</sup> והע\"ס נאצלו מלמעלה למטה כסדרן, עד\"מ באדם שמתחלה מתבונן בשכלו ואח\"כ מתפעל בלבו וכשנאצלו ג\"ר לא הי' עדיין מקור לעלמין דאתגליי' (שנק' עולם בלשון הכתוב ע\"ש שהוא מעלים<sup data-n=\"2243\">44</sup> ומסתיר על כח אלקי המהווהו), כמו עד\"מ באדם שהמוחין אינם רק אור המאיר לעצמו, ומתרוממים מן המעשה עדיין<sup data-n=\"2244\">45</sup>, רק א\"א לומר שמן המוחין שנאצלו",[["2233","34","<b>טמטום הלב</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקס ואילך. וש\"נ. תו\"ח שמות ח\"א ב, ב. וש\"נ."],["2234","35","<b>תשו' שהוא בינה</b>: ראה זהר ס\"ת לך פ, סע\"ב. רע\"מ נשא קכב, א וסוע\"ב. לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב הערה 73."],["2235","36","<b>המקובלים</b>: א: בספרי המקובלים."],["2236","37","<b>מנין לתשו' שקדמה לעולם</b>: ראה ב\"ר פ\"א, ד. לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב ובהערה 66."],["2237","38","<b>בטרם הרים יולדו</b>: תהלים צ, ב."],["2238","39","<b>תשב אנוש</b>: תהלים שם, ג."],["2239","40","<b>עולם חסד יבנה</b>: תהלים פט, ג. ראה גם לעיל ע' קיג ובהערה 90."],["2240","41","<b>כי עצמי' אא\"ס</b>: א: ואדרבה עיקר הטעם למה בנפש האדם הוא כן הוא מצד שאדם מצויר בדוגמא של מעלה ולמעלה המדות הם מקור לעולמות והמוחין למעלה ממקור לעולמות, כי הגם שביארנו טעם פשוט מצד האור והכלי בנפש, הנה כל הטעמים שאנו מוצאים על תבנית הבריאה מצד השכל הוא מחמת שנבראו כן ע\"פ חכ' עליונה כמ\"ש כולם בחכ' עשית והחכ' כלולה בנפש האדם ע\"כ יוכל למצא טעם בשכל כפי שמדדה החכ' עליונה שישנה בנברא, אבל אם היה נברא באופן אחר ובציור אחר אז הי' השכל מוצא טעם לנברא ההוא ג\"כ ע\"פ כח החכ\"ע, נמצא שכל הטעמים הפשוטים אינם מספיקים אלא לאחר שנברא כן, אבל הטעם האמת על ציור נפש האדם למה מצוייר באופן זה הוא מחמת שלמעלה הוא כן כמ\"ש בצומים ( ) כי עצמיו'."],["2241","42","<b>אמרו</b>: שם: כמא' אנת הוא חד ולא בחושבן ולכן כשעלה ברצונו לברא עולמות אמרו."],["2242","43","<b>אנת הוא דאפיקת עשר תקונין</b>: ת\"ז בהקדמה יז, א."],["2243","44","<b>עולם. . שהוא מעלים</b>: ראה מאמרי אדה\"א נ\"ך ע' רב. וש\"נ. תו\"ח שמות ח\"א יח, ד. וש\"נ."],["2244","45","<b>עדיין</b>: א ניתוסף: מחמת שלמע' הוא כנ\"ל."]]],[4801940332,"לא נתהווה עדיין כלום כמו באדם שלמטה שהרי כתי' כולם בחכמה עשית<sup data-n=\"2245\">46</sup>, ועז\"נ כי לא מחשבותי מחשבותיכם<sup data-n=\"2246\">47</sup> שמן המוחין שהם ג\"ר נתהוו עלמין דאתכסיין, אבל<sup data-n=\"2247\">48</sup> עדיין הם בתכלית היחוד וההתכללות, אבל ע\"י מדות יצאו לגילוי מן ההעלם שיהי' נק' בשם זולת, כי המדות נק' אור המאיר לזולתו, כי המדה לעצמו אין לה התגלות (והראי' מאהבת עצמו שאינה מורגשת) אם לא לזולתו כמו החסד שהוא להטיב לזולתו (רק למטה באדם לא מהמדה יתהווה הזולת אדרבה מהזולת יתהווה המדה אם להטיב או כו'<sup data-n=\"2248\">49</sup>, אבל למעלה מאחר שהאציל מציאות החסד שהוא להטיב לזולתו ומחייב שיהי' זולת, מזה גופא נתהווה הזולת, רק<sup data-n=\"2249\">50</sup> שלא היו עדיין נפרדים מחמת השפעת המדות בקירוב הערך, לכן האציל מדת המל' שהוא רוממות והתנשאות ועי\"ז נראים כאלו הם נפרדים<sup data-n=\"2250\">51</sup> כמ\"ש במ\"א).\n<b>וזהו</b> פי' הכתוב כי אמרתי עולם חסד יבנה שמקור העולמות הוא מהמדות דוקא כנ\"ל, וע\"ז אמר שתשו' קדמה במעלה מן המדות שהתשובה היא בבינה שהוא מקור המדות, ולמדו מזה הפסוק בטרם הרים שהם מדות<sup data-n=\"2251\">52</sup> (כי המדות הוא בליטה מן הנפש) כמ\"ש לא כאברהם שקראו הר<sup data-n=\"2252\">53</sup>, ואברהם הוא מדת החסד<sup data-n=\"2253\">54</sup>, מאותה שעה תשב אנוש כו', כי מחמת שע\"י העדר מ\"ע פגם במדות שבנפש כנ\"ל, העצה לזה שיעמיק בהתבוננות עד שיוליד מדות מחדש, כי הבינה נק' אם הבנים<sup data-n=\"2254\">55</sup> שמוליד את המדות, היינו שאם לא הי' פוגם במ\"ע שנוגע הפגם בו\"ה שבנפשו היו מאירים המדות שבנה\"א אצלו ולא הי' צריך לריבוי העמקת הדעת רק תומ\"י כשיזכור שהקב\"ה עומד עליו כו' מיד יגיע אליו היראה<sup data-n=\"2255\">56</sup> וכן האה', אבל מי שיש לו",[["2245","46","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["2246","47","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח. ראה לקו\"ת שה\"ש יז, ג."],["2247","48","<b>אבל עדיין. . אבל</b>: א: כמו למטה באדם הלא השכל כולל ג\"ד יודע ומדע וידוע והרי מן השכל נתהוה דבר חדש שלא הי' קודם בהשכל דהיינו שנצטייר דבר הידוע במוחו רק למטה אין השכל גורם התהוות דבר הידוע, אדרבה דבר הידוע הוא סיבת המדע שע\"י שיש דבר הידוע בעולם וחכ' מע\"ב שישנו בכל דבר כו' [הנברא — אולי מיותר ] כלולה בנפש האדם ע\"כ אפשר לו לידע ולצייר את הידוע, אבל למעלה אינו כן כי היודע והמדע הוא סיבת הידוע וע\"כ נתהווה אבל באופן שיהי' נק' בשם ידוע אבל לא בשם זולת ומכש\"כ בשם נפרד, אדרבה הוא בטל ונכלל בכח היודע והמדע בתכלית הביטול והתכללות כמשל אותיות השכל בתוך השכל ואח\"כ."],["2248","49","<b>כו'</b>: שם: לא כו')."],["2249","50","<b>רק</b>: שם: (רק."],["2250","51","<b>מדת המל'. . כאלו הם נפרדים</b>: ראה לקו\"ת שה\"ש מג, ג. לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב ובהערה *36."],["2251","52","<b>הרים שהם מדות</b>: ראה זהר סבא משפטים קט, ב ובמפרשים שם. תו\"ח שמות ח\"א יד, ד הערה 642."],["2252","53","<b>לא כאברהם שקראו הר</b>: ראה רש\"י ויצא כח, יז. פסחים פח, א. תו\"ח וארא ח\"א עז, סע\"ג ואילך. וש\"נ."],["2253","54","<b>ואברהם הוא מדת החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["2254","55","<b>הבינה נק' אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אם הבנים. לקו\"ת שמ\"ע פח, ד. שעה\"י קי, ב ובהערה 19. לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב על יד הערה 108."],["2255","56","<b>תומ\"י כשיזכור. . יגיע אליו היראה</b>: ראה שו\"ע אדה\"ז מהדו\"ת ס\"א, ס\"ה."]]],[4801940379,"טמטום הלב צריך יגיעת המוח והתבוננות שעה גדולה עד שיוליד ממילא מחדש את המדות.\n<b>ועוד</b> זאת יתבאר בענין תשו' שקדמה לעולם שצריך שיהי' ההתבוננו'<sup data-n=\"2256\">57</sup> בבחי' אני הוי' לא שניתי<sup data-n=\"2257\">58</sup> דהיינו בבחי' ומדריגה שלמעלה ממקור העולמות, דהנה המדות בחיצוניותם נגררים אחר השכל שמה שהשכל מכיר שהוא חיי נפשו נמשך אח\"ז, כמו שאנו רואים במדות דנה\"ט שנגררי' ג\"כ אחר המוחין, שהרי אפי' בבע\"ח המדות שלהם נגררים אחר כח המדמה שלהם ולכן בורח מן דבר המזיק ונמשך אחר דבר המצוייר לו שהוא חיי נפשו כמו המזון רק שאין להם שכל המברר את כח המדמה ולכן יוכלו להובילו לטבח ע\"י המזון, כי אין לו שכל לברר בין מה שהוא באמת חיים או חיים מדומין, וכ\"ה גם בנפש הטבעי' שמי שהעוורון של כח המדמה מגביר עליו נדמה לו מציאת היש של העולם שהוא החיים והטוב ונמשך אחריו, ובורח מן ההפסד החיים המדומה הזה, אבל כשמגביר כח השכל של הנה\"א ומתלבש בשכל של הנה\"ט להעביר את העוורון דכח המדמה ורואה שכל החיים המדומה אינו אלא מות ורע כי כל מציאת היש הוא הוה ונפסד (ואין ההפסד שלו בפ\"א רק שהוא מתקרב בכל שעה אל ההפסד נמצא חיותו הוא הפסדו), ומה הוא החיים האמיתי' אין זה כ\"א כח אלקי המחי' כמאמר ואולם חי אני<sup data-n=\"2258\">59</sup> כו' כי הוא חייך<sup data-n=\"2259\">60</sup> כו'<sup data-n=\"2260\">61</sup>, וע\"ז נאמר ובחרת בחיים<sup data-n=\"2261\">62</sup>, ומאחר שנצטייר ונתאמת במוחו שתכלית החיים והטוב הוא אלקות ממילא נגררו המדות אח\"ז כמ\"ש לאהבה את ה' כי הוא חייך, ומחמת שא\"א לדבקה בו כ\"א ע\"י תומ\"צ ממילא רודף אחר התומ\"צ כמו שרודף האדם אחר המזון או אחר ריוח הממון מחמת שהוא כלי לחיי נפשו<sup data-n=\"2262\">63</sup>.\n<b>נמצא</b> שכשם שאנו רואים בנה\"ט הרודף אחר ההרווחה וכדומה הלא לא יצטרך להתבונן בכל שעה ולעורר א\"ע לזה איך שהוא כלי לחיי נפשו עד שיעורר את לבו להתפעל ולהזדרז לזה, כי מספיק לו הכרה הכללית המצויירת בשכלו שכל ענינים הגשמיי' הוא כלי לחיי נפשו, כן בנה\"א מי שמאירים אצלו המדות דנה\"א לא יצטרך להתבונן בהעמקת הדעת לזרז א\"ע לעשות מצות, כי הכרה הכללי' שהתומ\"צ הם אמיתי' החיות שלו שהוא כלי לא\"ס שהוא חיי החיים<sup data-n=\"2263\">64</sup> כנ\"ל, הי' מספיק לו לעורר את המדות שבלב ולהיות זריז במ\"ע, אבל מאחר שעבר על מ\"ע נמצא שלא נתאמת במוחו בדרך הכרה כללי' שתכלית החיים והטוב הוא אלקו' באופן שיומשכו המדות שבלב אחר הכרת השכל (והגם שהמוחי' לא נפגמו אצלו, והראי' שלא עבר על ל\"ת כנ\"ל אבל הם מרוממי' עדיין בדרך אור המאיר לעצמו ולא שיתלבשו בתוך",[["2256","57","<b>שעה גדולה. . ההתבוננו'</b>: א: ליתא. וכנראה נשמט מפני תיבות הדומות: והתבוננות. . ההתבוננו'."],["2257","58","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["2258","59","<b>ואולם חי אני</b>: שלח יד, כא."],["2259","60","<b>כי הוא חייך</b>: נצבים ל, כ."],["2260","61","<b>ואולם. . כו'</b>: א: כי הוא חייך כו' ואולם חי אני כו'."],["2261","62","<b>ובחרת בחיים</b>: נצבים ל, יט."],["2262","63","<b>נפשו</b>: א ניתוסף: וא\"א להשיג ריוח מבלעדו זה."],["2263","64","<b>חיי החיים</b>: יומא עא, א."]]],[4801940423,"המדות להעירם ולהאירם<sup data-n=\"2264\">65</sup>), ולכן עצתו הוא תשובה שקדמה לעולם, דהנה בכדי להפוך לבו מן הקצה אל הקצה בשעה א' דהיינו שיתחיל להרגיש חיות במה שלא הרגיש עד עתה אחר שמדותיו פגומין, הוא דבר קשה, ורק עצתו שיתבונן בהעמקת הדעת ברוממות הא\"ס איך שהוא מופשט ומושלל מערך מקור העולמות עד שכללות חיי העולמות אינם נחשבים אצלו לגמרי, שאז עי\"ז יוכל לפעול בעצמו שיעשה המצות בזירוז גדול הגם שאין לו שום חיות בזה עדיין, וזהו תיקונו כמו במעיין נרפש ומקור משחת שהתקנה הוא לחפור בעומק יותר ועי\"ז יתמלא המעיין, ולכן א' עבר על מ\"ע ושב אינו זז משם עד שמוחלים לו כנ\"ל, כי גם למעלה ע\"י שהוא מעורר בחי' בינה עילאה יתוקן הפגם שפגם במדות עליונות ע\"י העדר מ\"ע כנ\"ל.\nד) <b>עבר</b> על מל\"ת ושב תשובה תולה ויוהכ\"פ מכפר, כי מחמת שלא הי' מוח שליט על הלב, נפעל שיש לו טמטום המוח<sup data-n=\"2265\">66</sup>, אין מספיק לו תשו' שהוא בינה, כי כמו מי שיש לו טמטום המוח לא יוכל להעמיק דעתו שעה גדולה כי מטמטמין אותו ומטרידין אותו במח\"ז, וגם אם יתחזק ויגרש את המח\"ז אבל לא יתאמת במוחו כ\"כ אמיתי' אחדות אלקות שיודבק היטיב במוחו רק בדרך מח' קרה כמו שחושב בדבר זר שאין נוגע לעצמו וזהו עונש מלמעלה. לכן א' ע\"ז שתקנתו הוא יוהכ\"פ, כי הנה בסידור איתא (בשם המגיד זי\"ע) שיום כפורים<sup data-n=\"2266\">67</sup> פי' כמו פורים, והיינו שכמו בפורים<sup data-n=\"2267\">68</sup> כ' הפיל פור הוא הגורל<sup data-n=\"2268\">69</sup> כן ביוהכ\"פ ונתן אהרן על שני השעירים גורלות<sup data-n=\"2269\">70</sup>, וצריך להבין ענין הדמיון גורל דכה\"ג לגורל דהמן, וכן גם בענין גורל דכה\"ג גופא צ\"ל מפני מה נשתנה יום זה דיוהכ\"פ דוקא שבו הי' צריך להיות גורל על עצם הקרבן משא\"כ בכל השנה (הגם שהיו פייסות בכל יום<sup data-n=\"2270\">71</sup> הוא רק מי שיזכה להקריב אבל לא בגוף הקרבן), וגם צ\"ל מארז\"ל שני השעירים מצותן שיהיו שוין בקומה ובמראה<sup data-n=\"2271\">72</sup> כו'. והלא גורל א' לה' וגורל אחד לעזאזל הוא ע\"ש לשעירים כמ\"ש בא\"ע<sup data-n=\"2272\">73</sup> וכמבואר בזוה\"ק שהוא ליתן חלק לסט\"א<sup data-n=\"2273\">74</sup>, ומהו ענין ההשתוות הזאת הלא רחוקים הם מאד זמ\"ז מן הקצה אל הקצה. ולהבין כ\"ז צ\"ל",[["2264","65","<b>ולהאירם)</b>: א: ולהאירם, ולכן אינם רק שליטים על המדות מרחוק כדרך השליט אבל לא מתלבשים בדרך אור לכלי או שלא התבונן א\"ע במקור המחי' של העולמות וידיעתו רק רוממות הא\"ס)."],["2265","66","<b>טמטום המוח</b>: ראה גם לעיל מאמר ד\"ה הנה להבין המדרש והצרוע תקצ\"ט על יד הערה 38. תו\"ח שמות ח\"א ב, ב. וש\"נ."],["2266","67","<b>בסידור. . בשם המגיד. . שיום כפורים. . פורים</b>: ראה סידור שער הפורים רפג, סע\"ב ואילך (ולא נזכר שם הה\"מ). ראה גם הנסמן בשערי אורה צו, ב הערה 21. מאמר ד\"ה ע\"כ קראו לימים האלו פורים תשי\"ג (קונט' פורים תנש\"א — סה\"מ מלוקט ח\"ה ע' קפט ואילך ובהערה 9)."],["2267","68","<b>והיינו שכמו בפורים</b>: א: וצריך להבין ההשתות בזה שאו' ע\"ז כמו שבפורים."],["2268","69","<b>הפיל פור הוא הגורל</b>: אסתר ג, ז."],["2269","70","<b>ונתן אהרן על שני השעירים גורלות</b>: אחרי טז, ח."],["2270","71","<b>שהיו פייסות בכ\"י</b>: ראה יומא כב, א. כה, א ואילך."],["2271","72","<b>שני השעירים. . בקומה ובמראה</b>: ראה יומא סב, א. ראה גם הנחה ד\"ה תכון תפילתי קטורת לפניך תר\"ם קרוב לסופה."],["2272","73","<b>כמ\"ש בא\"ע</b>: אחרי טז, ח. וראה רמב\"ן שם."],["2273","74","<b>וכמבואר בזוה\"ק. . חלק לסט\"א</b>: ראה זהר תצוה קפד, ב ואילך. פקודי רלז, ב. רע\"מ אחרי סג, א. אמור קא, ב. קב, א."]]],[4801940463,"בענין פורים מארז\"ל חייב אינש לבסומי בפוריא<sup data-n=\"2274\">75</sup> עד דלא ידע בין ארור המן לברוך מרדכי, וזה פלא גדול, הלא כל עיקר שמחת פורים בשביל הנס, ואיך חייבו חכמים לבסומי עד שישכח כל עיקר הנס, ומה תועלת יש בבלבול השכל, וגם מ\"ש המפרשים<sup data-n=\"2275\">76</sup> שלא יוכל לחשוב<sup data-n=\"2276\">77</sup> הגימט' בין ארור המן לברוך מרדכי, ג\"כ אינו מובן כיון שחושבני' דדין כחושבנא דדין, מהו לחשוב, והנה מספר שנות האבות הם תק\"ב כנ\"ל כמספר ברוך מרדכי או ארור המן.\n<b>והנה</b> להבין כל הנ\"ל צריך להבין ענין הגורל בעבודת ה', דהנה כתיב ישמחו השמים ותגל הארץ<sup data-n=\"2277\">78</sup>, ומרומז בר\"ת שם הוי', י'שמחו ה'שמים מרומז אותיות י\"ה שהו\"ע חו\"ב, ו'תגל ה'ארץ מרומז אותיות ו\"ה שהוא מדות ומל', כי המוחין נק' מקיפים והמדות ומל' פנימי', כי כמו שהשמים מקיפים את הארץ וכל מה שבארץ כל פרטי דצח\"מ יש להם שרש ומקור בשמים כמאמר אין לך עשב<sup data-n=\"2278\">79</sup> כו' רק שבשמים הם בהעלם ובדרך כלל, הגם שכל צמח יש לו מזל מיוחד עכ\"ז אינם מחולקים ומפורדים כמו למטה בגשמי' והארץ היא מוציאם מההעלם אל הגילוי ומחלקם לפרטים מחולקים וכן המוחין לגבי המדות, דהנה שרש המדות ישנם בשכל כמו מדות שבשכל רק ששם אינם מורגשים עדיין למהות מדה כמו בלב, והראי' שסברא אחת המטה כלפי דין תוכל להתהפך כלפי חסד, כידוע ע\"פ כי יצר לב האדם<sup data-n=\"2279\">80</sup> כו', שקודם המבול היתה מטה סברא זאת כלפי דין כו', ואח\"כ וירח ה' כו' ויאמר לא אוסיף<sup data-n=\"2280\">81</sup> לקלל כו' ג\"כ מטעם כי יצר לב האדם כו' ובפרט במדת המל' ששם נעשו נגלים ומחולקים בפועל ממש, ולכן המדות ומל' שהוא ו\"ה מרומז בתיבות ותגל הארץ והמוחין מרומזים בתיבות ישמחו השמים, ולכן ארז\"ל שמן הארץ עד לרקיע<sup data-n=\"2281\">82</sup> מהלך ת\"ק שנה, כי הנה ע\"ס הם חמש כנגד חמש כדאיתא בס\"י<sup data-n=\"2282\">83</sup> וכ\"א כלול מעשר ועשר מעשר, וזהו שמן המל' עד החכ' יש ת\"ק מדריגות, ולכן שנות האבות הם כימי השמים על הארץ, כי כל עבודת האבות הי' להוסיף אורות בע\"ס דאצי', ולכן הי' ג' אבות כנגד ג' קוין, ואברהם הי' מרכבה לקו הימין חח\"ן שהוא עמוד גמ\"ח כמ\"ש בס' הבהיר אמרה מדת החסד<sup data-n=\"2283\">84</sup> כו', ויצחק מרכבה לקו השמאל בג\"ה שהוא עמוד העבודה ולכן הי' עולה, ויעקב מרכבה לקו האמצעי דת\"י שהוא עמוד התורה כמ\"ש ויקם עדות כו' ותו' שם בישראל<sup data-n=\"2284\">85</sup>, ולכן חיו",[["2274","75","<b>חייב אינש לבסומי בפוריא</b>: ראה מגילה ז, ב. לקו\"ש ויקרא כרך ז ע' 20 הערה 2."],["2275","76","<b>וגם מ\"ש המפרשים</b>: א: והנה המפרשים שהביא המ\"א ובה\"ג [ ובאר הגולה] ביארו שהפי'."],["2276","77","<b>שלא יוכל לחשוב</b>: ראה מג\"א סתרצ\"ה, ס\"ג. לקו\"ש ויקרא שם ע' 21 הערה 11."],["2277","78","<b>ישמחו השמים ותגל הארץ</b>: תהלים צו, יא. דהי\"א טז, לא. ת\"ז בהקדמה ט, ב. בעל הטורים בראשית א, לא. ב, א."],["2278","79","<b>אין לך עשב</b>: ראה ב\"ר פ\"י, ו. מאמרי אדה\"א דברים ח\"ג ע' תתמח. וש\"נ. שם ע' תתעו ואילך. שער האמונה ע' נג. אוה\"ת וארא כרך ח ע' ב'תתפג."],["2279","80","<b>כי יצר לב האדם</b>: נח ח, כא. ראה גם לקמן ביאור מאמר ד\"ה והניף הכהן אותם ובהערה 54."],["2280","81","<b>וירח. . ויאמר לא אוסיף</b>: התחלת הכתוב [בדילוג] כי יצר לב האדם."],["2281","82","<b>שמן הארץ עד לרקיע</b>: חגיגה יג, א."],["2282","83","<b>ע\"ס הם חמש כנגד חמש כדאיתא בס\"י</b>: פ\"א, מ\"ג."],["2283","84","<b>בס' הבהיר אמרה מדת החסד</b>: סקצ\"א. וראה לעיל הערה 54."],["2284","85","<b>ויקם עדות. . בישראל</b>: תהלים עח, ה."]]],[4801940498,"ת\"ק שנים (לבד הב' שנים קודם שהכיר) כי בכל שנה המשיכו תוס' אורות בבחי' ומדריגה א' מת\"ק מדריגות שמן החכ' עד המל' כנ\"ל. והנה בבחי' זו יש לעו\"ז כי כמו שיש שמים וארץ בקדושה כן יש שמים וארץ בלעו\"ז כמ\"ש כי שמים כעשן נמלחו והארץ כו' דמפרש בת\"ז<sup data-n=\"2285\">86</sup> דקאי על ס\"מ ובת זוגי', כי כמו שיש ע\"ס בקדושה כן יש עשר כתרין דמסאבותא<sup data-n=\"2286\">87</sup> ונחלקים ג\"כ בכלל למוחין ומדות שהם שמים וארץ, ובפרט לג' קוין ובפרטי פרטיות לת\"ק מדריגות שמן הארץ עד לרקיע.\n<b>והנה</b> בקדושה נק' מדריגות* הללו בשם ברוך מרדכי שהוא בגימט' תק\"ב עם ב' מדריגות שקודם שהכיר (שהוא ענין חי' ויחידה כנ\"ל), כי כל ההמשכות שניתוסף אורות בע\"ס ע\"י מעשה המצות שע\"י שמירת ל\"ת ממשיכים בחי' י\"ה וע\"י מ\"ע בחי' ו\"ה הם נמשכים ע\"י החכמה שהוא בחי' מרדכי כדמתרגמינן מירא דכיא<sup data-n=\"2287\">88</sup>, ובלעו\"ז כל הת\"ק מדריגות נק' בשם ארור המן כי כללות הכתרין נק' ארורים כידוע, והמן הוא בחי' חכ' דקליפה שהוא תכלית הגסות, לנגד בחי' חכ' דקדושה שהוא תכלית הביטול, ולכן ע\"י פגם מל\"ת נעשה תוס' יניקה במוחי' דלעו\"ז וע\"י העדר מ\"ע במדות דלעו\"ז, והנה עז\"נ והיתה נפש אדוני צרורה<sup data-n=\"2288\">89</sup> בצרור החיים את הוי', שע\"י מ\"ע ומל\"ת שמזכך שם הוי' שבנפשו מעורר עי\"ז ג\"כ שם הוי' למעלה שהוא בחי' ע\"ס כנ\"ל, ונפש אויביך ע\"י פגמיו בעשה ול\"ת יקלענה כו', אבל למעלה מע\"ס שם אין שום מנגד בלעו\"ז.\n<b>כי</b> הנה כתי' והי' על מצחו תמיד לרצון<sup data-n=\"2289\">90</sup> כו', ופי' בשל\"ה<sup data-n=\"2290\">91</sup> המרוצה תמיד בכל פעם, והכוונה שאין שם נגד הרצון, כי הנה אנו רואים שהרצון הוא המנהיג באדם ושליט על כל כחותיו רק שהרצון הפרטי יש כנגדו שלילת הרצון לפ\"ע תוקף הרצון בדבר פרטי לפ\"ע זה הוא המיאון וסלידת הרצון<sup data-n=\"2291\">92</sup> לאחוריו מדבר שהוא נגד רצונו, ולכן אנו רואים שהרצון באדם הנמדד ע\"פ השכל הוא מוגבל הן מצד המשפיע, הן מצד המקבל, דהיינו לבד מה שישלם לעושי רצונו ויעניש לעוברי רצונו, הנה בעושי רצונו גופא יש הבדל בהשכר עבור מילוי הרצון לפ\"ע תוקף הרצון שיש לו בהדבר, וכן בעונש לפ\"ע תוקף שכנגד הרצון, ולכן כל הנהגות האדם מוגבלים הן מצד המשפיע לוותר לפי כחו ויכולתו, והן מצד המקבל לפ\"ע פעולת המקבל וזיכוכו, והנה כ\"ז הוא כשמתנהג ע\"פ רצון הפרטי המלובש בתוך השכל ונגבל ע\"פ השכל שמדדו, אבל כשמאיר באדם הרצון פשוט כמו בעת שמחת בנו יחידו, אזי יסולקו כל המדידות וההגבלות עד שיוותר יותר מכפי כחו ויכולתו, וגם",[["2285","86","<b>כי שמים כעשן. . בת\"ז</b>: ישעי' נא, ו. ת\"ז סת\"ח."],["2286","87","<b>עשר כתרין דמסאבותא</b>: ראה זהר סבא משפטים צד, ב. שמיני מא, ב. אחרי ע, א. אד\"ר נשא קמג, סע\"א ורע\"ב.\n88)* מדריגות: א: ת\"ק מדריגות."],["2287","88","<b>מרדכי כדמתרגמינן מירא דכיא</b>: ראה חולין קלט, ב."],["2288","89","<b>והיתה נפש אדוני צרורה</b>: שמו\"א כה, כט."],["2289","90","<b>והי' על מצחו תמיד לרצון</b>: תצוה כח, לח."],["2290","91","<b>ופי' בשל\"ה</b>: ראה דעת ר\"ש יומא ז, ב. רש\"י תצוה שם."],["2291","92","<b>וסלידת הרצון</b>: א: וסליקת הרצון הנפש."]]],[4801940530,"למי שאינו ראוי והגון, ולכן יוכל לקרב ולעשות שלום גם עם השונא שע\"פ שכלו לא הי' מתקרב עמו בשום אופן, וזה נק' עת רצון, כי בשעה שהמלך מלובש באיזה רצון פרטי אז אין השעה מוכשרת לבקש ממנו שום דבר, כי זהו בלבול ונגד לרצונו, ורק עת רצון נק' בשעה שהוא פנוי מכל הרצונות הפרטים (בל\"א ער<sup data-n=\"2292\">93</sup> איז און גוטין ווילין), ואז הוא עלול להשפעת כל טוב לכל מי שידרוש ממנו, וכמארז\"ל חזי' דהוה קא בדח טובא ואי הוו שאלי מיני' כל חללי דעלמא<sup data-n=\"2293\">94</sup> כו', שהוא נק' בלשון הקבלה רעדכ\"ר<sup data-n=\"2294\">95</sup> שהוא רצון של כל הרצונות, והיינו עדיין קודם שנגבל לפרטי רצונות, דאלו אחר שנגבל כשישאל ממנו שום שכל אז יהי' מוגבל רצונו להשפעה זאת, ויהי' גם שכל אחר מותר<sup data-n=\"2295\">96</sup> ומבלבל לזה, כמ\"ש כי קאי רבי בהא מסכת<sup data-n=\"2296\">97</sup> לא תשיילי' במס' אחריתא, רק מחמת שמאיר אצלו רצה\"פ הנה אח\"כ כשיסיים שכל זה מלגלות ישוב לפשיטות אורו ויוכל שוב להמשיך לשכליות אחרים או לשארי השפעות כנ\"ל.\nה) <b>והנה</b> כמו שאנו רואים בנפש האדם כ\"ה למעלה כי כ\"ז שהנהגת העולמות הוא ע\"פ רצה\"ע המלובש בחכמה שבתורה, אז שייך שכר לעושי רצונו ועונש כו', וכמ\"ש והיתה נפש אדוני צרורה כו', וכן בעושי רצונו גופא יש חילוק בין שמירת ל\"ת ובין קיום מ\"ע כנ\"ל ובמ\"ע גופא יש חילוקי מדריגות, וכן יש חילוק בהשכר לפ\"ע היגיעה כמארז\"ל<sup data-n=\"2297\">98</sup> לפום צערא אגרא<sup data-n=\"2298\">99</sup>, אבל כשמאיר מלמעלה בחי' רצה\"פ שהוא בחי' רעדכ\"ר משם יוכל להיות נמשך סליחת עוונות כמ\"ש ונשא אהרן<sup data-n=\"2299\">100</sup> וכנ\"ל במשל האדם, ולכן כתיב אם חטאת מה תפעל בו<sup data-n=\"2300\">101</sup> כו' ואם צדקת<sup data-n=\"2301\">102</sup> כו'<sup data-n=\"2302\">103</sup>, אבל איך ממשיכים בחי' רעדכ\"ר שיומשך ויתגלה בעולמות מאחר שרצונו העצמי הי' שיהי' הנהגת העולמות ע\"פ הרצון הפרטי המלובש בח\"ע דתו' וע\"פ מדותיו ית', כמאמר אנת הוא דאפיקת כו' לאחזאה ולאנהגא בהון דוקא עלמין, ובחי' רעדכ\"ר הוא דבוק ונעלם בעצמות אא\"ס ואינו מאיר בגילוי בעולמות, דאל\"כ לא הי' שכר ועונש מאחר שמעשה התחתונים אין תופסים מקום שם (דבשלמא באדם התחתון הגם שגם בו אין מאיר בתמידות כחות הפשוטים כמו תענוג הפשוט ורצון הפשוט מצד שהם דבוקים ונעלמים בעצמי' הנפש, דאל\"כ לא הי' מרגיש לעולם שום צער מדבר הפרטי שמנגד לרצון הפרטי כי הי' התענוג מעצמו' נפשו מכריע כי די שהוא חי, אך מ\"מ יש ענינים וסיבות שמעוררים את עצם הנפש לבא<sup data-n=\"2303\">104</sup> לידי גילוי",[["2292","93","<b>ער. . און</b>: שם: אז ער. . אין."],["2293","94","<b>חזי' דהוה. . חללי דעלמא</b>: ראה שבת עז, ב. לעיל ע' עו. וש\"נ."],["2294","95","<b>רעדכ\"ר</b>: ראה זהר ספדצ\"נ תרומה קעו, ב. תו\"ח בראשית לו, ג הערה 23. תצוה ח\"ב שעו, ג."],["2295","96","<b>מותר</b>: א: סותר."],["2296","97","<b>כי קאי רבי בהא מסכתא</b>: ראה שבת ג, רע\"ב."],["2297","98","<b>יש חילוק. . כמארז\"ל</b>: א: בין ג' דברים שהעולם עומד עליהם וכן בפרט בפרטי המצות שהשכר לפי ענין היגיעה כמ\"ש."],["2298","99","<b>לפום צערא אגרא</b>: אבות ספ\"ה. ולפי גי' אדה\"ז בסידורו מכ\"א."],["2299","100","<b>ונשא אהרן</b>: תצוה כח, לח."],["2300","101","<b>אם חטאת מה תפעל בו</b>: איוב לה, ו."],["2301","102","<b>ואם צדקת</b>: איוב שם, ז [ושם: אם — ראה לקמן מאמר ד\"ה והתהלכתי תרט\"ו ובהערה 17]."],["2302","103","<b>אם חטאת. . כו'</b>: א: אם צדקת."],["2303","104","<b>אך מ\"מ. . לבא</b>: שם: ובפרט שאנו רואים שכל ומדות האדם מדודים ומוגבלים ע\"פ השכל והיינו מחמת שהוא בדוגמא ש\"מ כנ\"ל שהוא אמיתית הטעם על הצטיירות כוחות הנפש הנגבלים והנעלמים ולמעלה היה רצון העצמות כן כנ\"ל על מא' אנת הוא דאפיקת כו' כדי ליתן מקום למעה\"ת שיהיה שכר ועונש מ\"מ לא קשה מי הוא המעורר את כוחות הפשוטים להביאם."]]],[4801940557,"אור כמו בשמחת בנו יחידו, או כשניצול מן הסכנה וכדומה, או שמזכין אותו מלמעלה בשמחה של מצוה כמו לא הוה פסק חוכא מפומי'<sup data-n=\"2304\">105</sup> כו', אבל למעלה אינו מובן מאחר שנתינת עצמותו הי' באופן שלא יתגלה בעולמות רק רצון הפרטי המלובש בע\"ס, איך ובמה פועלים שיאיר בחי' רעדכ\"ר).\n<b>אך</b> הנה ע\"ז נאמר גם את העולם נתן בלבו של אדם<sup data-n=\"2305\">106</sup>, שע\"י שהאדם מעורר בעצמו כחות הנעלמים והפשוטים יעורר למעלה ג\"כ בחי' רצה\"פ שיאיר בעולמות ומשם יומשך סליחת עוונות, ולזה צוה השי\"ת שביום המיוחד לסליחת עוונות יפיל הכה\"ג גורל על הקרבן, דהנה הגורל בנפש האדם הוא נתינת עצמותו למעלה מן הטו\"ד, רק התעוררות רצון הפשוט, דהלא בדבר שהשכל מחייב לעשות באופן זה דוקא, או שהמדות שבלב מטין לצד א' דוקא לא יפיל הגורל, אם לא בדבר שהוא מסופק ואין לו שום הכרע לא בשכלו ולא במדותיו איך לבחור, אז מטיל הגורל, והרי בשעה שיוטל הגורל יש לו רצון פשוט בהשתוות על שני הצדדים דבר והיפוכו בהשוואה, והוא נותן א\"ע שכשם שיצא ע\"פ הגורל כן יטה רצונו בהחלט, נמצא שהטלת הגורל הוא התעוררות רצה\"פ ונתינת עצמותו למעלה מן הטו\"ד, ובפרט שהגורל של כה\"ג הי' נוגע לחיות הכללי של נש\"י ברוחניות וגשמיות, כי אם הי' הגורל של שם עולה בשמאל ח\"ו הוא סימן רע ח\"ו, וכמארז\"ל שבמ' שנים האחרונים<sup data-n=\"2306\">107</sup> הי' עולה גורל של שם בשמאל כו' ואמרו מקדש מקדש יודעים אנו בך שסופך ליחרב, משא\"כ בכל השנים הי' גורל של שם עולה בימין<sup data-n=\"2307\">108</sup>, ועכ\"ז לא הי' רשאי הכה\"ג ליטול בבחירתו הגורל של שם בימין, או איזה תחבולה בכדי שיעלה הגורל של שם בימין רק אדרבה טרף בקלפי<sup data-n=\"2308\">109</sup> והעלה ב' גורלות כו', נמצא שהי' מבטל רצונו לגמרי ומעורר בנפשו רצה\"פ שיהי' שוה אצלו חיות של כללות נש\"י והיפוכו ח\"ו בהשוואה ע\"ד אם כה יאמר לא חפצתי<sup data-n=\"2309\">110</sup> כו', והוא הי' שלוחן של כל ישראל כמאמר קהל עדתנו עליך יסמוכו<sup data-n=\"2310\">111</sup>, נמצא שכשם שע\"י הגורל הי' מוצא בנפשו רצה\"פ ע\"ד מס\"נ ממש, כן הי' מעורר אצל כל ישראל המצפים לסליחה ג\"כ רצה\"פ ומס\"נ כזה, ולכן עי\"ז מעוררים למעלה ג\"כ בחי' רצה\"פ רעדכ\"ר ששם אין מעשה התחתונים תופס מקום כלל, וכחשיכה כאורה<sup data-n=\"2311\">112</sup> ממש, ולכן מצותן שיהיו שוין כו' לרמז על בחי' זאת שלהוי' שהוא ע\"ס דקדושה ולעזאזל שהוא עשר כתרין דמסאבותא שוין ממש.",[["2304","105","<b>לא הוה פסק חוכא מפומי'</b>: ראה ברכות ט, ב."],["2305","106","<b>גם את העולם נתן בלבו של אדם</b>: קהלת ג, יא [ושם: בלבם]."],["2306","107","<b>שבמ' שנים האחרונים</b>: ראה יומא לט, ב."],["2307","108","<b>בימין</b>: א ניתוסף: וידוע שלא למגנא איתעביד ניסא מחמת שזה היה נוגע לחיים של כו'."],["2308","109","<b>טרף בקלפי</b>: יומא לט, א."],["2309","110","<b>אם כה יאמר לא חפצתי</b>: שמו\"ב טו, כב [ושם: ואם — ראה מאמרי אדה\"א קונטרסים ע' קמז]."],["2310","111","<b>קהל עדתנו עליך יסמוכו</b>: תכנת כל אלה (סדר עבודה ליוכ\"פ)."],["2311","112","<b>וכחשיכה כאורה</b>: תהלים קלט, יב. ראה לקו\"ת צו יב, א. סידור סדר הגדה רצז, רע\"ד. עט\"ר דרוש לעשי\"ת ע' נא. סה\"מ תרכ\"ז ע' תצד."]]],[4801940575,"ולכן מצינו בהמן שהגביה א\"ע כנשר שדרך הנשר בשמים<sup data-n=\"2312\">113</sup> לקבל דוקא מבחי' רוממות הא\"ס שלמעלה מהתלבשות בע\"ס ושם<sup data-n=\"2313\">114</sup> כחשיכה כאורה שוין כדי שיוכל למשול על ישראל, ולכן כדי לעורר למעלה בחי' זו עשה דוגמת הכה\"ג ביוהכ\"פ והפיל פור הוא הגורל לפני המן, היינו למעלה ממדריגת המן מן התורה<sup data-n=\"2314\">115</sup> שהוא חכ' דקליפה, והוא רצה לעורר בחי' כתר וגם פעל כן, ולכן יצאה הגזירה ונחתם הגז\"ד, אך מחמת שהגזירה יצאה על המכונה בשם יהודי, והם מסרו נפשם בפועל עי\"ז התעורר בנפשם נקודת עצם היחידה (ולכן בכל מגילת אסתר נק' בשם יהודים ע\"ש נקודת יהדות שלהם), שהוא בחי' עתיקא דעתיקין<sup data-n=\"2315\">116</sup> שלמעלה מבחי' רעדכ\"ר, עי\"ז פעלו שיהי' ונהפוך הוא<sup data-n=\"2316\">117</sup> כו' ומשם דוקא אורידך<sup data-n=\"2317\">118</sup> כו', דהנה לכאורה אינו מובן מאחר שע\"י שנהנו מסעודת אחשורוש<sup data-n=\"2318\">119</sup> עי\"ז נחתם הגז\"ד, הגם שנמחל להם החטא ע\"י תשובה ותענית, אבל מאין נמשך להם הכח שישלטו בשונאיהם, אך הענין הוא כמו שמצינו בחותם דנעילה שלאחר עבודת היום מתפלל תפלת נעילה והוא זמן חתימה כמו שאנו מבקשים חתמינו כו'. ולהבין ענין נעילה וחתימה, אך הנה ידוע שמאחר שע\"י גורל הכה\"ג מעוררים למעלה בחי' רעדכ\"ר כנ\"ל ומשם יומשך הסליחה מחמת ששם כחשיכה כאורה כנ\"ל, הנה לפ\"ז יוכל לימשך ג\"כ יניקת החיצוני' מטעם זה ששם הכל שוין כמאמ' מצותן שיהיו שוין כנ\"ל, לכן צריך אח\"כ להתפלל תפלת נעילה לנעול ולחתום ההשפעה שיהי' נמשך דוקא לישראל ולא לע' שרים<sup data-n=\"2319\">120</sup>, והוא כמשל החותם שעל האגרת שלא יקראנה זר, אפי' השליח אינו יודע מה שכתוב בו רק מי שנשתלח אליו, כ\"ה ענין הנעילה ואפי' בזה\"ג שההשפעה הוא על ידי מעבר ע' שרים<sup data-n=\"2320\">121</sup> מ\"מ לא יגיע פנימי' ההשפעה רק לישראל לבדם כמ\"ש יבחר לנו את נחלתנו (וכמבואר בסידור שער יוהכ\"פ<sup data-n=\"2321\">122</sup> ).\n<b>אך</b> באמת אינו מובן זה גופא דממ\"נ אם מאיר מלמעלה בחי' רעדכ\"ר ששם כחשיכה כאורה עד שעי\"ז נמשך הסליחה כענין נושא עון מחמת ששם אין תופס מקום מעשה התחתונים והוא בחי' א\"א שמאריך אף אף לעוברי רצונו, איך יוגבל ההשפעה לישראל דוקא מאחר ששם הכל שוין ממש כנ\"ל בענין מצותן שיהיו שוין, ואם שיוגבל ההשפעה ע\"פ חכ' דוקא ולכן יומדד שיהי' לישראל דוקא, א\"כ",[["2312","113","<b>שדרך הנשר בשמים</b>: משלי ל, יט. ראה גם לקמן מאמר ד\"ה וספרתם תרי\"ב על יד הערה 67."],["2313","114","<b>ושם</b>: א: כי לא הספיק א\"ע מהיניקה שיש לו ע\"כ (ע\"י ) חטאים ועוונות בנ\"י ח\"ו, שעל ידי פגם דל\"ת יומשך תוס' יניקה בהמוחין וע\"י העדר מ\"ע בהמדות כנ\"ל, כי לולא הפגם הרי התגלות (הכללות ) דע\"ס מודדים את האור עד פה תבוא ולא תוסיף רק ע\"י הפגם יוכל לינק כמבואר ע\"פ שופך דם האדם ורצה לינק מגוף שרשם."],["2314","115","<b>המן מן התורה</b>: חולין קלט, ב."],["2315","116","<b>עתיקא דעתיקין</b>: ראה זהר אד\"ר נשא קכח, א."],["2316","117","<b>ונהפוך הוא</b>: אסתר ט, א."],["2317","118","<b>ומשם. . אורידך</b>: עובדי' א, ד."],["2318","119","<b>שנהנו מסעודת אחשורוש</b>: ראה מגילה יב, א."],["2319","120","<b>לע' שרים</b>: ראה זהר בראשית מו, סע\"ב. שע\"ת עד, א הערה 2."],["2320","121","<b>בזה\"ג שההשפעה. . ע' שרים</b>: ראה אגה\"ק סכ\"ה (קלט, ב). שע\"ת ו, א ובהערה 3. מאמרי אדה\"א דברים ח\"א ע' קסד. וש\"נ."],["2321","122","<b>יבחר לנו. . בסידור שער יוהכ\"פ</b>: תהלים מז, ה. ראה סידור שם רנ, ד."]]],[4801940588,"איך יהי' נמשך סליחת עוונות, הלא ע\"פ חכ' נמשך עונש לעוברי רצונו כידוע בענין שאלו לחכ'<sup data-n=\"2322\">123</sup> כו', ולמה לישראל נמשך הויתור, שזהו לכאורה דבר<sup data-n=\"2323\">124</sup> והיפוכו שמציירים הגבול בבל\"ג. אך הענין יובן ע\"ד דוגמא במי שבדח טובא ע\"י שמחת בנו יחידו כנ\"ל והוא מוותר וסולח לשאינו ראוי ולחוטא כנ\"ל ע\"י גילוי אור הנפש הפשוט שהנפש נתמלא במילוי ולכן אז מסולקים כל המדידות וההגבלות הן מצד המשפיע והן מצד המקבל כנ\"ל, ועכ\"ז אם בשעת מעשה יעדר בן יחידו ח\"ו, הנה עי\"ז יסתלק כל מילוי אור הנפש הפשוט הגם שהוא דבר פרטי ג\"כ אבל מאחר שהוא הסיבה לכל מילוי אור הנפש בתענוג הפשוט מחמת שהוא עצם א' עמו ונוגע לעצם העלם המאור ע\"כ בהעדרו יוכל לסלק כל אור הנפש הפשוט ולהעלימו, נמצא הגם שאור הנפש הוא פשוט הוא רק שפשיטותו הוא מהגבלת כלי מוחו ולבו שאינם מגבילים אבל העונג הנעלם בעצמותו המקור לתענוג הפשוט הנגלה הגם שהוא פרטי, כחו חזק להגביל את פשיטת האור אחרי שהוא מקורו.\n<b>וכן</b> בדוגמא זו ע\"י שבתפלת נעילה שהוא זמן התשובה היותר נעלה שאז הוא העלי' לבחי' ה\"ג דעתיקא ומצד כי פנה יום שהוא גמרו של תענוג שאז נתעורר נעיצת התחלה שהוא הסיבה שהביאה לכלל תענוג הפשוט הנגלה, ועוד זאת שהוא מצד השלילה, כמו באדם בהפרדו מבנו שאז נגלה העונג העצמי שאין לו שום כלי בדרך קירוב כמו השמחה שהוא תוס' אור בכלי, רק אדרבה אז יבכה שהוא בקיעת הכלי דוקא (הגם שמתענג מהפירוד כמו בגמר החתונה) ואז ממילא יתעורר בכאו\"א מישראל נקודת עצם יהדותם שהוא ממש כמו מס\"נ בפו\"מ, ומעוררים למעלה בחי' עתיקא דעתיקין שלמעלה מבחי' רעדכ\"ר שמעוררים בתחלה ע\"י הגורל דכה\"ג, שע\"ז אמרו מחשבתן של ישראל קדמה לכל דבר, שהוא אפי' לאור השעשועים שרש התורה, ולכן ביכולתם לעשות הגבלה בבחי' אור פשוט שבלי גבול דהיינו שיהי' ההשפעה בדרך וויתור עד שיומשך סליחת עוונות ועכ\"ז דוקא לישראל מאחר שמעורר עצם העלם המאור שהוא ענין עונג הנעלם בעצמותו שהוא מנש\"י דוקא.\n<b>ועכ\"ז</b> בכל השנה ההנהגה גם עם ישראל ע\"פ ח\"ע שבתורה דוקא, ושייך שכר ועונש אע\"פ שמחשבתן של ישראל קדמה כו' ושרשן בעונג הנעלם שבעצמותו אבל רצונו העצמי הי' שלא יאירו למטה כל אורות הפשוטים כמו הרצון הפשוט ותענוג הפשוט, רק תהי' ההנהגה ע\"פ התורה דוקא, בלתי אם יעוררו נש\"י מלמטה ע\"י הגורל ומס\"נ בפועל בנעילה, כמאמר אנת הוא כו' לאחזאה ולאנהגא בהון דוקא עלמין, אבל ביוהכ\"פ שמעוררים הרצה\"פ ע\"י הגורל ועונג הנעלם ע\"י נעילה אזי נמשך הוויתור וההגבלה לישראל דוקא והוא ענין החתימה כנ\"ל, ועד\"ז הי' הנס בפורים דהגם שע\"י גורל דהמן נתעלה לינק מבחי' כמה ארך אפים שהו\"ע רצה\"פ ששם שוין הכל בהשוואה אמיתית אפי' לעזאזל כנ\"ל ולכן הי' ביכולתו לשלוט על ישראל, אבל מאחר שע\"י גזירתו נגע",[["2322","123","<b>שאלו לחכ'</b>: ירושלמי מכות פ\"ב, ה\"ו."],["2323","124","<b>מחשבתן של ישראל. . דבר</b>: ב\"ר פ\"א, ד."]]],[4801940598,"בבת עינו של הקב\"ה<sup data-n=\"2324\">125</sup>, וכנ\"י בכל משך זמן הגזירה עמדו במס\"נ<sup data-n=\"2325\">126</sup> בפועל, נתעורר עצם שרשן למעלה בעונג הנעלם המקור לכל מיני גילוי אור אפי' תענוג הפשוט ורצון הפשוט כנ\"ל בענין מחשבתן של ישראל קדמה כו' כנ\"ל ולכן נעשה ההגבלה בלתי בע\"ג, ולכן נמחל לישראל אותו עון, והי' ההשפעה בדרך ויתור, והוא נדחה לגמרי, כמאמר הכתוב משם אורידך כנ\"ל.\nוא\"ו) <b>וע\"ז</b> רמזו לנו חז\"ל חייב אינש לבסומי שהוא גילוי אור תענוג הפשוט ורצון הפשוט (הנעשה ע\"י נכנס יין יצא סוד<sup data-n=\"2326\">127</sup> ) עד דלא ידעי בין ארור המן כו', פי' ששם אין ניכר ההבדל בין ארור המן שהוא גימט' תק\"ב שהוא בעשר כתרין דמסאבותא כימי השמים על הארץ בשמים וארץ דקליפה, ובין ברוך מרדכי שהוא ג\"כ תק\"ב שבע\"ס שהוא בשמים וארץ דקדושה הנעשה ע\"י קיום מ\"ע ושמירת ל\"ת כנ\"ל בשני האבות, מאחר ששם כחשיכה כאורה שוין כנ\"ל, להורות על הפלגת הנס שאפי' מבחי' זו נמדד הוויתור לישראל דוקא והדחי' בלעו\"ז כנ\"ל. והנה לפ\"ז יתפרש ענין עד דלא ידעי ע\"ד אם לא תדע לך היפה בנשים<sup data-n=\"2327\">128</sup> שמבואר במ\"א שהיפה בנשים גימט' תק\"ב<sup data-n=\"2328\">129</sup>, דהנה יש ב' מיני יופי יפ\"ת ויפ\"מ<sup data-n=\"2329\">130</sup>, וידוע כי תואר הוא ציור האברים ומראה הוא קלסתר פנים, ובנפש* אברים הם המדות שהז\"א בעל ט\"ס וטפ\"ט עולה רמ\"ג וה\"ח המגדילים עולה רמ\"ח<sup data-n=\"2330\">131</sup>, ומראה נק' המוחין<sup data-n=\"2331\">*131</sup>*, והפסוק אם לא תדעי כו' הוא תשובה על השאלה הגידה לי<sup data-n=\"2332\">132</sup> כו' איכה תרעה איכה תרביץ ב\"פ איכה כנגד חורבן ראשון וחורבן שני, שהוא בנפש ענין טמטום הלב והמוח שאז חסר ב' מיני יופי הנ\"ל שכללות שניהם נק' היפה בנשים, ולכן הוא גימט' תק\"ב שהוא כימי השמים על הארץ שכולל שו\"א שהם מוחין ומדות כנ\"ל, וע\"ז משיב רוה\"ק ואומר אם לא תדעי לך היפה בנשים, שהעצה הוא לעורר ע\"י גורל שבנפש שהוא בחי' מס\"נ בכח, את בחי' רצון הפשוט שלמעלה ששם אין ניכר כלל כללות היופי דיפ\"ת ויפ\"מ המרומז בתיבת היפה בנשים (בל\"א וואש דארטין איז ניט קענטיג דער גאנצער היפה בנשים), מפני ששם כחשיכה כאורה בשני כפי\"ן לרמז שאף האור אינו תופס מקום<sup data-n=\"2333\">*133</sup> כידוע.",[["2324","125","<b>בבת (בבבת ) עינו של הקב\"ה</b>: ראה זכרי' ב, יב. מכילתא בשלח טו, ז. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' שלה."],["2325","126","<b>וכנ\"י. . זמן הגזירה עמדו במס\"נ</b>: ראה גם ש\"א צ, ב ובהערה 26."],["2326","127","<b>נכנס יין יצא סוד</b>: ערובין סה, סע\"א. ראה גם תו\"ח ויחי רלו, ב."],["2327","128","<b>אם לא תדע </b>[א: תדעי]<b> לך היפה בנשים</b>: שה\"ש א, ח. ראה גם בהערה הבאה."],["2328","129","<b>שהיפה בנשים גימט' תק\"ב</b>: ראה גם אוה\"ת שה\"ש ח\"א ע' קלו. ע' קלט. (כרך ג) ע' תתמו. ע' תתנח. סה\"מ תרכ\"ו ע' רג."],["2329","130","<b>יפ\"ת ויפ\"מ</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קסט וע' 11 ואילך. תו\"ח ויצא קעד, ג ואילך."],["2330","131","<b>שהז\"א בעל ט\"ס. . עולה רמ\"ח</b>: כ\"ה בהכת\"י. ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"ו. תו\"א מקץ לז, סע\"ד ואילך. שע\"ת מב, ב ובהערה 13."],["2331","*131","<b>יפ\"ת ויפ\"מ. . ובנפש. . המוחין</b>: ראה גם סה\"מ תרכ\"ז ע' קפט ואילך. מאמר ד\"ה להבין וכו' כל המועדים עתידין ליבטל פורים תשט\"ז. ובהנסמן בהנ\"ל."],["2332","132","<b>הגידה לי</b>: שה\"ש א, ז."],["2333","*133","<b>תופס מקום</b>: א: מאיר."]]],[4801940604,"ועכ\"ז יתפרש ענין הנ\"ל עבר על מצות ל\"ת שכבר פגם גם המוחי' שאין המוח שליט על הלב ויש לו טמטום המוח ג\"כ אזי התשובה שהוא בינה תולה כי ההתחלה צ\"ל ע\"י התבוננות אבל גמר הכפרה אינו מספיק לו בתשובה מאחר שפגם המוחין ג\"כ ואין לו תקנה רק שיעורר בחי' יוהכ\"פ שהוא הגורל שהוא הרצה\"פ לאלקי' כמו מס\"נ בכח כנ\"ל שהוא בחי' מקיף דחיה וממילא יעורר למעלה ג\"כ בחי' רצה\"פ שהוא רעדכ\"ר ומשם יומשך סליחת עוונות כנ\"ל, וכן בכ\"י יש בחי' בעבודה שהוא מעין יוהכ\"פ שהוא הגורל, והו\"ע קבעומ\"ש שקדם לעול מצות שהוא הנחת עצמותו לגמרי, והוא ביטול הרצון שמסלק ומניח גם בעל הרצון שלו מפני מקור הרצון שלמעלה וכמבואר באריכות ע\"פ והתגדלתי<sup data-n=\"2334\">133</sup>.\nז) <b>עבר</b> על כריתות ומב\"ד תשובה ויוהכ\"פ תולין ויסורין ממרקין, דהנה אף שלכאורה גם בכאן הוא פגם רק במוחי' שלא הי' מוח שליט על הלב ומדוע לא יועיל לו יוהכ\"פ כנ\"ל בעבר על ל\"ת, אך באמת על ל\"ת החמורים שיש בהם חיוב כרת ומב\"ד לא לבד שפגם המוחי' אף גם הרצה\"פ שבנפשו פגם ג\"כ, ולכן איתא שע\"י עריות הפגם בקוש\"י שהוא בחי' כתר<sup data-n=\"2335\">134</sup> (כי אדרבה על עוונת החמורים כ\"כ לא הי' צריך כ\"כ להשתמש במוחי' שלו<sup data-n=\"2336\">135</sup> לכבוש את המדות כי אין שייך רק בעבירות שאפשר להרוח שטות דקליפה לכסות ולהקל בו שבעבירה זו עודנו ביהדותו ואינו נפרד עדיין ע\"ז צריך העמקת הדעת להעביר את הרוח שטות דקליפה ולהתבונן איך שמאחר שהוא נגד רצה\"ע אפי' איסור קל של דקדוקי סופרים הוא גרוע יותר מע\"ז עצמה כמ\"ש בתניא באריכות<sup data-n=\"2337\">136</sup>, אבל על דבר שהוא חמור בעיני ההמון מאחר שעונשו חמור והוא דבר שבדל ממנו מנעוריו כמו עוונות חמורות כאלה, הנה ע\"ז לא יתכן שיצטרך להתבוננות עד<sup data-n=\"2338\">137</sup> שיכלא את הרוח שטות שבלבו, אדרבה החוש מעיד שאפי' בדבר שיש עונג בעצם רק מפני שהדבר נפלא ממנו מפני חשש סכנת נפש, לא יתעוררו המדות שבלב לחשוק זאת עד שיצטרך בשכלו לכבות את רשפי אש התשוקה, אע\"כ לומר שמאחר שחשק את העבירה זאת ולא מנעוהו סכנת העונש החמור, הנה הוא הוראה או שאינו מאמין בשכר ועונש, והו\"ע האפיקורסות שהפגם הוא בבחי' כתר שהו\"ע הפר\"ע שהוא כתר דקליפה כמבואר במ\"א ע\"פ והתגדלתי, או שהפקיר א\"ע בדרך עבדא בהפקירא ניחא לי'<sup data-n=\"2339\">138</sup> עד שעורר את הרצה\"פ דקליפה שבנפשו כעין גורל דהמן עד שאינו חושש אפי' אם יענש, בדרך יעבר עלי מה<sup data-n=\"2340\">139</sup>, ובמא' והתגדלתי הנ\"ל מבואר איך שגם האפיקורסות אינו רק הפקר ופר\"ע ולא שיבוש בדיעות כמבואר שם באריכות.",[["2334","133","<b>ע\"פ והתגדלתי</b>: לע\"ע נמצא רק הנחה מדברי ר\"ה ולא נדפסה לע\"ע."],["2335","134","<b>שע\"י עריות. . כתר</b>: ראה גם תו\"ח בשלח ח\"א רכט, א."],["2336","135","<b>שלו</b>: תוקן ע\"פ א."],["2337","136","<b>בתניא באריכות</b>: פכ\"ד."],["2338","137","<b>עד</b>: א: בהתפעלות גלוי עד."],["2339","138","<b>עבדא בהפקירא ניחא לי'</b>: גיטין יג, א."],["2340","139","<b>יעבר עלי מה</b>: ראה איוב יג, יג ובמפרשים שם. רד\"ק שמו\"ב יח, כג."]]],[4801940610,"והנה ע\"ז נא' והי' בשמעו את דברי האלה דהיינו כל הצ\"ח קללות<sup data-n=\"2341\">141</sup> הכתובים לעיל, והתברך<sup data-n=\"2342\">140</sup> שהוא מקור כל הברכות שהו\"ע כתר דקליפה לאמר שלום יהי' לי מפני שאינו מאמין בעונש, וזהו רק בדבור אומר כן כדרך כל המפקירים א\"ע שמתפאר בלשונו לאמר שלום כו', אבל בלבבו עושה הסכם גם על הצד השני, ולכן נא' ע\"ז לא יאבה הוי' סלוח לו<sup data-n=\"2343\">142</sup> דהיינו שהכתוב מפליג עד היכן הפגם שלו שפוגם ברצה\"פ שבנפשו וממילא לא יעורר למעלה בחי' רעדכ\"ר שמשם יומשך סליחת עוונות ביוה\"כ עכ\"י<sup data-n=\"2344\">143</sup> אפי' לפגם ל\"ת שהוא המוחין אבל מ\"מ מאחר שע\"י גורל שהוא מס\"נ ובעבודה הוא קבעומ\"ש מעורר בנפשו בחי' רצה\"פ וכן למעלה מעורר את בחי' רצה\"פ שהוא לפני הוי' שהוא התלבשות א\"ס בע\"ס ולכן משם תטהרו. אבל זה שפורק עומ\"ש בהפקירות הלא פוגם הוא גם את רצה\"פ שבנפשו וא\"כ לא יהי' רצון למעלה לסליחת עוונות כנ\"ל. וזהו לא יאבה ה' סלוח לו, ומ\"מ לא כתיב לא יסלח לו ה' כי באמת אין לך דבר שעומד בפני התשו'<sup data-n=\"2345\">144</sup> ואפי' הפר\"ע הנ\"ל רק שצריך לעורר תשו' עמוקה יותר דהיינו בחי' עתיקא דעתיקין שלמעלה מבחי' רעדכ\"ר כמו ע\"י תשובת ראב\"ד שא' שמים וארץ בקשו עלי רחמים<sup data-n=\"2346\">145</sup>, דהפי' שהלך בין שני הרים גדולים להיות ממארי דחושבנא<sup data-n=\"2347\">146</sup> ולפשפש כחות נפשו אולי נשארו אצלו כחות בלתי פגומים שלא השתמש בהם באיזה עבירה וממילא לא פגם למעלה באיזה ספי' עליונה, וידוע בשם הבעש\"ט ז\"ל שכשאני תופס בקצה מן האחדות<sup data-n=\"2348\">147</sup> הריני תופס בכולו, א\"כ יוכל מעתה לעורר בנפשו אותו הכח שלא פגם עדיין ויתדבק לאותה הספי' למעלה וממילא יתוקן הכל כנ\"ל.\n<b>וזהו</b> שמים וארץ שהם נו\"ה, חמה ולבנה ת\"ת ומל'<sup data-n=\"2349\">148</sup> שלכולם אמר בקשו עלי רחמים דהיינו כמו שמפרש בח\"א<sup data-n=\"2350\">149</sup> שאמר לעצמו והשיב לעצמו דהיינו שבדק ופשפש בעצמו בכל העשר כחות שלו שהם כדוגמת ע\"ס עליונות אולי נשאר אצלו איזה כח שלא פגם עדיין, והשיב לעצמו מקראות המורים על פגם הספי' המכוונים כנגד כחות נפשו שנשתלשלו משם כמו כי שמים כעשן נמלחו כו', שמפרש בת\"ז שקאי על זו\"נ דקליפה, דהיינו שנתן תוס' יניקה לשמים וארץ של ההיפוך, עד שאמר א\"כ אין הדבר תלוי אלא בי, דהיינו שלאחר שמצא שכל ציור קומת נפשו מכף רגלו ועד כו' אין בו מתום<sup data-n=\"2351\">150</sup>, אמר א\"כ לא נשתייר בו אלא נקודת",[["2341","141","<b>הצ\"ח קללות</b>: ראה גם רש\"י פינחס כט, יח. ר\"פ נצבים (מתנחומא שם)."],["2342","140","<b>והי' בשמעו את דברי האלה. . והתברך</b>: נצבים כט, יח."],["2343","142","<b>לא יאבה הוי' סלוח לו</b>: נצבים שם, יט."],["2344","143","<b>עכ\"י</b>: על כל ישראל."],["2345","144","<b>אין לך דבר שעומד בפני התשו'</b>: ראה תניא פכ\"ה. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. סה\"מ תש\"ט ע' 42 (הא') בהערה. לקו\"ש בא כרך ו ע' 66 הערה 54."],["2346","145","<b>ראב\"ד. . בקשו עלי רחמים</b>: ע\"ז יז, א."],["2347","146","<b>ממארי דחושבנא</b>: ראה זהר קרח קעח, א. תניא פכ\"ט."],["2348","147","<b>בשם הבעש\"ט ז\"ל שכשאני תופס בקצה מן האחדות</b>: ראה ספר השיחות תש\"א ע' 32 הערה 19. כתר שם טוב קה\"ת מהדורת תשנ\"ט סרכ\"ז. וש\"נ."],["2349","148","<b>חמה ולבנה ת\"ת ומל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ח מערכת חמה ופי\"ב מערכת לבנה."],["2350","149","<b>שמפרש בח\"א</b>: כ\"ה בהכת\"י. ראה ריטב\"א בע\"י כאן."],["2351","150","<b>מכף רגלו. . מתום</b>: ע\"פ ישעי' א, ו."]]],[4801940615,"עצם הנפש שהוא עצם היחידה שעז\"נ נשמה שנתת בי דייקא טהורה היא<sup data-n=\"2352\">151</sup>, שאף שקודם השינה אומר אם פגמתי<sup data-n=\"2353\">152</sup> בכל ד' אותיות הוי' שבנפשו מ\"מ נשמה שנתת בי דייקא שהוא עצם היחידה טהורה היא שאין שייך בה שום פגם, כי ע\"ז אינו בעל בחירה כלל כמו שאמרו אע\"פ שחטא ישראל הוא<sup data-n=\"2354\">153</sup> אפי' ישראל מומר, כי הבחירה לא ניתנה רק על גילויי הנשמה שאפשר לתקנם או לפגום אותם ח\"ו, אבל עצם הנשמה עז\"נ וחשב מחשבות לבלתי ידח ממנו נדח<sup data-n=\"2355\">154</sup>, כי סוף כל סוף עתידה להתברר בגלגול זו או בגלגול אחר, ועז\"נ והשיב את הגזילה<sup data-n=\"2356\">155</sup> בע\"כ, ולכן ע\"ד הפשוט הכוונה אלא בי ממש (בל\"א אין מיר „ליין) שהוא נקודת עצם הנפש כי על כל גילויי הנפש דרך האדם לומר שהוא שלו כמו שכלו ומדותיו ורצונו, ומכ\"ש לבושיו ואבריו, ומי הוא העצם שהכל שלו הוא העלם עצם המאור.\n<b>ולכן</b> מאחר שאין לו עצה אחרת רק לעורר עצם נקודת העלם המאור שאין שייך בו שום כלי וא\"א לעורר אותה רק על ידי ההעדר, ע\"ד כידוע מהבעש\"ט נ\"ע שהוא לאו שקודם להן<sup data-n=\"2357\">156</sup>, כי כשהאדם חושק לאיזה דבר אין זה רק גילוי והתפשטות מהנפש ולכן<sup data-n=\"2358\">157</sup> יוכל להיות שאוהב את האדם, וגם את מנגדו ושונאו, אבל מה שא\"א לו לסבול ההיפוך הוא נוגע לעצם הנפש, וכן עד\"ז בעבודת הצדיקים שיש לו אהבה לאלקות או אפי' תענוג אין זה רק גילוי הנפש האלקי' אבל ע\"י שמצער על ריחוקו שא\"א לו לסבול המנגד עי\"ז מעורר עצם העלם המאור, ולכן הכניס ראשו בין ברכיו שהוא כמו הולד בעודו בבטן אמו שאז הוא מקופל ומונח מפני שאז אין מאיר בו עדיין ציור אדם הפנימי, מחמת שאין החומר מוכשר עדיין לקבל צורת אור הנפש בפנימיותו רק מקיף כללי שהוא בחי' עיגולים שבנפש, ולכן גשמי' החומר שהוא כדוגמת הנפש השורה בו הוא ג\"כ ראשו בין ברכיו כעיגול להורות על ההשתוות שהראש עם שהוא נעלה במזיגתו לא יתקרב יותר לעצם השראת המקיף ושוה להרגל שהוא היותר נמוך בציור האדם ושניהם אינם מוכשרים לקבל אור הנפש הפשוט בדרך כלי לאור פנימי, ובדרך השראה ומקיף גם הרגל אינו נמנע להיות מקום להשראה זו, וגעה בבכי' בצער עמוק על הריחוק עד שנגע לעצם העלם היחידה עד שיצאה נשמתו<sup data-n=\"2359\">158</sup>.",[["2352","151","<b>נשמה שנתת בי. . טהורה היא</b>: ברכת אלקי נשמה (ברכות ס, ב)."],["2353","152","<b>שקודם השינה אומר אם פגמתי</b>: בק\"ש שעהמ\"ט (נוסח האריז\"ל)."],["2354","153","<b>אע\"פ שחטא ישראל הוא</b>: סנהדרין מד, א."],["2355","154","<b>וחשב מחשבות. . נדח</b>: שמו\"ב יד, יד."],["2356","155","<b>והשיב את הגזילה</b>: ויקרא ה, כג."],["2357","156","<b>מהבעש\"ט נ\"ע שהוא לאו שקודם להן</b>: ראה גם לעיל מאמר ד\"ה למנצח על השמינית הערה 77."],["2358","157","<b>ולכן</b>: א: אף שהצער הוא לפי ענין משקל ושב' קווין שקולין אבל הוא כמו המשקל דרך המאזניים שלפ\"ע המכביד בכף זו כן היא העלי' בכף שכנגדו נמצא העונג הוא המשכת הנפש והצער הוא עלי' והסתלקות וע\"כ נוגע לעצם ההעלם שלמע' מגדר גילוי, ולכן."],["2359","158","<b>נשמתו</b>: א ניתוסף: כי הוא הי' משורש נשמתו מאות' שאין בהם שוב אחר הרצוא כענין שמצינו בעבודת הצדיקים בדרך עונג כענין עונג אות' שבאידרא דעיילי ולא נפקי שיצאה נשמתם בערבות מתיקות וידידות כמבואר באוה\"ח על נדב ואביהו וכן הוא בעבודת הבעלי תשובה, אבל באמת צ\"ל שוב אחר הרצוא כמ\"ש במ\"א. . ישראל ואח\"כ ושובו אל הוי' ד'."]]],[4801940620,"ועז\"א שאם עבר על כריתות כו' שפגם בחי' הרצה\"פ שבנפש שעז\"א לא יאבה ה', וא\"כ אין יוהכ\"פ שהוא הגורל שבנפש מועיל כנ\"ל אז יסורין ממרקין שהו\"ע תיסרך רעתך כו'<sup data-n=\"2360\">159</sup> ודעי כי רע ומר עזבך<sup data-n=\"2361\">160</sup> כו', דהיינו טעימת מרירות בנפשו לעורר בחי' עתיקא דעתיקין שהו\"ע היחידה שישנה אפי' בקל שבקלים<sup data-n=\"2362\">161</sup>, ועכ\"ז לא נאמר מכפרין רק ממרקין שיש בזה ב' פירושים, א' לשון גמר<sup data-n=\"2363\">162</sup> כמו ומירק אחר על ידו<sup data-n=\"2364\">163</sup>, והב' לשון מריקה ושטיפה כמו ומורק ושוטף במים<sup data-n=\"2365\">164</sup>, כי מלבד שהיסורים שהוא טעימת החטא<sup data-n=\"2366\">165</sup> גומר כפרתו כנ\"ל, עכ\"ז עדיין עוד צריך לביטושים למרק ולטהר ולזכך את מוחו ולבו להיות כולם מוכשרים אח\"כ לתו' ומעש\"ט, כי מאחר שכבר פרק עומ\"ש לגמרי כענין והתברך כנ\"ל ולא הורגל לקבל עליו עול במוח ולב, הנה אם גם שע\"י המרירות יכנע לבו בשעת מעשה, עכ\"ז צריך עדיין לביטושים עד שיתרכך לבו להיות כלי מוכשר לקבלת עול תורה ועבודה בקביעות (כי אין זה דומה לב' מיני תשו' הקודמי' כנ\"ל בענין עבר על מ\"ע שהפגם במדות והתיקון ע\"י תשו' לעורר המוחי' ולתקן<sup data-n=\"2367\">166</sup> המדות מחדש, או בעבר על ל\"ת שהפגם במוחי' והתיקון ע\"י יוהכ\"פ שהוא הרצה\"פ כנ\"ל שעי\"ז נטהר המוח והלב, כי כ\"ז הם גילויי הנפש שמאירין בדרך אור וכלי וכשמעורר אור היותר גבוה הרי ממילא נתקן הבחי' התחתונה, אבל ע\"י היסורים שמעורר יחידה שבנפש שאין לה שום כלי בדרך קבלה בפנימי' הנה לא תוכל להאיר בקביעות כ\"א או שהנפש יסתלק כמו אצל ראב\"ד או שהמרירות תסתלק, וע\"כ יוכל ליפול ח\"ו) וע\"כ צריך עדיין לביטושים ושפלות<sup data-n=\"2368\">167</sup> עד שיכנע לבבו הערל לגמרי וירחץ מטומאתו ואז יוכל לקבל עול תורה ועבודה כנ\"ל.\nח) <b>והנה</b> אחר שנת' היטיב ענין ג' חילוקי כפרה הנ\"ל, יבואר ג\"כ הפלוגתא שבין הבבלי להירושלמי, ובירושלמי גופא ההפרש בין ר\"א לר' יהושע בענין כשנים, דהנה השני הוא חוט הלבן הצבוע בגוון אדום שגוון האדום מורה על החטא כמ\"ש עשו הוא אדום<sup data-n=\"2369\">168</sup>, או מדוע אדום ללבושיך<sup data-n=\"2370\">169</sup>, והתולע הוא עצם הרע, שהוא עצם האדמימות שבו צובעין<sup data-n=\"2371\">170</sup>, והנה לפי הבבלי הגוון אדום מורה על פגם המדות (שהמדות הם גווני הנפש כמבואר בענין ססגונא ששש בגוונין<sup data-n=\"2372\">171</sup> ), והמוחין נק' עצם לגבי המדות, ולכן מפרש שאם יהיו חטאיכם רק כשנים שהעצם הוא לבן רק הגוון",[["2360","159","<b>תייסרך רעתך כו'</b>: שם: ליתא."],["2361","160","<b>תייסרך. . ודעי כי רע ומר עזבך</b>: ירמי' ב, יט [בדילוג]."],["2362","161","<b>בקל שבקלים</b>: ע\"פ ר\"ה כה, ב. תוספתא שם ספ\"א. קה\"ר פ\"א ד [ד]. רש\"י ויצא כט, יא."],["2363","162","<b>ממרקין. . לשון גמר</b>: להעיר מערוך מערכת מרק הא'."],["2364","163","<b>ומירק אחר על ידו</b>: א: ומירק אחר שחיטה — ראה יומא לא, ב (במשנה)."],["2365","164","<b>ומורק ושוטף במים</b>: צו ו, כא. ראה גם אוה\"ת ואתחנן כרך ו ע' ב'רנט. ס\"ע ב'רס. וראה גם אגה\"ת פ\"א."],["2366","165","<b>החטא</b>: א: מרירות החטא."],["2367","166","<b>ולתקן</b>: שם: ולהוליד."],["2368","167","<b>ח\"ו) וע\"כ צריך. . ושפלות</b>: שם: ח\"ו ולחזור לסורו וכמו ששמעתי בשם ראיב\"ד ( ) ע\"פ אם ללצים הוא יליץ שפי' הוא על האהבה מסותרת לפרקים תתעלם ממנו והי' כלא הי' והעיקר מחמת שהוא לץ שהוא הפר\"ע כמבואר בד\"ח ושפלות."],["2369","168","<b>עשו הוא אדום</b>: וישלח לו, א."],["2370","169","<b>מדוע אדום ללבושיך</b>: ישעי' סג, ב."],["2371","170","<b>והתולע. . שבו צובעין</b>: ראה רש\"י ישעי' א, יח. רמב\"ם הל' פרה אדומה פ\"ג, ה\"ב. הל' כלי המקדש פ\"ח, הי\"ג."],["2372","171","<b>ססגונא ששש בגוונין</b>: שבת כח, א. ראה גם מאמרי אדה\"א במדבר ח\"א ע' קעב וע' קפ."]]]]});
